import type { BankQuestion } from "@/lib/bank";

/** Rivers of India (Geography): 214 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"geo-indian-rivers-1","question":"Which is the longest river flowing in India?","options":["Godavari","Ganga","Brahmaputra","Yamuna"],"answer":1,"explanation":"The Ganga flows about 2,525 km within India, the longest of any river in the country.","difficulty":"easy","questionHi":"भारत में बहने वाली सबसे लंबी नदी कौन-सी है?","optionsHi":["गोदावरी","गंगा","ब्रह्मपुत्र","यमुना"],"explanationHi":"गंगा भारत के भीतर लगभग 2,525 किमी बहती है, जो देश की किसी भी नदी से सबसे लंबी है।"},
  {"id":"geo-indian-rivers-2","question":"The Ganga originates from the:","options":["Yamunotri glacier","Gangotri glacier","Mansarovar lake","Amarkantak plateau"],"answer":1,"explanation":"The Bhagirathi rises at Gaumukh, Gangotri glacier, and becomes the Ganga after meeting the Alaknanda at Devprayag.","difficulty":"easy","questionHi":"गंगा का उद्गम कहाँ से होता है?","optionsHi":["यमुनोत्री हिमनद","गंगोत्री हिमनद","मानसरोवर झील","अमरकंटक पठार"],"explanationHi":"भागीरथी गंगोत्री हिमनद के गौमुख से निकलती है और देवप्रयाग में अलकनंदा से मिलने के बाद गंगा कहलाती है।"},
  {"id":"geo-indian-rivers-3","question":"Which river flows through Delhi?","options":["Ganga","Yamuna","Sutlej","Chambal"],"answer":1,"explanation":"The Yamuna, the largest tributary of the Ganga, flows through Delhi.","difficulty":"easy","questionHi":"कौन-सी नदी दिल्ली से होकर बहती है?","optionsHi":["गंगा","यमुना","सतलुज","चंबल"],"explanationHi":"गंगा की सबसे बड़ी सहायक नदी यमुना दिल्ली से होकर बहती है।"},
  {"id":"geo-indian-rivers-4","question":"Which of these rivers flows westward into the Arabian Sea?","options":["Godavari","Krishna","Narmada","Mahanadi"],"answer":2,"explanation":"The Narmada flows west through a rift valley into the Arabian Sea; the others drain into the Bay of Bengal.","difficulty":"moderate","questionHi":"इनमें से कौन-सी नदी पश्चिम की ओर बहकर अरब सागर में गिरती है?","optionsHi":["गोदावरी","कृष्णा","नर्मदा","महानदी"],"explanationHi":"नर्मदा भ्रंश घाटी से होकर पश्चिम की ओर बहती हुई अरब सागर में गिरती है; शेष नदियाँ बंगाल की खाड़ी में गिरती हैं।"},
  {"id":"geo-indian-rivers-5","question":"Which river is known as the “Dakshin Ganga”?","options":["Kaveri","Godavari","Krishna","Tungabhadra"],"answer":1,"explanation":"The Godavari, the longest peninsular river, is called the Dakshin Ganga.","difficulty":"moderate","questionHi":"किस नदी को “दक्षिण गंगा” कहा जाता है?","optionsHi":["कावेरी","गोदावरी","कृष्णा","तुंगभद्रा"],"explanationHi":"प्रायद्वीपीय भारत की सबसे लंबी नदी गोदावरी को दक्षिण गंगा कहा जाता है।"},
  {"id":"geo-indian-rivers-6","question":"The Narmada originates from the:","options":["Amarkantak plateau","Trimbakeshwar hills","Mahabaleshwar","Gangotri glacier"],"answer":0,"explanation":"The Narmada rises at the Amarkantak plateau (Anuppur, Madhya Pradesh), which also feeds the Son. Trimbakeshwar is the source of the Godavari and Mahabaleshwar of the Krishna, the two usual traps.","difficulty":"moderate","questionHi":"नर्मदा का उद्गम कहाँ से होता है?","optionsHi":["अमरकंटक पठार","त्र्यंबकेश्वर की पहाड़ियाँ","महाबलेश्वर","गंगोत्री हिमनद"],"explanationHi":"नर्मदा अमरकंटक पठार (अनूपपुर, मध्य प्रदेश) से निकलती है, जहाँ से सोन नदी भी निकलती है। त्र्यंबकेश्वर गोदावरी का और महाबलेश्वर कृष्णा का उद्गम है; ये दोनों प्रायः भ्रम के कारण बनते हैं।"},
  {"id":"geo-indian-rivers-7","question":"The Brahmaputra is known by which name in Tibet?","options":["Tsangpo","Dihang","Jamuna","Burhi Dihing"],"answer":0,"explanation":"It is the (Yarlung) Tsangpo in Tibet, the Dihang/Siang in Arunachal Pradesh and the Jamuna in Bangladesh. The Burhi Dihing is only a south-bank tributary in Assam.","difficulty":"hard","questionHi":"ब्रह्मपुत्र तिब्बत में किस नाम से जानी जाती है?","optionsHi":["सांगपो","दिहांग","जमुना","बूढ़ी दिहिंग"],"explanationHi":"तिब्बत में इसे (यारलुंग) सांगपो, अरुणाचल प्रदेश में दिहांग/सियांग और बांग्लादेश में जमुना कहा जाता है। बूढ़ी दिहिंग असम में केवल दक्षिणी तट की एक सहायक नदी है।"},
  {"id":"geo-indian-rivers-8","question":"Hirakud Dam is built on which river?","options":["Godavari","Mahanadi","Sutlej","Krishna"],"answer":1,"explanation":"Hirakud, near Sambalpur in Odisha, dams the Mahanadi and is one of the longest earthen dams in the world. The Godavari has Polavaram and the Sutlej has Bhakra, so those are wrong.","difficulty":"hard","questionHi":"हीराकुड बाँध किस नदी पर बना है?","optionsHi":["गोदावरी","महानदी","सतलुज","कृष्णा"],"explanationHi":"ओडिशा में संबलपुर के निकट स्थित हीराकुड, महानदी पर बना है और विश्व के सबसे लंबे मिट्टी के बाँधों में से एक है। गोदावरी पर पोलावरम और सतलुज पर भाखड़ा है, इसलिए वे विकल्प गलत हैं।"},
  {"id":"geo-indian-rivers-9","question":"Bhakra Nangal Dam is built on which river?","options":["Beas","Ravi","Sutlej","Chenab"],"answer":2,"explanation":"Bhakra Dam, on the Sutlej in Himachal Pradesh, is one of the highest gravity dams in the world.","difficulty":"hard","questionHi":"भाखड़ा नांगल बाँध किस नदी पर बना है?","optionsHi":["ब्यास","रावी","सतलुज","चेनाब"],"explanationHi":"हिमाचल प्रदेश में सतलुज पर बना भाखड़ा बाँध विश्व के सबसे ऊँचे गुरुत्व बाँधों में से एक है।"},
  {"id":"geo-indian-rivers-10","question":"Which river is known as the “Sorrow of Bihar”?","options":["Gandak","Kosi","Son","Ghaghara"],"answer":1,"explanation":"The Kosi brings huge silt loads from Nepal and has shifted its course westward by over 100 km, flooding north Bihar almost every year. Do not confuse it with the Damodar, the old Sorrow of Bengal.","difficulty":"very-hard","questionHi":"किस नदी को “बिहार का शोक” कहा जाता है?","optionsHi":["गंडक","कोसी","सोन","घाघरा"],"explanationHi":"कोसी नेपाल से भारी मात्रा में गाद लाती है और अपना मार्ग पश्चिम की ओर 100 किमी से अधिक बदल चुकी है, जिससे उत्तरी बिहार में लगभग हर वर्ष बाढ़ आती है। इसे दामोदर से न मिलाएँ, जो पहले “बंगाल का शोक” कहलाती थी।"},
  {"id":"geo-indian-rivers-11","question":"The Sardar Sarovar Dam is built on which river?","options":["Tapi","Narmada","Mahi","Sabarmati"],"answer":1,"explanation":"Sardar Sarovar at Kevadia in Gujarat is the terminal major dam on the Narmada. The Tapi (Ukai dam) and the Mahi (Kadana dam) also flow west through Gujarat, which makes them the tempting wrong picks.","difficulty":"very-hard","questionHi":"सरदार सरोवर बाँध किस नदी पर बना है?","optionsHi":["ताप्ती","नर्मदा","माही","साबरमती"],"explanationHi":"गुजरात के केवड़िया में स्थित सरदार सरोवर, नर्मदा का अंतिम प्रमुख बाँध है। ताप्ती (उकाई बाँध) और माही (कडाना बाँध) भी गुजरात से होकर पश्चिम की ओर बहती हैं, इसीलिए वे भ्रमित करने वाले गलत विकल्प बनते हैं।"},
  {"id":"geo-indian-rivers-12","question":"Which of these rivers does NOT originate in India?","options":["Godavari","Subarnarekha","Brahmaputra","Mahanadi"],"answer":2,"explanation":"The Brahmaputra rises in the Chemayungdung glacier near Mansarovar in Tibet. The Godavari, Subarnarekha and Mahanadi all rise on Indian plateaus (Trimbakeshwar, near Ranchi and Sihawa).","difficulty":"very-hard","questionHi":"इनमें से कौन-सी नदी भारत में नहीं निकलती?","optionsHi":["गोदावरी","सुवर्णरेखा","ब्रह्मपुत्र","महानदी"],"explanationHi":"ब्रह्मपुत्र तिब्बत में मानसरोवर के निकट चेमायुंगडुंग हिमनद से निकलती है। गोदावरी, सुवर्णरेखा और महानदी, तीनों भारतीय पठारों (त्र्यंबकेश्वर, राँची के निकट और सिहावा) से निकलती हैं।"},
  {"id":"geo-indian-rivers-13","question":"The longest river flowing entirely within India is the:","options":["Ganga","Godavari","Krishna","Brahmaputra"],"answer":1,"explanation":"The Godavari (about 1,465 km) is the longest river wholly within India. The Ganga and the Brahmaputra are longer overall, but parts of their courses lie in Bangladesh (and Tibet for the Brahmaputra).","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"पूरी तरह भारत के भीतर बहने वाली सबसे लंबी नदी कौन-सी है?","optionsHi":["गंगा","गोदावरी","कृष्णा","ब्रह्मपुत्र"],"explanationHi":"गोदावरी (लगभग 1,465 किमी) पूरी तरह भारत के भीतर बहने वाली सबसे लंबी नदी है। गंगा और ब्रह्मपुत्र कुल मिलाकर अधिक लंबी हैं, किंतु उनके मार्ग का कुछ भाग बांग्लादेश में (और ब्रह्मपुत्र का तिब्बत में) है।"},
  {"id":"geo-indian-rivers-14","question":"Which river forms the Jog (Gersoppa) Falls?","options":["Kaveri","Sharavathi","Periyar","Tungabhadra"],"answer":1,"explanation":"The Sharavathi plunges about 253 m at Jog Falls in Shivamogga district, Karnataka, before entering the Arabian Sea at Honnavar. The Tungabhadra is the tempting guess, but it is east-flowing and forms no such fall.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कौन-सी नदी जोग (गेरसोप्पा) जलप्रपात बनाती है?","optionsHi":["कावेरी","शरावती","पेरियार","तुंगभद्रा"],"explanationHi":"शरावती, कर्नाटक के शिवमोगा जिले में जोग जलप्रपात पर लगभग 253 मी नीचे गिरती है और फिर होन्नावर में अरब सागर में प्रवेश करती है। तुंगभद्रा का अनुमान भ्रामक है, क्योंकि वह पूर्व की ओर बहती है और ऐसा कोई प्रपात नहीं बनाती।"},
  {"id":"geo-indian-rivers-15","question":"The Prakasam Barrage at Vijayawada in Andhra Pradesh is built across the:","options":["Godavari","Krishna","Penna","Tungabhadra"],"answer":1,"explanation":"The Prakasam Barrage spans the Krishna at Vijayawada and feeds the canals of the Krishna delta. The Godavari is barraged at Dowleswaram near Rajamahendravaram, and the Tungabhadra is a tributary dammed at Hosapete in Karnataka.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"आंध्र प्रदेश में विजयवाड़ा स्थित प्रकाशम बैराज किस नदी पर बना है?","optionsHi":["गोदावरी","कृष्णा","पेन्ना","तुंगभद्रा"],"explanationHi":"प्रकाशम बैराज विजयवाड़ा में कृष्णा नदी पर बना है और कृष्णा डेल्टा की नहरों को पानी देता है। गोदावरी पर राजमहेंद्रवरम के पास धवलेश्वरम में बैराज है, और तुंगभद्रा एक सहायक नदी है जिस पर कर्नाटक के होसपेटे में बाँध बना है।"},
  {"id":"geo-indian-rivers-16","question":"The Luni, the main river of the Thar region that ends in the Rann of Kutch, rises in the:","options":["Aravalli range near Ajmer","Thar desert near Jaisalmer","Vindhya range near Bhopal","Malwa plateau near Indore"],"answer":0,"explanation":"The Luni rises in the Pushkar valley of the Aravallis near Ajmer and flows south-west across western Rajasthan to the Rann of Kutch. The Vindhyas and the Malwa plateau give rise to rivers such as the Betwa and the Chambal instead.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"थार क्षेत्र की प्रमुख नदी लूनी, जो कच्छ के रण में समाप्त होती है, कहाँ से निकलती है?","optionsHi":["अजमेर के पास अरावली पर्वतमाला","जैसलमेर के पास थार मरुस्थल","भोपाल के पास विंध्य पर्वतमाला","इंदौर के पास मालवा पठार"],"explanationHi":"लूनी अजमेर के पास अरावली की पुष्कर घाटी से निकलती है और पश्चिमी राजस्थान से दक्षिण-पश्चिम दिशा में बहते हुए कच्छ के रण तक जाती है। विंध्य और मालवा पठार से बेतवा और चंबल जैसी नदियाँ निकलती हैं।"},
  {"id":"geo-indian-rivers-17","question":"The Pong dam, whose reservoir Maharana Pratap Sagar is a Ramsar wetland, is built on the:","options":["Ravi","Beas","Sutlej","Chenab"],"answer":1,"explanation":"The Pong dam in Kangra district of Himachal Pradesh impounds the Beas. Bhakra is on the Sutlej, Ranjit Sagar (Thein) on the Ravi, and Salal and Baglihar on the Chenab.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"पोंग बाँध, जिसका जलाशय महाराणा प्रताप सागर एक रामसर आर्द्रभूमि है, किस नदी पर बना है?","optionsHi":["रावी","ब्यास","सतलुज","चेनाब"],"explanationHi":"हिमाचल प्रदेश के कांगड़ा ज़िले में स्थित पोंग बाँध ब्यास नदी पर है। भाखड़ा सतलुज पर, रणजीत सागर (थीन) रावी पर, और सलाल व बगलिहार चेनाब पर हैं।"},
  {"id":"geo-indian-rivers-18","question":"The Indus Waters Treaty (1960) gives India unrestricted use of which three rivers?","options":["Indus, Jhelum, Chenab","Ravi, Beas, Sutlej","Jhelum, Ravi, Beas","Indus, Chenab, Sutlej"],"answer":1,"explanation":"The eastern rivers (Ravi, Beas, Sutlej) went to India; the western ones (Indus, Jhelum, Chenab) to Pakistan.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"सिंधु जल संधि (1960) भारत को किन तीन नदियों के अप्रतिबंधित उपयोग का अधिकार देती है?","optionsHi":["सिंधु, झेलम, चेनाब","रावी, ब्यास, सतलुज","झेलम, रावी, ब्यास","सिंधु, चेनाब, सतलुज"],"explanationHi":"पूर्वी नदियाँ (रावी, ब्यास, सतलुज) भारत को मिलीं; पश्चिमी नदियाँ (सिंधु, झेलम, चेनाब) पाकिस्तान को।"},
  {"id":"geo-indian-rivers-19","question":"Which of these is NOT part of the Ganga river system?","options":["Chambal","Betwa","Ramganga","Mahanadi"],"answer":3,"explanation":"Chambal and Betwa join the Yamuna and the Ramganga joins the Ganga near Kannauj, so all three belong to the Ganga system. The Mahanadi drains independently into the Bay of Bengal.","difficulty":"hard","questionHi":"इनमें से कौन-सी गंगा नदी तंत्र का भाग नहीं है?","optionsHi":["चंबल","बेतवा","रामगंगा","महानदी"],"explanationHi":"चंबल और बेतवा यमुना में मिलती हैं तथा रामगंगा कन्नौज के निकट गंगा में मिलती है, इसलिए तीनों गंगा तंत्र की हैं। महानदी स्वतंत्र रूप से बंगाल की खाड़ी में गिरती है।"},
  {"id":"geo-indian-rivers-20","question":"The Betwa, which rises in the Vindhyas near Bhopal, joins the Yamuna near:","options":["Etawah","Hamirpur","Prayagraj","Agra"],"answer":1,"explanation":"The Betwa flows north-east through Bundelkhand, past Orchha, and meets the Yamuna at Hamirpur in Uttar Pradesh. Agra and Etawah lie upstream on the Yamuna, and Prayagraj is where the Yamuna itself meets the Ganga.","difficulty":"hard","questionHi":"विंध्य पर्वतमाला में भोपाल के पास से निकलने वाली बेतवा नदी यमुना से कहाँ के पास मिलती है?","optionsHi":["इटावा","हमीरपुर","प्रयागराज","आगरा"],"explanationHi":"बेतवा बुंदेलखंड से होकर, ओरछा के पास से, उत्तर-पूर्व की ओर बहती है और उत्तर प्रदेश के हमीरपुर में यमुना से मिलती है। आगरा और इटावा यमुना पर इससे ऊपर की ओर हैं, और प्रयागराज वह स्थान है जहाँ यमुना स्वयं गंगा से मिलती है।"},
  {"id":"geo-indian-rivers-21","question":"Arrange these east-flowing rivers from north to south:","options":["Mahanadi, Godavari, Krishna, Kaveri","Godavari, Mahanadi, Krishna, Kaveri","Mahanadi, Krishna, Godavari, Kaveri","Godavari, Krishna, Mahanadi, Kaveri"],"answer":0,"explanation":"Mahanadi (Odisha), Godavari (Andhra/Telangana), Krishna, then Kaveri (Tamil Nadu).","difficulty":"very-hard","questionHi":"इन पूर्व की ओर बहने वाली नदियों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए:","optionsHi":["महानदी, गोदावरी, कृष्णा, कावेरी","गोदावरी, महानदी, कृष्णा, कावेरी","महानदी, कृष्णा, गोदावरी, कावेरी","गोदावरी, कृष्णा, महानदी, कावेरी"],"explanationHi":"महानदी (ओडिशा), गोदावरी (आंध्र प्रदेश/तेलंगाना), कृष्णा, फिर कावेरी (तमिलनाडु)।"},
  {"id":"geo-indian-rivers-22","question":"The Tehri dam stands near the confluence of:","options":["Alaknanda and Bhagirathi","Bhagirathi and Bhilangana","Alaknanda and Mandakini","Bhagirathi and Jadh Ganga"],"answer":1,"explanation":"Tehri dam is on the Bhagirathi near its confluence with the Bhilangana. Alaknanda and Bhagirathi meet at Devprayag, Alaknanda and Mandakini at Rudraprayag, and the Jadh Ganga joins far upstream near Bhaironghati.","difficulty":"very-hard","questionHi":"टिहरी बाँध किनके संगम के निकट स्थित है?","optionsHi":["अलकनंदा और भागीरथी","भागीरथी और भिलंगना","अलकनंदा और मंदाकिनी","भागीरथी और जाध गंगा"],"explanationHi":"टिहरी बाँध भागीरथी पर, भिलंगना के साथ उसके संगम के निकट है। अलकनंदा और भागीरथी देवप्रयाग में, अलकनंदा और मंदाकिनी रुद्रप्रयाग में मिलती हैं, और जाध गंगा बहुत ऊपर भैरोंघाटी के निकट मिलती है।"},
  {"id":"geo-indian-rivers-23","question":"How many of these statements are correct? I. The Godavari is called the “Dakshin Ganga”. II. The Krishna rises near Mahabaleshwar. III. The Kaveri rises at Talakaveri in the Brahmagiri hills. IV. The Mahanadi rises in the Western Ghats.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Mahanadi rises near Sihawa in Chhattisgarh.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. गोदावरी को “दक्षिण गंगा” कहा जाता है। II. कृष्णा महाबलेश्वर के निकट से निकलती है। III. कावेरी ब्रह्मगिरि पहाड़ियों में तालकावेरी से निकलती है। IV. महानदी पश्चिमी घाट से निकलती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। महानदी छत्तीसगढ़ में सिहावा के निकट से निकलती है।"},
  {"id":"geo-indian-rivers-24","question":"How many of these statements are correct? I. The Indus rises in Tibet near Lake Mansarovar. II. The Sutlej enters India through the Shipki La pass. III. The Chenab is formed by the Chandra and the Bhaga.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"The Indus rises near Mansarovar, the Sutlej enters India at Shipki La in Himachal Pradesh, and the Chandra and Bhaga meet at Tandi to form the Chenab, so all three are true.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. सिंधु मानसरोवर झील के निकट तिब्बत से निकलती है। II. सतलुज शिपकी ला दर्रे से भारत में प्रवेश करती है। III. चेनाब का निर्माण चंद्र और भागा के मिलने से होता है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"सिंधु मानसरोवर के निकट से निकलती है, सतलुज हिमाचल प्रदेश में शिपकी ला से भारत में प्रवेश करती है, और चंद्र तथा भागा तांदी में मिलकर चेनाब बनाती हैं, इसलिए तीनों सही हैं।"},
  {"id":"geo-indian-rivers-25","question":"How many of these statements are correct? I. The Narmada flows through a rift valley. II. The Tapi rises in the Maikal range near Amarkantak. III. The Mahi drains into the Gulf of Kutch.","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only I is correct. The Tapi rises in the Satpura range near Multai (Amarkantak is the source of the Narmada), and the Mahi, after crossing the Tropic of Cancer twice, drains into the Gulf of Khambhat.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. नर्मदा भ्रंश घाटी से होकर बहती है। II. ताप्ती अमरकंटक के निकट मैकाल श्रेणी से निकलती है। III. माही कच्छ की खाड़ी में गिरती है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I सही है। ताप्ती मुलताई के निकट सतपुड़ा श्रेणी से निकलती है (अमरकंटक नर्मदा का उद्गम है), और माही कर्क रेखा को दो बार पार करने के बाद खंभात की खाड़ी में गिरती है।"},
  {"id":"geo-indian-rivers-26","question":"Arrange these tributaries of the Indus from north to south: 1. Jhelum 2. Ravi 3. Chenab 4. Sutlej","options":["1-3-2-4","1-2-3-4","3-1-2-4","1-3-4-2"],"answer":0,"explanation":"North to south the Punjab rivers run Jhelum, Chenab, Ravi, Beas, Sutlej (J-C-R-B-S). The order 1-2-3-4 is the trap of putting the Ravi above the Chenab.","difficulty":"very-hard","questionHi":"सिंधु की इन सहायक नदियों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए: 1. झेलम 2. रावी 3. चेनाब 4. सतलुज","optionsHi":["1-3-2-4","1-2-3-4","3-1-2-4","1-3-4-2"],"explanationHi":"उत्तर से दक्षिण पंजाब की नदियाँ झेलम, चेनाब, रावी, ब्यास, सतलुज (J-C-R-B-S) के क्रम में हैं। 1-2-3-4 क्रम रावी को चेनाब के ऊपर रखने की भूल है।"},
  {"id":"geo-indian-rivers-27","question":"The Ganga is formed by the confluence of the Bhagirathi and the Alaknanda at:","options":["Devprayag","Rudraprayag","Karnaprayag","Vishnuprayag"],"answer":0,"explanation":"At Devprayag. Rudraprayag joins the Mandakini, Karnaprayag the Pindar and Vishnuprayag the Dhauliganga with the Alaknanda.","difficulty":"very-hard","questionHi":"भागीरथी और अलकनंदा के संगम से गंगा का निर्माण कहाँ होता है?","optionsHi":["देवप्रयाग","रुद्रप्रयाग","कर्णप्रयाग","विष्णुप्रयाग"],"explanationHi":"देवप्रयाग में। रुद्रप्रयाग में अलकनंदा से मंदाकिनी, कर्णप्रयाग में पिंडर और विष्णुप्रयाग में धौलीगंगा मिलती है।"},
  {"id":"geo-indian-rivers-28","question":"Which pair of river and tributary is NOT correctly matched?","options":["Krishna – Tungabhadra","Godavari – Pranhita","Kaveri – Kabini","Mahanadi – Indravati"],"answer":3,"explanation":"The Indravati joins the Godavari, like the Pranhita. The main tributaries of the Mahanadi are the Seonath, Ib, Tel and Jonk; the Tungabhadra (Krishna) and Kabini (Kaveri) are correctly matched.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"नदी और सहायक नदी का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["कृष्णा – तुंगभद्रा","गोदावरी – प्राणहिता","कावेरी – काबिनी","महानदी – इंद्रावती"],"explanationHi":"इंद्रावती गोदावरी में मिलती है, जैसे प्राणहिता। महानदी की मुख्य सहायक नदियाँ शिवनाथ, इब, तेल और जोंक हैं; तुंगभद्रा (कृष्णा) और काबिनी (कावेरी) सही सुमेलित हैं।"},
  {"id":"geo-indian-rivers-29","question":"How many of these statements are correct? I. The Luni ends in the Rann of Kutch. II. The Damodar is a tributary of the Hugli. III. The Brahmaputra is called the Dihang in Arunachal Pradesh. IV. The Sabarmati flows into the Gulf of Khambhat.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: the Luni ends in the Rann of Kutch, the Damodar joins the Hugli, the Brahmaputra is the Dihang in Arunachal Pradesh, and the Sabarmati drains into the Gulf of Khambhat.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. लूनी कच्छ के रण में समाप्त होती है। II. दामोदर हुगली की सहायक नदी है। III. ब्रह्मपुत्र को अरुणाचल प्रदेश में दिहांग कहा जाता है। IV. साबरमती खंभात की खाड़ी में गिरती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: लूनी कच्छ के रण में समाप्त होती है, दामोदर हुगली में मिलती है, ब्रह्मपुत्र अरुणाचल प्रदेश में दिहांग है, और साबरमती खंभात की खाड़ी में गिरती है।"},
  {"id":"geo-indian-rivers-30","question":"The Nagarjuna Sagar dam is built on the river:","options":["Godavari","Krishna","Kaveri","Mahanadi"],"answer":1,"explanation":"Nagarjuna Sagar, on the Krishna between Telangana and Andhra Pradesh, was one of the earliest large multipurpose projects of independent India. Srisailam is also on the Krishna.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"नागार्जुन सागर बाँध किस नदी पर बना है?","optionsHi":["गोदावरी","कृष्णा","कावेरी","महानदी"],"explanationHi":"तेलंगाना और आंध्र प्रदेश के बीच कृष्णा पर स्थित नागार्जुन सागर, स्वतंत्र भारत की आरंभिक बड़ी बहुउद्देशीय परियोजनाओं में से एक था। श्रीशैलम भी कृष्णा पर है।"},
  {"id":"geo-indian-rivers-31","question":"The Yamuna rises from the:","options":["Gangotri glacier","Yamunotri glacier","Satopanth glacier","Siachen glacier"],"answer":1,"explanation":"The Yamuna starts from the Yamunotri glacier on the Banderpunch range in Uttarakhand and joins the Ganga at Prayagraj (Allahabad).","difficulty":"easy","source":"SSC CHSL · UPSSSC PET","questionHi":"यमुना का उद्गम कहाँ से होता है?","optionsHi":["गंगोत्री हिमनद","यमुनोत्री हिमनद","सतोपंथ हिमनद","सियाचिन हिमनद"],"explanationHi":"यमुना उत्तराखंड में बंदरपूँछ श्रेणी के यमुनोत्री हिमनद से निकलती है और प्रयागराज (इलाहाबाद) में गंगा से मिलती है।"},
  {"id":"geo-indian-rivers-32","question":"Lucknow, the capital of Uttar Pradesh, stands on the bank of the river:","options":["Ganga","Gomti","Ghaghara","Sarayu"],"answer":1,"explanation":"The Gomti, a sluggish left-bank tributary of the Ganga rising from Gomat Taal near Pilibhit, flows through Lucknow and Jaunpur.","difficulty":"easy","source":"SSC CGL · UPSSSC PET","questionHi":"उत्तर प्रदेश की राजधानी लखनऊ किस नदी के तट पर स्थित है?","optionsHi":["गंगा","गोमती","घाघरा","सरयू"],"explanationHi":"गोमती, गंगा की एक धीमी गति से बहने वाली बाएँ तट की सहायक नदी है, जो पीलीभीत के निकट गोमत ताल से निकलकर लखनऊ और जौनपुर से होकर बहती है।"},
  {"id":"geo-indian-rivers-33","question":"The Chambal, a tributary of the Yamuna, rises from the:","options":["Janapav hills near Mhow","Amarkantak plateau","Aravalli hills near Udaipur","Vindhya range near Bhopal"],"answer":0,"explanation":"The Chambal rises at Janapav in the Vindhya range near Mhow, flows through Rajasthan (Gandhi Sagar, Rana Pratap Sagar and Kota barrage) and joins the Yamuna in Uttar Pradesh; it is famous for its ravines.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"यमुना की सहायक नदी चंबल का उद्गम कहाँ से होता है?","optionsHi":["महू के निकट जानापाव की पहाड़ियाँ","अमरकंटक पठार","उदयपुर के निकट अरावली की पहाड़ियाँ","भोपाल के निकट विंध्य श्रेणी"],"explanationHi":"चंबल महू के निकट विंध्य श्रेणी में जानापाव से निकलती है, राजस्थान (गांधी सागर, राणा प्रताप सागर और कोटा बैराज) से होकर बहती है और उत्तर प्रदेश में यमुना से मिलती है; यह अपने बीहड़ों के लिए प्रसिद्ध है।"},
  {"id":"geo-indian-rivers-34","question":"Which peninsular river rises at Amarkantak and flows NORTH to join the Ganga as a right-bank tributary near Patna?","options":["Narmada","Son","Betwa","Ken"],"answer":1,"explanation":"The Son rises on the Amarkantak plateau, like the Narmada, but flows north-east and joins the Ganga near Danapur; the Betwa and Ken are tributaries of the Yamuna.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"कौन-सी प्रायद्वीपीय नदी अमरकंटक से निकलकर उत्तर की ओर बहती है और पटना के निकट गंगा में दाएँ तट की सहायक नदी के रूप में मिलती है?","optionsHi":["नर्मदा","सोन","बेतवा","केन"],"explanationHi":"सोन अमरकंटक पठार से निकलती है, नर्मदा की तरह, किंतु उत्तर-पूर्व की ओर बहकर दानापुर के निकट गंगा में मिलती है; बेतवा और केन यमुना की सहायक नदियाँ हैं।"},
  {"id":"geo-indian-rivers-35","question":"The Mettur dam, one of the oldest large dams in India (1934), is built on the:","options":["Krishna","Periyar","Kaveri","Vaigai"],"answer":2,"explanation":"Mettur dam in Salem district, Tamil Nadu, impounds the Kaveri as the Stanley reservoir and irrigates the Kaveri delta.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"भारत के सबसे पुराने बड़े बाँधों में से एक मेट्टूर बाँध (1934) किस नदी पर बना है?","optionsHi":["कृष्णा","पेरियार","कावेरी","वैगई"],"explanationHi":"तमिलनाडु के सेलम जिले में स्थित मेट्टूर बाँध स्टेनली जलाशय के रूप में कावेरी को रोकता है और कावेरी डेल्टा की सिंचाई करता है।"},
  {"id":"geo-indian-rivers-36","question":"The Salal and Baglihar hydroelectric projects in Jammu and Kashmir are on the river:","options":["Jhelum","Chenab","Ravi","Indus"],"answer":1,"explanation":"Both projects are on the Chenab; the Kishanganga and Uri projects are on the Jhelum system and the Ranjit Sagar (Thein) dam is on the Ravi.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"जम्मू-कश्मीर में सलाल और बगलिहार जलविद्युत परियोजनाएँ किस नदी पर हैं?","optionsHi":["झेलम","चेनाब","रावी","सिंधु"],"explanationHi":"दोनों परियोजनाएँ चेनाब पर हैं; किशनगंगा और उरी परियोजनाएँ झेलम तंत्र पर हैं और रंजीत सागर (थीन) बाँध रावी पर है।"},
  {"id":"geo-indian-rivers-37","question":"The Tungabhadra, formed by the union of the Tunga and the Bhadra, is a tributary of the:","options":["Godavari","Kaveri","Krishna","Mahanadi"],"answer":2,"explanation":"The Tungabhadra rises in the Western Ghats of Karnataka, flows past Hampi and joins the Krishna in Andhra Pradesh; the Bhima is the other major Krishna tributary.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"तुंगा और भद्रा के मिलने से बनी तुंगभद्रा किसकी सहायक नदी है?","optionsHi":["गोदावरी","कावेरी","कृष्णा","महानदी"],"explanationHi":"तुंगभद्रा कर्नाटक के पश्चिमी घाट से निकलती है, हम्पी के पास से बहती है और आंध्र प्रदेश में कृष्णा से मिलती है; भीमा कृष्णा की दूसरी प्रमुख सहायक नदी है।"},
  {"id":"geo-indian-rivers-38","question":"The Indus enters Indian territory in Ladakh and flows between which two ranges?","options":["Zanskar and Ladakh ranges","Great Himalaya and Pir Panjal","Karakoram and Kunlun","Shiwalik and Dhauladhar"],"answer":0,"explanation":"After entering Ladakh near Demchok, the Indus flows north-west past Leh in the trough between the Ladakh range to its north and the Zanskar range to its south.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"सिंधु लद्दाख में भारतीय क्षेत्र में प्रवेश करती है और किन दो पर्वत श्रेणियों के बीच बहती है?","optionsHi":["ज़ांस्कर और लद्दाख श्रेणियाँ","महान हिमालय और पीर पंजाल","काराकोरम और कुनलुन","शिवालिक और धौलाधार"],"explanationHi":"देमचोक के निकट लद्दाख में प्रवेश करने के बाद सिंधु उत्तर-पश्चिम की ओर लेह के पास से, अपने उत्तर की लद्दाख श्रेणी और दक्षिण की ज़ांस्कर श्रेणी के बीच की द्रोणी में बहती है।"},
  {"id":"geo-indian-rivers-39","question":"Which Himalayan tributary of the Ganga is known as the Karnali in Nepal?","options":["Gandak","Ghaghara","Kosi","Ramganga"],"answer":1,"explanation":"The Ghaghara (Karnali in Nepal) rises near Mansarovar and joins the Ganga at Chhapra; the Gandak is called the Narayani in Nepal.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"गंगा की कौन-सी हिमालयी सहायक नदी नेपाल में कर्णाली कहलाती है?","optionsHi":["गंडक","घाघरा","कोसी","रामगंगा"],"explanationHi":"घाघरा (नेपाल में कर्णाली) मानसरोवर के निकट से निकलती है और छपरा में गंगा से मिलती है; गंडक को नेपाल में नारायणी कहा जाता है।"},
  {"id":"geo-indian-rivers-40","question":"The Brahmaputra takes that name in Assam after the union, near Sadiya, of the Dihang with the:","options":["Subansiri and Manas","Dibang and Lohit","Teesta and Torsa","Dhansiri and Kopili"],"answer":1,"explanation":"The Dihang (Siang) meets the Dibang and the Lohit near Sadiya and the combined stream is called the Brahmaputra; the Subansiri and Manas join further downstream.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"सादिया के निकट दिहांग किससे मिलने के बाद असम में ब्रह्मपुत्र नाम धारण करती है?","optionsHi":["सुबनसिरी और मानस","दिबांग और लोहित","तीस्ता और तोर्सा","धनसिरी और कोपिली"],"explanationHi":"दिहांग (सियांग) सादिया के निकट दिबांग और लोहित से मिलती है और संयुक्त धारा ब्रह्मपुत्र कहलाती है; सुबनसिरी और मानस और आगे नीचे की ओर मिलती हैं।"},
  {"id":"geo-indian-rivers-41","question":"The Shivasamudram falls, where one of Asia’s earliest hydroelectric stations was set up in 1902, are on the:","options":["Krishna","Kaveri","Sharavathi","Godavari"],"answer":1,"explanation":"The Kaveri drops over the Shivasamudram falls in Karnataka; the Jog falls are on the Sharavathi and the Hogenakkal falls, also on the Kaveri, lie downstream in Tamil Nadu.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"शिवसमुद्रम जलप्रपात, जहाँ 1902 में एशिया के आरंभिक जलविद्युत केंद्रों में से एक स्थापित किया गया था, किस नदी पर है?","optionsHi":["कृष्णा","कावेरी","शरावती","गोदावरी"],"explanationHi":"कावेरी कर्नाटक में शिवसमुद्रम जलप्रपात के रूप में गिरती है; जोग प्रपात शरावती पर है और होगेनक्कल प्रपात, जो भी कावेरी पर है, तमिलनाडु में नीचे की ओर स्थित है।"},
  {"id":"geo-indian-rivers-42","question":"Which of these is NOT a tributary of the Godavari?","options":["Indravati","Manjra","Pranhita","Bhima"],"answer":3,"explanation":"The Bhima is a tributary of the Krishna. The Godavari’s tributaries include the Pranhita (formed by the Wardha, Wainganga and Penganga), Indravati, Manjra, Purna and Sabari.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सी गोदावरी की सहायक नदी नहीं है?","optionsHi":["इंद्रावती","मंजरा","प्राणहिता","भीमा"],"explanationHi":"भीमा कृष्णा की सहायक नदी है। गोदावरी की सहायक नदियों में प्राणहिता (वर्धा, वैनगंगा और पेनगंगा से बनी), इंद्रावती, मंजरा, पूर्णा और सबरी शामिल हैं।"},
  {"id":"geo-indian-rivers-43","question":"Hyderabad is situated on the banks of the river:","options":["Krishna","Musi","Manjra","Tungabhadra"],"answer":1,"explanation":"The Musi, a tributary of the Krishna, flows through Hyderabad; the Osman Sagar and Himayat Sagar reservoirs were built on it after the 1908 flood.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"हैदराबाद किस नदी के तट पर स्थित है?","optionsHi":["कृष्णा","मूसी","मंजरा","तुंगभद्रा"],"explanationHi":"कृष्णा की सहायक नदी मूसी हैदराबाद से होकर बहती है; 1908 की बाढ़ के बाद उस पर उस्मान सागर और हिमायत सागर जलाशय बनाए गए।"},
  {"id":"geo-indian-rivers-44","question":"The Mahanadi rises at:","options":["Amarkantak, Madhya Pradesh","Sihawa, Chhattisgarh","Nasik, Maharashtra","Mahabaleshwar, Maharashtra"],"answer":1,"explanation":"The Mahanadi rises near Sihawa in Dhamtari district of Chhattisgarh and flows through Odisha to the Bay of Bengal; the Hirakud dam stands on it near Sambalpur.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"महानदी का उद्गम कहाँ है?","optionsHi":["अमरकंटक, मध्य प्रदेश","सिहावा, छत्तीसगढ़","नासिक, महाराष्ट्र","महाबलेश्वर, महाराष्ट्र"],"explanationHi":"महानदी छत्तीसगढ़ के धमतरी जिले में सिहावा के निकट से निकलती है और ओडिशा से होकर बंगाल की खाड़ी में गिरती है; संबलपुर के निकट हीराकुड बाँध उसी पर है।"},
  {"id":"geo-indian-rivers-45","question":"The Beas joins the Sutlej at:","options":["Harike (Punjab)","Ropar (Punjab)","Ferozepur (Punjab)","Nangal (Punjab)"],"answer":0,"explanation":"The Beas, which flows entirely within India, meets the Sutlej at Harike, where a barrage feeds the Indira Gandhi (Rajasthan) canal; Harike wetland is a Ramsar site.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"ब्यास सतलुज से कहाँ मिलती है?","optionsHi":["हरिके (पंजाब)","रोपड़ (पंजाब)","फिरोजपुर (पंजाब)","नांगल (पंजाब)"],"explanationHi":"पूरी तरह भारत के भीतर बहने वाली ब्यास हरिके में सतलुज से मिलती है, जहाँ का बैराज इंदिरा गांधी (राजस्थान) नहर को जल देता है; हरिके आर्द्रभूमि एक रामसर स्थल है।"},
  {"id":"geo-indian-rivers-46","question":"The longest river of Kerala is the:","options":["Bharathapuzha","Periyar","Pamba","Chaliyar"],"answer":1,"explanation":"The Periyar (244 km) is Kerala’s longest river; the Bharathapuzha (Ponnani) is the second longest. The Pamba is the river of Sabarimala.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"केरल की सबसे लंबी नदी कौन-सी है?","optionsHi":["भारतपुझा","पेरियार","पंबा","चालियार"],"explanationHi":"पेरियार (244 किमी) केरल की सबसे लंबी नदी है; भारतपुझा (पोन्नानी) दूसरी सबसे लंबी है। पंबा सबरीमाला की नदी है।"},
  {"id":"geo-indian-rivers-47","question":"Which river rises on the Chhota Nagpur plateau near Ranchi and flows directly into the Bay of Bengal without joining the Ganga?","options":["Damodar","Son","Subarnarekha","North Koel (Uttari Koel)"],"answer":2,"explanation":"The Subarnarekha rises near Nagri, west of Ranchi, and flows through Jharkhand, West Bengal and Odisha straight to the Bay of Bengal. The North Koel, also from the Ranchi plateau, joins the Son, which joins the Ganga, and the Damodar ends in the Hugli.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"कौन-सी नदी राँची के निकट छोटानागपुर पठार से निकलती है और गंगा से मिले बिना सीधे बंगाल की खाड़ी में गिरती है?","optionsHi":["दामोदर","सोन","सुवर्णरेखा","उत्तरी कोयल"],"explanationHi":"सुवर्णरेखा राँची के पश्चिम में नगड़ी के निकट से निकलती है और झारखंड, पश्चिम बंगाल तथा ओडिशा से होकर सीधे बंगाल की खाड़ी में गिरती है। उत्तरी कोयल भी राँची पठार से निकलकर सोन में मिलती है, जो गंगा में मिलती है, और दामोदर हुगली में समाप्त होती है।"},
  {"id":"geo-indian-rivers-48","question":"How many of these statements about the Ganga are correct? I. Its length is about 2,525 km. II. The Bhagirathi is regarded as the source stream although the Alaknanda is the larger of the two. III. The Farakka barrage diverts Ganga water into the Hugli. IV. In Bangladesh the Ganga is called the Padma and joins the Brahmaputra (Jamuna).","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The combined Padma–Jamuna later meets the Meghna before entering the Bay of Bengal.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"गंगा के बारे में इनमें से कितने कथन सही हैं? I. इसकी लंबाई लगभग 2,525 किमी है। II. भागीरथी को स्रोत धारा माना जाता है, यद्यपि अलकनंदा दोनों में बड़ी है। III. फरक्का बैराज गंगा का जल हुगली में मोड़ता है। IV. बांग्लादेश में गंगा को पद्मा कहा जाता है और वह ब्रह्मपुत्र (जमुना) से मिलती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। संयुक्त पद्मा–जमुना आगे चलकर बंगाल की खाड़ी में प्रवेश करने से पहले मेघना से मिलती है।"},
  {"id":"geo-indian-rivers-49","question":"Arrange these left-bank tributaries of the Ganga from west to east: 1. Kosi 2. Gomti 3. Ghaghara 4. Gandak","options":["2, 3, 4, 1","3, 2, 4, 1","2, 4, 3, 1","2, 3, 1, 4"],"answer":0,"explanation":"Gomti (joins at Ghazipur), Ghaghara (at Chhapra), Gandak (at Hajipur, opposite Patna) and Kosi (near Kursela in Bihar).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"गंगा की इन बाएँ तट की सहायक नदियों को पश्चिम से पूर्व के क्रम में व्यवस्थित कीजिए: 1. कोसी 2. गोमती 3. घाघरा 4. गंडक","optionsHi":["2, 3, 4, 1","3, 2, 4, 1","2, 4, 3, 1","2, 3, 1, 4"],"explanationHi":"गोमती (गाजीपुर में मिलती है), घाघरा (छपरा में), गंडक (हाजीपुर में, पटना के सामने) और कोसी (बिहार में कुर्सेला के निकट)।"},
  {"id":"geo-indian-rivers-50","question":"Which pair of dam and river is NOT correctly matched?","options":["Tehri – Bhagirathi","Nagarjuna Sagar – Krishna","Ukai – Tapi","Gandhi Sagar – Betwa"],"answer":3,"explanation":"Gandhi Sagar (Madhya Pradesh) is on the Chambal; the Betwa has the Rajghat and Matatila dams. Tehri, Nagarjuna Sagar and Ukai are correctly matched.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"बाँध और नदी का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["टिहरी – भागीरथी","नागार्जुन सागर – कृष्णा","उकाई – ताप्ती","गांधी सागर – बेतवा"],"explanationHi":"गांधी सागर (मध्य प्रदेश) चंबल पर है; बेतवा पर राजघाट और माताटीला बाँध हैं। टिहरी, नागार्जुन सागर और उकाई सही सुमेलित हैं।"},
  {"id":"geo-indian-rivers-51","question":"Assertion (A): The Kosi frequently shifts its course across north Bihar. Reason (R): It carries a very heavy sediment load from the Himalaya and deposits it on the plains, raising its bed.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Bed aggradation forces the river to spill and shift, which is why it has moved westward by over 100 km in two centuries and earned the name “Sorrow of Bihar”.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कोसी उत्तरी बिहार में बार-बार अपना मार्ग बदलती है। कारण (R): यह हिमालय से बहुत अधिक अवसाद (गाद) लाती है और उसे मैदानों में जमा करती है, जिससे उसकी तलहटी ऊँची हो जाती है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"तलहटी के ऊँचे होते जाने से नदी किनारों को तोड़कर फैलती और मार्ग बदलती है; इसीलिए वह दो शताब्दियों में 100 किमी से अधिक पश्चिम की ओर खिसक गई है और उसे “बिहार का शोक” नाम मिला।"},
  {"id":"geo-indian-rivers-52","question":"How many of these statements about west-flowing rivers are correct? I. The Narmada forms the Dhuandhar falls at Bhedaghat near Jabalpur. II. The Tapi enters the Gulf of Khambhat near Surat. III. The Sharavathi falls into the Bay of Bengal. IV. The Mahi rises in Madhya Pradesh and drains into the Gulf of Kutch.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. III is wrong: the Sharavathi enters the Arabian Sea at Honnavar. IV is wrong: the Mahi drains into the Gulf of Khambhat, not the Gulf of Kutch.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"पश्चिम की ओर बहने वाली नदियों के बारे में इनमें से कितने कथन सही हैं? I. नर्मदा जबलपुर के निकट भेड़ाघाट में धुआँधार प्रपात बनाती है। II. ताप्ती सूरत के निकट खंभात की खाड़ी में गिरती है। III. शरावती बंगाल की खाड़ी में गिरती है। IV. माही मध्य प्रदेश से निकलती है और कच्छ की खाड़ी में गिरती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। III गलत है: शरावती होन्नावर में अरब सागर में प्रवेश करती है। IV गलत है: माही खंभात की खाड़ी में गिरती है, कच्छ की खाड़ी में नहीं।"},
  {"id":"geo-indian-rivers-53","question":"How many of these statements about the Brahmaputra are correct? I. It rises from the Chemayungdung glacier near Mansarovar. II. In Bangladesh it is called the Padma. III. It takes a hairpin bend around Nanda Devi before entering India. IV. Its length within India is greater than its length within Tibet.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. In Bangladesh the Brahmaputra is the Jamuna (the Padma is the Ganga), it bends around Namcha Barwa, and most of its length is in Tibet, not India.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ब्रह्मपुत्र के बारे में इनमें से कितने कथन सही हैं? I. यह मानसरोवर के निकट चेमायुंगडुंग हिमनद से निकलती है। II. बांग्लादेश में इसे पद्मा कहा जाता है। III. भारत में प्रवेश करने से पहले यह नंदा देवी के चारों ओर एक हेयरपिन मोड़ लेती है। IV. भारत के भीतर इसकी लंबाई तिब्बत के भीतर की लंबाई से अधिक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। बांग्लादेश में ब्रह्मपुत्र को जमुना कहा जाता है (पद्मा गंगा है), यह नामचा बरवा के चारों ओर मुड़ती है, और इसकी अधिकांश लंबाई तिब्बत में है, भारत में नहीं।"},
  {"id":"geo-indian-rivers-54","question":"Which of these rivers does NOT form a delta at its mouth?","options":["Mahanadi","Godavari","Narmada","Krishna"],"answer":2,"explanation":"The Narmada, like the Tapi, forms an estuary because it flows through a rift valley with a steep gradient and little sediment, and the Arabian Sea coast has strong tidal action; the east-flowing rivers form deltas.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सी नदी अपने मुहाने पर डेल्टा नहीं बनाती?","optionsHi":["महानदी","गोदावरी","नर्मदा","कृष्णा"],"explanationHi":"नर्मदा, ताप्ती की तरह, ज्वारनदमुख (एस्चुअरी) बनाती है, क्योंकि वह तीव्र ढाल वाली भ्रंश घाटी से बहती है, उसमें अवसाद कम होता है, और अरब सागर के तट पर प्रबल ज्वारीय क्रिया होती है; पूर्व की ओर बहने वाली नदियाँ डेल्टा बनाती हैं।"},
  {"id":"geo-indian-rivers-55","question":"Which pair of city and river is NOT correctly matched?","options":["Surat – Tapi","Nashik – Godavari","Vijayawada – Krishna","Jabalpur – Tapi"],"answer":3,"explanation":"Jabalpur stands on the Narmada, near the marble rocks of Bhedaghat; the Tapi flows through Burhanpur and Surat.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"नगर और नदी का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["सूरत – ताप्ती","नासिक – गोदावरी","विजयवाड़ा – कृष्णा","जबलपुर – ताप्ती"],"explanationHi":"जबलपुर नर्मदा पर स्थित है, भेड़ाघाट की संगमरमर चट्टानों के निकट; ताप्ती बुरहानपुर और सूरत से होकर बहती है।"},
  {"id":"geo-indian-rivers-56","question":"Arrange these dams in the order of their completion or commissioning: 1. Tehri 2. Hirakud 3. Sardar Sarovar 4. Bhakra","options":["2, 4, 1, 3","4, 2, 1, 3","2, 4, 3, 1","2, 1, 4, 3"],"answer":0,"explanation":"Hirakud (1957), Bhakra (1963), Tehri (2006) and Sardar Sarovar (dedicated to the nation in 2017).","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"इन बाँधों को उनके पूर्ण होने या चालू होने के क्रम में व्यवस्थित कीजिए: 1. टिहरी 2. हीराकुड 3. सरदार सरोवर 4. भाखड़ा","optionsHi":["2, 4, 1, 3","4, 2, 1, 3","2, 4, 3, 1","2, 1, 4, 3"],"explanationHi":"हीराकुड (1957), भाखड़ा (1963), टिहरी (2006) और सरदार सरोवर (2017 में राष्ट्र को समर्पित)।"},
  {"id":"geo-indian-rivers-57","question":"How many of these statements about the Indus system are correct? I. The Indus is about 2,880 km long. II. The Jhelum rises at Verinag in the Kashmir valley. III. The Ravi rises near the Rohtang pass in the Kullu hills. IV. The Beas rises at Beas Kund near the Rohtang pass and flows entirely within India.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Ravi and Beas both rise near Rohtang, on opposite sides of the Pir Panjal; the Beas is the only Indus tributary that never leaves India.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"सिंधु तंत्र के बारे में इनमें से कितने कथन सही हैं? I. सिंधु लगभग 2,880 किमी लंबी है। II. झेलम कश्मीर घाटी में वेरीनाग से निकलती है। III. रावी कुल्लू पहाड़ियों में रोहतांग दर्रे के निकट से निकलती है। IV. ब्यास रोहतांग दर्रे के निकट ब्यास कुंड से निकलती है और पूरी तरह भारत के भीतर बहती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। रावी और ब्यास दोनों रोहतांग के निकट, पीर पंजाल के विपरीत पक्षों से निकलती हैं; ब्यास सिंधु की एकमात्र सहायक नदी है जो कभी भारत से बाहर नहीं जाती।"},
  {"id":"geo-indian-rivers-58","question":"Assertion (A): East-flowing peninsular rivers such as the Godavari form deltas, while the Narmada and Tapi form estuaries. Reason (R): The west-flowing rivers run through rift valleys with steep gradients, carry little sediment, and meet a coast with strong tidal action.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Delta formation needs abundant sediment and a gentle, shallow coast; the east-flowing rivers have both, while the Narmada and Tapi lack sediment and face a submerged, tidal western coast.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): गोदावरी जैसी पूर्व की ओर बहने वाली प्रायद्वीपीय नदियाँ डेल्टा बनाती हैं, जबकि नर्मदा और ताप्ती ज्वारनदमुख (एस्चुअरी) बनाती हैं। कारण (R): पश्चिम की ओर बहने वाली नदियाँ तीव्र ढाल वाली भ्रंश घाटियों से बहती हैं, उनमें अवसाद कम होता है, और वे प्रबल ज्वारीय क्रिया वाले तट से मिलती हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"डेल्टा निर्माण के लिए प्रचुर अवसाद और मंद, उथला तट चाहिए; पूर्व की ओर बहने वाली नदियों में दोनों हैं, जबकि नर्मदा और ताप्ती में अवसाद की कमी है और उन्हें एक निमज्जित, ज्वारीय पश्चिमी तट मिलता है।"},
  {"id":"geo-indian-rivers-59","question":"How many of these statements about inter-state river disputes are correct? I. The Kaveri dispute involves Karnataka, Tamil Nadu, Kerala and Puducherry. II. The Krishna water dispute involves Maharashtra, Karnataka, Andhra Pradesh and Telangana. III. The Mahadayi (Mandovi) dispute is among Goa, Karnataka and Maharashtra. IV. The Sutlej–Yamuna Link canal dispute is between Punjab and Rajasthan.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The SYL canal dispute is between Punjab and Haryana, over Haryana’s share of Ravi–Beas water.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अंतर-राज्यीय नदी विवादों के बारे में इनमें से कितने कथन सही हैं? I. कावेरी विवाद में कर्नाटक, तमिलनाडु, केरल और पुदुचेरी शामिल हैं। II. कृष्णा जल विवाद में महाराष्ट्र, कर्नाटक, आंध्र प्रदेश और तेलंगाना शामिल हैं। III. महादायी (मांडोवी) विवाद गोवा, कर्नाटक और महाराष्ट्र के बीच है। IV. सतलुज–यमुना लिंक नहर विवाद पंजाब और राजस्थान के बीच है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। SYL नहर विवाद पंजाब और हरियाणा के बीच है, जो रावी–ब्यास के जल में हरियाणा के हिस्से को लेकर है।"},
  {"id":"geo-indian-rivers-60","question":"Kolkata stands on the bank of the river:","options":["Damodar","Hugli","Rupnarayan","Padma"],"answer":1,"explanation":"Kolkata lies on the east bank of the Hugli (Bhagirathi–Hugli), a distributary of the Ganga. The Padma is the Ganga’s name in Bangladesh.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"कोलकाता किस नदी के तट पर स्थित है?","optionsHi":["दामोदर","हुगली","रूपनारायण","पद्मा"],"explanationHi":"कोलकाता हुगली (भागीरथी–हुगली) के पूर्वी तट पर स्थित है, जो गंगा की एक वितरिका है। पद्मा बांग्लादेश में गंगा का नाम है।"},
  {"id":"geo-indian-rivers-61","question":"Srinagar, the summer capital of Jammu and Kashmir, is situated on the river:","options":["Chenab","Jhelum","Indus","Tawi"],"answer":1,"explanation":"The Jhelum flows through Srinagar and the Kashmir valley. Jammu stands on the Tawi.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"जम्मू-कश्मीर की ग्रीष्मकालीन राजधानी श्रीनगर किस नदी पर स्थित है?","optionsHi":["चेनाब","झेलम","सिंधु","तवी"],"explanationHi":"झेलम श्रीनगर और कश्मीर घाटी से होकर बहती है। जम्मू तवी नदी पर स्थित है।"},
  {"id":"geo-indian-rivers-62","question":"The city of Pune lies at the confluence of the rivers:","options":["Mula and Mutha","Bhima and Nira","Krishna and Koyna","Godavari and Pravara"],"answer":0,"explanation":"The Mula and Mutha meet at Pune; the combined Mula-Mutha later joins the Bhima, a tributary of the Krishna.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"पुणे नगर किन नदियों के संगम पर स्थित है?","optionsHi":["मुला और मुठा","भीमा और नीरा","कृष्णा और कोयना","गोदावरी और प्रवरा"],"explanationHi":"मुला और मुठा पुणे में मिलती हैं; संयुक्त मुला-मुठा आगे चलकर कृष्णा की सहायक नदी भीमा से मिलती है।"},
  {"id":"geo-indian-rivers-63","question":"The Kishanganga, called the Neelum in Pakistan-administered Kashmir, is a tributary of the:","options":["Chenab","Ravi","Indus directly","Jhelum"],"answer":3,"explanation":"The Kishanganga joins the Jhelum near Muzaffarabad. India’s Kishanganga hydroelectric project diverts its water to the Wular lake area.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"किशनगंगा, जिसे पाकिस्तान-अधिकृत कश्मीर में नीलम कहा जाता है, किसकी सहायक नदी है?","optionsHi":["चेनाब","रावी","सीधे सिंधु","झेलम"],"explanationHi":"किशनगंगा मुजफ्फराबाद के निकट झेलम में मिलती है। भारत की किशनगंगा जलविद्युत परियोजना उसका जल वुलर झील क्षेत्र की ओर मोड़ती है।"},
  {"id":"geo-indian-rivers-64","question":"The Mahatma Gandhi Setu, one of India’s longest river bridges, spans the Ganga at:","options":["Varanasi","Bhagalpur","Patna","Prayagraj"],"answer":2,"explanation":"The Gandhi Setu links Patna with Hajipur across the Ganga. Bhagalpur has the Vikramshila Setu.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारत के सबसे लंबे नदी पुलों में से एक महात्मा गांधी सेतु गंगा पर कहाँ बना है?","optionsHi":["वाराणसी","भागलपुर","पटना","प्रयागराज"],"explanationHi":"गांधी सेतु गंगा के आर-पार पटना को हाजीपुर से जोड़ता है। भागलपुर में विक्रमशिला सेतु है।"},
  {"id":"geo-indian-rivers-65","question":"Leh, the main town of Ladakh, lies close to the bank of the:","options":["Indus","Shyok","Zanskar","Nubra"],"answer":0,"explanation":"Leh stands in the Indus valley, a few kilometres from the river, between the Ladakh and Zanskar ranges. The Shyok and its tributary the Nubra flow north of the Ladakh range, and the Zanskar joins the Indus downstream at Nimu.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"लद्दाख का प्रमुख नगर लेह किस नदी के तट के पास स्थित है?","optionsHi":["सिंधु","श्योक","ज़ांस्कर","नुब्रा"],"explanationHi":"लेह सिंधु घाटी में, नदी से कुछ किलोमीटर दूर, लद्दाख और ज़ांस्कर पर्वतमालाओं के बीच स्थित है। श्योक और उसकी सहायक नुब्रा लद्दाख पर्वतमाला के उत्तर में बहती हैं, और ज़ांस्कर नीचे की ओर निमू में सिंधु से मिलती है।"},
  {"id":"geo-indian-rivers-66","question":"Which river was known as the “Sorrow of Bengal” because of its devastating floods before multipurpose dams were built on it?","options":["Kosi","Rupnarayan","Damodar","Teesta"],"answer":2,"explanation":"The Damodar flooded Bengal frequently until the Damodar Valley Corporation built dams on it. The Kosi is the Sorrow of Bihar, and the Rupnarayan is only a tidal river that the Damodar partly drains into.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किस नदी को अपनी विनाशकारी बाढ़ों के कारण, उस पर बहुउद्देशीय बाँध बनने से पहले, “बंगाल का शोक” कहा जाता था?","optionsHi":["कोसी","रूपनारायण","दामोदर","तीस्ता"],"explanationHi":"दामोदर घाटी निगम द्वारा उस पर बाँध बनाए जाने तक दामोदर में बंगाल में बार-बार बाढ़ आती थी। कोसी बिहार का शोक है, और रूपनारायण केवल एक ज्वारीय नदी है जिसमें दामोदर का कुछ जल जाता है।"},
  {"id":"geo-indian-rivers-67","question":"The Bhima, a major tributary of the Krishna, rises at:","options":["Mahabaleshwar","Trimbakeshwar","Bhimashankar","Nasik"],"answer":2,"explanation":"The Bhima rises at Bhimashankar (Pune district) and joins the Krishna near Raichur. The Krishna rises at Mahabaleshwar and the Godavari at Trimbakeshwar near Nasik.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"कृष्णा की प्रमुख सहायक नदी भीमा का उद्गम कहाँ से होता है?","optionsHi":["महाबलेश्वर","त्र्यंबकेश्वर","भीमाशंकर","नासिक"],"explanationHi":"भीमा भीमाशंकर (पुणे जिला) से निकलती है और रायचूर के निकट कृष्णा से मिलती है। कृष्णा महाबलेश्वर से और गोदावरी नासिक के निकट त्र्यंबकेश्वर से निकलती है।"},
  {"id":"geo-indian-rivers-68","question":"The Gandak, a left-bank tributary of the Ganga, is known in Nepal as the:","options":["Karnali","Sapt Kosi","Narayani","Bagmati"],"answer":2,"explanation":"In Nepal the Gandak is called the Narayani (Sapta Gandaki); it joins the Ganga near Patna. The Karnali becomes the Ghaghara and the Sapt Kosi the Kosi.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"गंगा की बाएँ तट की सहायक नदी गंडक नेपाल में किस नाम से जानी जाती है?","optionsHi":["कर्णाली","सप्त कोसी","नारायणी","बागमती"],"explanationHi":"नेपाल में गंडक को नारायणी (सप्तगंडकी) कहा जाता है; यह पटना के निकट गंगा में मिलती है। कर्णाली घाघरा बनती है और सप्त कोसी कोसी।"},
  {"id":"geo-indian-rivers-69","question":"The historic town of Orchha in Madhya Pradesh lies on the bank of the:","options":["Betwa","Ken","Sindh","Dhasan"],"answer":0,"explanation":"Orchha, the old Bundela capital, is on the Betwa, a tributary of the Yamuna. The Ken flows past Panna and through Khajuraho’s region.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"मध्य प्रदेश का ऐतिहासिक नगर ओरछा किस नदी के तट पर स्थित है?","optionsHi":["बेतवा","केन","सिंध","धसान"],"explanationHi":"बुंदेला शासकों की पुरानी राजधानी ओरछा यमुना की सहायक नदी बेतवा पर स्थित है। केन पन्ना और खजुराहो क्षेत्र से होकर बहती है।"},
  {"id":"geo-indian-rivers-70","question":"The Damodar Valley Corporation (1948), India’s first multipurpose river valley project, was modelled on the:","options":["Hoover Dam project, USA","Tennessee Valley Authority, USA","Aswan High Dam project, Egypt","Snowy Mountains Scheme, Australia"],"answer":1,"explanation":"The DVC was modelled on the Tennessee Valley Authority, an integrated river-basin agency set up in the USA in 1933.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"दामोदर घाटी निगम (1948), भारत की पहली बहुउद्देशीय नदी घाटी परियोजना, किस पर आधारित थी?","optionsHi":["हूवर बाँध परियोजना, संयुक्त राज्य अमेरिका","टेनेसी वैली अथॉरिटी, संयुक्त राज्य अमेरिका","असवान उच्च बाँध परियोजना, मिस्र","स्नोई माउंटेंस योजना, ऑस्ट्रेलिया"],"explanationHi":"DVC टेनेसी वैली अथॉरिटी पर आधारित था, जो 1933 में अमेरिका में स्थापित एक एकीकृत नदी-बेसिन एजेंसी थी।"},
  {"id":"geo-indian-rivers-71","question":"The temple city of Madurai stands on the bank of the river:","options":["Tamraparni","Kaveri","Palar","Vaigai"],"answer":3,"explanation":"Madurai lies on the Vaigai, which flows into the Palk Bay. The Tamraparni flows past Tirunelveli.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"मंदिरों का नगर मदुरै किस नदी के तट पर स्थित है?","optionsHi":["तामिरभरणी","कावेरी","पालार","वैगई"],"explanationHi":"मदुरै वैगई पर स्थित है, जो पाल्क खाड़ी में गिरती है। तामिरभरणी तिरुनेलवेली से होकर बहती है।"},
  {"id":"geo-indian-rivers-72","question":"The Ken–Betwa link project, the first project under India’s National Perspective Plan for interlinking rivers, transfers surplus water from the Ken to the Betwa. Both rivers are tributaries of the:","options":["Ganga directly","Son","Chambal","Yamuna"],"answer":3,"explanation":"The Ken and the Betwa are right-bank tributaries of the Yamuna in Bundelkhand. The project includes the Daudhan dam in Panna district.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"केन–बेतवा लिंक परियोजना, जो नदियों को जोड़ने की भारत की राष्ट्रीय परिप्रेक्ष्य योजना के अंतर्गत पहली परियोजना है, केन के अधिशेष जल को बेतवा में स्थानांतरित करती है। दोनों नदियाँ किसकी सहायक नदियाँ हैं?","optionsHi":["सीधे गंगा की","सोन की","चंबल की","यमुना की"],"explanationHi":"केन और बेतवा बुंदेलखंड में यमुना की दाएँ तट की सहायक नदियाँ हैं। परियोजना में पन्ना जिले में दौधन बाँध शामिल है।"},
  {"id":"geo-indian-rivers-73","question":"In January 2023, India issued a notice to Pakistan under Article XII(3) seeking modification of the:","options":["Ganga Water Treaty with Bangladesh","Indus Waters Treaty with Pakistan","Mahakali Treaty with Nepal","Kosi Agreement with Nepal"],"answer":1,"explanation":"India sought changes to the 1960 Indus Waters Treaty, brokered by the World Bank, after Pakistan's handling of disputes over the Kishanganga and Ratle hydro projects. Under the treaty India controls the eastern rivers (Ravi, Beas, Sutlej) and Pakistan the western rivers (Indus, Jhelum, Chenab).","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"जनवरी 2023 में भारत ने अनुच्छेद XII(3) के अंतर्गत पाकिस्तान को किस संधि में संशोधन की माँग करते हुए नोटिस भेजा?","optionsHi":["बांग्लादेश के साथ गंगा जल संधि","पाकिस्तान के साथ सिंधु जल संधि","नेपाल के साथ महाकाली संधि","नेपाल के साथ कोसी समझौता"],"explanationHi":"भारत ने किशनगंगा और रातले जलविद्युत परियोजनाओं से जुड़े विवादों पर पाकिस्तान के रवैये के बाद विश्व बैंक की मध्यस्थता से हुई 1960 की सिंधु जल संधि में बदलाव की माँग की। इस संधि के अंतर्गत भारत पूर्वी नदियों (रावी, ब्यास, सतलुज) और पाकिस्तान पश्चिमी नदियों (सिंधु, झेलम, चेनाब) को नियंत्रित करता है।"},
  {"id":"geo-indian-rivers-74","question":"Match the river with its source: A. Godavari B. Penna (Pennar) C. Son D. Chambal. 1. Janapav hills near Mhow 2. Amarkantak 3. Nandi hills, Karnataka 4. Trimbakeshwar","options":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"The Godavari rises at Trimbakeshwar (Nasik), the Penna in the Nandi hills (Chikkaballapur), the Son at Amarkantak and the Chambal in the Janapav hills near Mhow.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"नदी का उसके उद्गम से मिलान कीजिए: A. गोदावरी B. पेन्ना (पेन्नार) C. सोन D. चंबल. 1. महू के निकट जानापाव की पहाड़ियाँ 2. अमरकंटक 3. नंदी हिल्स, कर्नाटक 4. त्र्यंबकेश्वर","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"गोदावरी त्र्यंबकेश्वर (नासिक) से, पेन्ना नंदी हिल्स (चिक्कबल्लापुर) से, सोन अमरकंटक से और चंबल महू के निकट जानापाव की पहाड़ियों से निकलती है।"},
  {"id":"geo-indian-rivers-75","question":"Arrange these confluences on the Alaknanda from upstream to downstream: 1. Rudraprayag 2. Vishnuprayag 3. Karnaprayag 4. Nandprayag","options":["2, 3, 4, 1","4, 2, 3, 1","2, 4, 1, 3","2, 4, 3, 1"],"answer":3,"explanation":"Vishnuprayag (Dhauliganga), Nandprayag (Nandakini), Karnaprayag (Pindar), Rudraprayag (Mandakini); then Devprayag, where the Bhagirathi joins and the Ganga begins.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अलकनंदा पर स्थित इन संगमों को ऊपर की ओर (अपस्ट्रीम) से नीचे की ओर (डाउनस्ट्रीम) के क्रम में व्यवस्थित कीजिए: 1. रुद्रप्रयाग 2. विष्णुप्रयाग 3. कर्णप्रयाग 4. नंदप्रयाग","optionsHi":["2, 3, 4, 1","4, 2, 3, 1","2, 4, 1, 3","2, 4, 3, 1"],"explanationHi":"विष्णुप्रयाग (धौलीगंगा), नंदप्रयाग (नंदाकिनी), कर्णप्रयाग (पिंडर), रुद्रप्रयाग (मंदाकिनी); फिर देवप्रयाग, जहाँ भागीरथी मिलती है और गंगा का आरंभ होता है।"},
  {"id":"geo-indian-rivers-76","question":"Assertion (A): The Himalayan rivers of the Ganga system are perennial. Reason (R): They are fed both by melting snow and glaciers and by monsoon rainfall.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. Snowmelt keeps them flowing in the dry summer months, and the monsoon swells them in the rainy season, unlike the rain-fed peninsular rivers.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): गंगा तंत्र की हिमालयी नदियाँ बारहमासी हैं। कारण (R): ये पिघलती बर्फ और हिमनदों तथा मानसूनी वर्षा, दोनों से जल प्राप्त करती हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है। हिमगलन शुष्क गर्मी के महीनों में इन्हें प्रवाहित रखता है, और मानसून वर्षा ऋतु में इन्हें उफान पर ला देता है, जो वर्षा-पोषित प्रायद्वीपीय नदियों से भिन्न है।"},
  {"id":"geo-indian-rivers-77","question":"How many of these statements about the tributaries of the Brahmaputra are correct? I. The Subansiri joins it from the north bank. II. The Manas joins it from the north bank. III. The Dhansiri joins it from the south bank. IV. The Teesta joins it within Indian territory.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: the Teesta flows from Sikkim through West Bengal into Bangladesh and joins the Brahmaputra (Jamuna) there.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"ब्रह्मपुत्र की सहायक नदियों के बारे में इनमें से कितने कथन सही हैं? I. सुबनसिरी इसमें उत्तरी तट से मिलती है। II. मानस इसमें उत्तरी तट से मिलती है। III. धनसिरी इसमें दक्षिणी तट से मिलती है। IV. तीस्ता भारतीय क्षेत्र के भीतर इसमें मिलती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: तीस्ता सिक्किम से पश्चिम बंगाल होकर बांग्लादेश में बहती है और वहीं ब्रह्मपुत्र (जमुना) में मिलती है।"},
  {"id":"geo-indian-rivers-78","question":"Arrange these water agreements in chronological order: 1. Ganga Water Treaty with Bangladesh 2. Indus Waters Treaty 3. Mahakali Treaty with Nepal 4. Kosi Agreement with Nepal","options":["4, 2, 3, 1","2, 4, 3, 1","4, 2, 1, 3","4, 3, 2, 1"],"answer":0,"explanation":"Kosi Agreement: 1954. Indus Waters Treaty: 1960. Mahakali Treaty: February 1996. Ganga Water Treaty: December 1996.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन जल समझौतों को कालानुक्रमिक क्रम में व्यवस्थित कीजिए: 1. बांग्लादेश के साथ गंगा जल संधि 2. सिंधु जल संधि 3. नेपाल के साथ महाकाली संधि 4. नेपाल के साथ कोसी समझौता","optionsHi":["4, 2, 3, 1","2, 4, 3, 1","4, 2, 1, 3","4, 3, 2, 1"],"explanationHi":"कोसी समझौता: 1954। सिंधु जल संधि: 1960। महाकाली संधि: फरवरी 1996। गंगा जल संधि: दिसंबर 1996।"},
  {"id":"geo-indian-rivers-79","question":"Which of these rivers is a RIGHT-bank tributary of the Indus?","options":["Jhelum","Chenab","Kabul","Sutlej"],"answer":2,"explanation":"The Kabul joins the Indus from the right (west) near Attock, as do the Kurram, Tochi and Gomal. The Jhelum, Chenab, Ravi, Beas and Sutlej are left-bank tributaries joining via the Panjnad.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सी नदी सिंधु की दाएँ तट की सहायक नदी है?","optionsHi":["झेलम","चेनाब","काबुल","सतलुज"],"explanationHi":"काबुल अटक के निकट सिंधु में दाएँ (पश्चिमी) ओर से मिलती है, जैसे कुर्रम, तोची और गोमल। झेलम, चेनाब, रावी, ब्यास और सतलुज बाएँ तट की सहायक नदियाँ हैं, जो पंजनद के माध्यम से मिलती हैं।"},
  {"id":"geo-indian-rivers-80","question":"Match the waterfall with the river: A. Dudhsagar B. Hogenakkal C. Chitrakote D. Athirappilly. 1. Chalakudy 2. Indravati 3. Kaveri 4. Mandovi","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Dudhsagar (Goa–Karnataka border) is on the Mandovi; Hogenakkal (Tamil Nadu) on the Kaveri; Chitrakote (Chhattisgarh) on the Indravati; Athirappilly (Kerala) on the Chalakudy.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"जलप्रपात का नदी से मिलान कीजिए: A. दूधसागर B. होगेनक्कल C. चित्रकोट D. अथिरापल्ली. 1. चालाकुडी 2. इंद्रावती 3. कावेरी 4. मांडोवी","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"दूधसागर (गोवा–कर्नाटक सीमा) मांडोवी पर है; होगेनक्कल (तमिलनाडु) कावेरी पर; चित्रकोट (छत्तीसगढ़) इंद्रावती पर; अथिरापल्ली (केरल) चालाकुडी पर।"},
  {"id":"geo-indian-rivers-81","question":"How many of these dams are correctly matched with their river? I. Tehri – Alaknanda II. Indira Sagar – Narmada III. Ukai – Mahi IV. Koyna – Koyna, in Maharashtra","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and IV are correct. I is wrong: the Tehri dam is on the Bhagirathi. III is wrong: the Ukai dam is on the Tapi in Gujarat; the Mahi has the Kadana and Mahi Bajaj Sagar dams.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने बाँध अपनी नदी से सही सुमेलित हैं? I. टिहरी – अलकनंदा II. इंदिरा सागर – नर्मदा III. उकाई – माही IV. कोयना – कोयना, महाराष्ट्र में","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और IV सही हैं। I गलत है: टिहरी बाँध भागीरथी पर है। III गलत है: उकाई बाँध गुजरात में ताप्ती पर है; माही पर कडाना और माही बजाज सागर बाँध हैं।"},
  {"id":"geo-indian-rivers-82","question":"Assertion (A): The Chambal valley is known for its deep ravines (badlands). Reason (R): Intense gully erosion has cut deeply into the soft alluvial soils along the river.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. Run-off from heavy seasonal rain has dissected the soft alluvium along the Chambal into a maze of ravines.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): चंबल घाटी अपने गहरे बीहड़ों (उत्खात भूमि) के लिए जानी जाती है। कारण (R): तीव्र अवनालिका अपरदन ने नदी के किनारे की कोमल जलोढ़ मिट्टी को गहराई तक काट दिया है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है। भारी मौसमी वर्षा के अपवाह ने चंबल के किनारे की कोमल जलोढ़क को बीहड़ों के जाल में काट दिया है।"},
  {"id":"geo-indian-rivers-83","question":"How many of these statements about the peninsular rivers are correct? I. The Kaveri has a relatively steady flow because its basin receives rain from both the south-west and north-east monsoons. II. The Krishna is the second-largest east-flowing peninsular river. III. The Mahanadi forms its delta in Odisha. IV. The Godavari has the largest basin among peninsular rivers.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The upper Kaveri catchment in Karnataka gets the south-west monsoon and the lower basin in Tamil Nadu the north-east monsoon, so its flow fluctuates less than other peninsular rivers.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"प्रायद्वीपीय नदियों के बारे में इनमें से कितने कथन सही हैं? I. कावेरी का प्रवाह अपेक्षाकृत स्थिर रहता है, क्योंकि उसके बेसिन को दक्षिण-पश्चिम और उत्तर-पूर्व दोनों मानसूनों से वर्षा मिलती है। II. कृष्णा पूर्व की ओर बहने वाली दूसरी सबसे बड़ी प्रायद्वीपीय नदी है। III. महानदी अपना डेल्टा ओडिशा में बनाती है। IV. प्रायद्वीपीय नदियों में गोदावरी का बेसिन सबसे बड़ा है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। कर्नाटक में ऊपरी कावेरी जलग्रहण क्षेत्र को दक्षिण-पश्चिम मानसून और तमिलनाडु में निचले बेसिन को उत्तर-पूर्वी मानसून मिलता है, इसलिए अन्य प्रायद्वीपीय नदियों की तुलना में उसका प्रवाह कम घटता-बढ़ता है।"},
  {"id":"geo-indian-rivers-84","question":"Arrange the mouths of these west-flowing rivers from north to south: 1. Tapi 2. Mahi 3. Narmada 4. Sabarmati","options":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","4, 2, 1, 3"],"answer":0,"explanation":"The Sabarmati and the Mahi enter the head of the Gulf of Khambhat, the Sabarmati further north; the Narmada reaches the sea near Bharuch and the Tapi near Surat.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"पश्चिम की ओर बहने वाली इन नदियों के मुहानों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए: 1. ताप्ती 2. माही 3. नर्मदा 4. साबरमती","optionsHi":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","4, 2, 1, 3"],"explanationHi":"साबरमती और माही खंभात की खाड़ी के शीर्ष में प्रवेश करती हैं, साबरमती और उत्तर में; नर्मदा भरूच के निकट और ताप्ती सूरत के निकट समुद्र में पहुँचती है।"},
  {"id":"geo-indian-rivers-85","question":"Ahmedabad, the largest city of Gujarat, stands on the bank of the river:","options":["Mahi","Sabarmati","Vishwamitri","Narmada"],"answer":1,"explanation":"Ahmedabad lies on the Sabarmati, which rises in the Aravalli and flows into the Gulf of Khambhat. Vadodara stands on the Vishwamitri and Surat on the Tapi, which makes them the tempting wrong picks.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"गुजरात का सबसे बड़ा शहर अहमदाबाद किस नदी के तट पर स्थित है?","optionsHi":["माही","साबरमती","विश्वामित्री","नर्मदा"],"explanationHi":"अहमदाबाद साबरमती पर स्थित है, जो अरावली से निकलकर खंभात की खाड़ी में गिरती है। वडोदरा विश्वामित्री पर और सूरत ताप्ती पर है, इसीलिए ये भ्रमित करने वाले गलत विकल्प बनते हैं।"},
  {"id":"geo-indian-rivers-86","question":"Which animal was declared India's National Aquatic Animal in 2009?","options":["Gharial","Gangetic dolphin","Olive ridley turtle","Irrawaddy dolphin"],"answer":1,"explanation":"The Gangetic (Ganges river) dolphin, a nearly blind dolphin of the Ganga–Brahmaputra system, was declared the National Aquatic Animal in 2009. The Irrawaddy dolphin lives in Chilika lake and is not the national symbol.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2009 में किस पशु को भारत का राष्ट्रीय जलीय जीव घोषित किया गया?","optionsHi":["घड़ियाल","गंगा डॉल्फिन","ऑलिव रिडले कछुआ","इरावदी डॉल्फिन"],"explanationHi":"गंगा–ब्रह्मपुत्र तंत्र की लगभग दृष्टिहीन डॉल्फिन, गंगा नदी की डॉल्फिन (Gangetic dolphin), को 2009 में राष्ट्रीय जलीय जीव घोषित किया गया। इरावदी डॉल्फिन चिल्का झील में रहती है और राष्ट्रीय प्रतीक नहीं है।"},
  {"id":"geo-indian-rivers-87","question":"The city of Ujjain, where the Simhastha Kumbh is held, stands on the river:","options":["Chambal","Shipra","Betwa","Narmada"],"answer":1,"explanation":"Ujjain is on the Shipra (Kshipra), a tributary of the Chambal. Nashik (Godavari), Haridwar and Prayagraj (Ganga) are the other Kumbh cities.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उज्जैन नगर, जहाँ सिंहस्थ कुंभ आयोजित होता है, किस नदी पर स्थित है?","optionsHi":["चंबल","शिप्रा","बेतवा","नर्मदा"],"explanationHi":"उज्जैन चंबल की सहायक नदी शिप्रा (क्षिप्रा) पर है। नासिक (गोदावरी), हरिद्वार और प्रयागराज (गंगा) अन्य कुंभ नगर हैं।"},
  {"id":"geo-indian-rivers-88","question":"Ayodhya stands on the bank of the Saryu, which is the name given to the lower course of the:","options":["Ghaghara","Gomti","Gandak","Ramganga"],"answer":0,"explanation":"The Ghaghara (Karnali in Nepal) is called the Saryu near Ayodhya. It joins the Ganga near Chhapra in Bihar.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"अयोध्या सरयू के तट पर स्थित है, जो किसके निचले मार्ग को दिया गया नाम है?","optionsHi":["घाघरा","गोमती","गंडक","रामगंगा"],"explanationHi":"घाघरा (नेपाल में कर्णाली) को अयोध्या के निकट सरयू कहा जाता है। यह बिहार में छपरा के निकट गंगा में मिलती है।"},
  {"id":"geo-indian-rivers-89","question":"The largest tributary of the Yamuna in the Himalayan region, which joins it near Kalsi in Uttarakhand, is the:","options":["Hindon","Giri","Chambal","Tons"],"answer":3,"explanation":"The Tons, rising near Bandarpunch, is the Yamuna's largest Himalayan tributary. The Chambal is the largest tributary overall, joining from the plateau side much further down.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"हिमालयी क्षेत्र में यमुना की सबसे बड़ी सहायक नदी, जो उत्तराखंड में कालसी के निकट उससे मिलती है, कौन-सी है?","optionsHi":["हिंडन","गिरि","चंबल","टोंस"],"explanationHi":"बंदरपूँछ के निकट से निकलने वाली टोंस यमुना की सबसे बड़ी हिमालयी सहायक नदी है। चंबल कुल मिलाकर सबसे बड़ी सहायक नदी है, जो पठारी ओर से बहुत आगे नीचे मिलती है।"},
  {"id":"geo-indian-rivers-90","question":"The Govind Ballabh Pant Sagar reservoir in Sonbhadra (Uttar Pradesh) is formed by a dam on the:","options":["Betwa","Ken","Ramganga","Rihand"],"answer":3,"explanation":"The Rihand dam stands on the Rihand river, a tributary of the Son, and its reservoir is one of India's largest artificial lakes. It powers the Singrauli energy belt.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"सोनभद्र (उत्तर प्रदेश) में गोविंद बल्लभ पंत सागर जलाशय किस नदी पर बाँध से बना है?","optionsHi":["बेतवा","केन","रामगंगा","रिहंद"],"explanationHi":"रिहंद बाँध सोन की सहायक नदी रिहंद पर स्थित है, और उसका जलाशय भारत की सबसे बड़ी कृत्रिम झीलों में से एक है। यह सिंगरौली ऊर्जा पट्टी को बिजली देता है।"},
  {"id":"geo-indian-rivers-91","question":"The Ukai dam, Gujarat's largest reservoir, is built on the:","options":["Tapi","Mahi","Sabarmati","Narmada"],"answer":0,"explanation":"Ukai (with the Kakrapar weir downstream) is on the Tapi. The Kadana dam is on the Mahi and Sardar Sarovar on the Narmada.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"गुजरात का सबसे बड़ा जलाशय उकाई बाँध किस नदी पर बना है?","optionsHi":["ताप्ती","माही","साबरमती","नर्मदा"],"explanationHi":"उकाई (नीचे की ओर काकरापार वियर के साथ) ताप्ती पर है। कडाना बाँध माही पर और सरदार सरोवर नर्मदा पर है।"},
  {"id":"geo-indian-rivers-92","question":"The Krishna Raja Sagar (KRS) dam near Mysuru, with the Brindavan gardens below it, is on the:","options":["Krishna","Kaveri","Tungabhadra","Kabini"],"answer":1,"explanation":"Despite its name, KRS is on the Kaveri, just below where the Hemavati and Lakshmana Tirtha join it. It was named after Krishnaraja Wadiyar IV, Maharaja of Mysore.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"मैसूरु के निकट कृष्णराज सागर (KRS) बाँध, जिसके नीचे वृंदावन उद्यान है, किस नदी पर है?","optionsHi":["कृष्णा","कावेरी","तुंगभद्रा","काबिनी"],"explanationHi":"नाम के विपरीत, KRS कावेरी पर है, ठीक उस स्थान के नीचे जहाँ हेमावती और लक्ष्मण तीर्थ उससे मिलती हैं। इसका नाम मैसूर के महाराजा कृष्णराज वाडियार चतुर्थ के नाम पर रखा गया।"},
  {"id":"geo-indian-rivers-93","question":"Cuttack, the old capital of Odisha, stands at the head of the delta of the:","options":["Brahmani","Baitarani","Mahanadi","Subarnarekha"],"answer":2,"explanation":"Cuttack lies where the Mahanadi divides, between the Mahanadi and its branch the Kathajodi. The delta spreads out from here towards the coast.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"ओडिशा की पुरानी राजधानी कटक किस नदी के डेल्टा के शीर्ष पर स्थित है?","optionsHi":["ब्राह्मणी","बैतरणी","महानदी","सुवर्णरेखा"],"explanationHi":"कटक वहाँ स्थित है जहाँ महानदी विभाजित होती है, महानदी और उसकी शाखा कठजोड़ी के बीच। डेल्टा यहीं से तट की ओर फैलता है।"},
  {"id":"geo-indian-rivers-94","question":"The Sutlej rises in Tibet from:","options":["Lake Mansarovar","Chemayungdung glacier","Rakas Tal (Langa Tso)","Beas Kund"],"answer":2,"explanation":"The Sutlej rises from Rakas Tal near Mansarovar and enters India at Shipki La. The Brahmaputra rises from the Chemayungdung glacier and the Beas from Beas Kund.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"सतलुज तिब्बत में किससे निकलती है?","optionsHi":["मानसरोवर झील","चेमायुंगडुंग हिमनद","राक्षस ताल (लांगा त्सो)","ब्यास कुंड"],"explanationHi":"सतलुज मानसरोवर के निकट राक्षस ताल से निकलती है और शिपकी ला से भारत में प्रवेश करती है। ब्रह्मपुत्र चेमायुंगडुंग हिमनद से और ब्यास ब्यास कुंड से निकलती है।"},
  {"id":"geo-indian-rivers-95","question":"The Bansagar dam, a joint project of Madhya Pradesh, Uttar Pradesh and Bihar, is on the:","options":["Ken","Son","Betwa","Narmada"],"answer":1,"explanation":"The Bansagar dam in Shahdol district, MP, is on the Son and supplies irrigation and power to all three States. The Ken–Betwa link joins two other Yamuna tributaries.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"मध्य प्रदेश, उत्तर प्रदेश और बिहार की संयुक्त परियोजना बाणसागर बाँध किस नदी पर है?","optionsHi":["केन","सोन","बेतवा","नर्मदा"],"explanationHi":"म.प्र. के शहडोल जिले में स्थित बाणसागर बाँध सोन पर है और तीनों राज्यों को सिंचाई तथा बिजली देता है। केन–बेतवा लिंक यमुना की अन्य दो सहायक नदियों को जोड़ता है।"},
  {"id":"geo-indian-rivers-96","question":"The Polavaram multipurpose project, declared a national project, is being built on the:","options":["Krishna","Penna","Vamsadhara","Godavari"],"answer":3,"explanation":"Polavaram is on the Godavari in Andhra Pradesh. It is to transfer Godavari water to the Krishna basin through the Polavaram right canal.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"राष्ट्रीय परियोजना घोषित की गई पोलावरम बहुउद्देशीय परियोजना किस नदी पर बनाई जा रही है?","optionsHi":["कृष्णा","पेन्ना","वंशधारा","गोदावरी"],"explanationHi":"पोलावरम आंध्र प्रदेश में गोदावरी पर है। इसके द्वारा पोलावरम दायीं नहर से गोदावरी का जल कृष्णा बेसिन में स्थानांतरित किया जाना है।"},
  {"id":"geo-indian-rivers-97","question":"The Almatti dam (Lal Bahadur Shastri dam) in north Karnataka is on the:","options":["Krishna","Tungabhadra","Bhima","Ghataprabha"],"answer":0,"explanation":"Almatti is on the Krishna in Vijayapura–Bagalkot district, and the height of its reservoir has been a point in the Krishna water dispute. The Tungabhadra dam is at Hosapete.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"उत्तरी कर्नाटक में आलमट्टी बाँध (लाल बहादुर शास्त्री बाँध) किस नदी पर है?","optionsHi":["कृष्णा","तुंगभद्रा","भीमा","घटप्रभा"],"explanationHi":"आलमट्टी विजयपुरा–बागलकोट जिले में कृष्णा पर है, और उसके जलाशय की ऊँचाई कृष्णा जल विवाद का एक मुद्दा रही है। तुंगभद्रा बाँध होसपेटे में है।"},
  {"id":"geo-indian-rivers-98","question":"The Barak, which flows through Manipur, Mizoram and Assam (past Silchar), enters Bangladesh and divides into:","options":["The Padma and the Jamuna","The Surma and the Kushiyara","The Meghna and the Teesta","The Karnaphuli and the Feni"],"answer":1,"explanation":"The Barak splits into the Surma and the Kushiyara in Bangladesh, and these later form the Meghna. The Meghna joins the Padma before reaching the Bay of Bengal.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"बराक, जो मणिपुर, मिजोरम और असम (सिलचर के निकट) से होकर बहती है, बांग्लादेश में प्रवेश करके किसमें विभाजित हो जाती है?","optionsHi":["पद्मा और जमुना","सूरमा और कुशियारा","मेघना और तीस्ता","कर्णफुली और फेनी"],"explanationHi":"बराक बांग्लादेश में सूरमा और कुशियारा में बँट जाती है, और ये आगे चलकर मेघना बनाती हैं। मेघना बंगाल की खाड़ी में पहुँचने से पहले पद्मा से मिलती है।"},
  {"id":"geo-indian-rivers-99","question":"The Ghaggar, a seasonal river that rises in the Shiwaliks and dies out in the Rajasthan desert, is known in Pakistan as the:","options":["Luni","Sutlej","Chenab","Hakra"],"answer":3,"explanation":"The Ghaggar–Hakra is a stream of inland drainage that ends in the sands near Hanumangarh. Many Harappan sites line its old bed, and some identify it with the Vedic Sarasvati.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"घग्गर, एक मौसमी नदी जो शिवालिक में निकलती है और राजस्थान के मरुस्थल में विलुप्त हो जाती है, पाकिस्तान में किस नाम से जानी जाती है?","optionsHi":["लूनी","सतलुज","चेनाब","हकरा"],"explanationHi":"घग्गर–हकरा आंतरिक अपवाह वाली धारा है, जो हनुमानगढ़ के निकट रेत में समाप्त हो जाती है। इसके पुराने तल के किनारे कई हड़प्पाई स्थल हैं, और कुछ लोग इसे वैदिक सरस्वती मानते हैं।"},
  {"id":"geo-indian-rivers-100","question":"The Hundru falls near Ranchi are formed by the:","options":["Damodar","South Koel","Subarnarekha","Barakar"],"answer":2,"explanation":"The Subarnarekha drops about 98 m at Hundru on the edge of the Ranchi plateau. The Damodar and Barakar flow east towards West Bengal.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"राँची के निकट हुंडरू जलप्रपात किसके द्वारा बनता है?","optionsHi":["दामोदर","दक्षिणी कोयल","सुवर्णरेखा","बराकर"],"explanationHi":"सुवर्णरेखा राँची पठार के किनारे हुंडरू में लगभग 98 मी नीचे गिरती है। दामोदर और बराकर पश्चिम बंगाल की ओर पूर्व में बहती हैं।"},
  {"id":"geo-indian-rivers-101","question":"The Gokak falls in Belagavi district, Karnataka, are on the:","options":["Ghataprabha","Malaprabha","Sharavathi","Tungabhadra"],"answer":0,"explanation":"The Ghataprabha, a tributary of the Krishna, forms the Gokak falls. The Sharavathi forms the Jog falls.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"कर्नाटक के बेलगावी जिले में गोकाक जलप्रपात किस नदी पर है?","optionsHi":["घटप्रभा","मालप्रभा","शरावती","तुंगभद्रा"],"explanationHi":"कृष्णा की सहायक नदी घटप्रभा गोकाक प्रपात बनाती है। शरावती जोग प्रपात बनाती है।"},
  {"id":"geo-indian-rivers-102","question":"The Shyok, which rises from the Rimo glacier near the Karakoram, joins the Indus near:","options":["Leh","Attock","Kargil","Skardu"],"answer":3,"explanation":"The Shyok runs through Ladakh and Baltistan and meets the Indus near Skardu. At Attock the Kabul river joins the Indus.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"श्योक, जो काराकोरम के निकट रिमो हिमनद से निकलती है, सिंधु से कहाँ के निकट मिलती है?","optionsHi":["लेह","अटक","कारगिल","स्कर्दू"],"explanationHi":"श्योक लद्दाख और बल्तिस्तान से होकर बहती है और स्कर्दू के निकट सिंधु से मिलती है। अटक में काबुल नदी सिंधु से मिलती है।"},
  {"id":"geo-indian-rivers-103","question":"Match the drainage pattern with an example: A. Dendritic B. Radial C. Centripetal D. Trellis. 1. Rivers flowing out in all directions from the Amarkantak range 2. Rivers of the northern plains, branching like a tree 3. Streams draining into Loktak lake 4. Parallel streams with tributaries joining at right angles, as in old folded hills","options":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Dendritic: tree-like, as in the Indo-Gangetic plain. Radial: from a central high point such as Amarkantak. Centripetal: streams draining into a basin, such as Loktak. Trellis: tributaries meeting the main stream at right angles in folded or structurally controlled country.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अपवाह प्रतिरूप का उदाहरण से मिलान कीजिए: A. वृक्षाकार (डेंड्राइटिक) B. अरीय (रेडियल) C. अभिकेंद्रीय (सेंट्रीपीटल) D. जालीनुमा (ट्रेलिस). 1. अमरकंटक श्रेणी से सभी दिशाओं में बहने वाली नदियाँ 2. उत्तरी मैदानों की नदियाँ, जो वृक्ष की तरह शाखाओं में बँटी हैं 3. लोकटक झील में गिरने वाली धाराएँ 4. समानांतर धाराएँ, जिनमें सहायक नदियाँ समकोण पर मिलती हैं, जैसा पुरानी वलित पहाड़ियों में होता है","optionsHi":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3"],"explanationHi":"वृक्षाकार: वृक्ष जैसा, जैसे सिंधु-गंगा के मैदान में। अरीय: किसी केंद्रीय ऊँचे बिंदु से, जैसे अमरकंटक। अभिकेंद्रीय: किसी द्रोणी में गिरने वाली धाराएँ, जैसे लोकटक। जालीनुमा: वलित या संरचनात्मक रूप से नियंत्रित क्षेत्र में सहायक नदियों का मुख्य धारा से समकोण पर मिलना।"},
  {"id":"geo-indian-rivers-104","question":"Assertion (A): The Indus, the Sutlej and the Brahmaputra cut across the Himalaya through deep gorges. Reason (R): They are antecedent rivers, older than the Himalaya, which kept cutting down their beds as the mountains rose.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"These rivers kept to their old courses while the Himalaya slowly rose, so they carved gorges through the ranges, such as the Indus gorge near Gilgit and the Dihang gorge of the Brahmaputra.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): सिंधु, सतलुज और ब्रह्मपुत्र गहरे महाखड्डों (गॉर्ज) से होकर हिमालय को काटती हैं। कारण (R): ये पूर्ववर्ती (एंटीसीडेंट) नदियाँ हैं, जो हिमालय से पुरानी हैं और पर्वतों के उठने के साथ अपने तल को काटती रहीं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"हिमालय के धीरे-धीरे उठने के दौरान ये नदियाँ अपने पुराने मार्गों पर बनी रहीं, इसलिए उन्होंने श्रेणियों में महाखड्ड काटे, जैसे गिलगित के निकट सिंधु का महाखड्ड और ब्रह्मपुत्र का दिहांग महाखड्ड।"},
  {"id":"geo-indian-rivers-105","question":"Match the National Waterway with its route: A. NW-1 B. NW-2 C. NW-3 D. NW-4. 1. Godavari and Krishna rivers with the Kakinada–Puducherry canals 2. West Coast Canal in Kerala 3. Brahmaputra from Dhubri to Sadiya 4. Ganga–Bhagirathi–Hooghly from Prayagraj to Haldia","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1"],"answer":2,"explanation":"NW-1 (Prayagraj–Haldia) is the longest. NW-2 is on the Brahmaputra, NW-3 is the West Coast Canal (Kottapuram–Kollam), and NW-4 links the Godavari and Krishna with the Kakinada–Puducherry canal system.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"राष्ट्रीय जलमार्ग का उसके मार्ग से मिलान कीजिए: A. NW-1 B. NW-2 C. NW-3 D. NW-4. 1. गोदावरी और कृष्णा नदियाँ, काकीनाडा–पुदुच्चेरी नहरों के साथ 2. केरल में पश्चिमी तट नहर 3. धुबरी से सादिया तक ब्रह्मपुत्र 4. प्रयागराज से हल्दिया तक गंगा–भागीरथी–हुगली","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1"],"explanationHi":"NW-1 (प्रयागराज–हल्दिया) सबसे लंबा है। NW-2 ब्रह्मपुत्र पर है, NW-3 पश्चिमी तट नहर (कोट्टापुरम–कोल्लम) है, और NW-4 गोदावरी और कृष्णा को काकीनाडा–पुदुच्चेरी नहर तंत्र से जोड़ता है।"},
  {"id":"geo-indian-rivers-106","question":"How many of these statements about the Kaveri are correct? I. The Hemavati, Kabini, Bhavani and Amaravati are its tributaries. II. It forms the river islands of Srirangapatna and Srirangam. III. It reaches the Bay of Bengal in Tamil Nadu, its old mouth being at Poompuhar (Kaveripattinam). IV. It rises at Trimbakeshwar.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Kaveri rises at Talakaveri in the Brahmagiri hills of Kodagu. Trimbakeshwar near Nashik is the source of the Godavari.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कावेरी के बारे में इनमें से कितने कथन सही हैं? I. हेमावती, काबिनी, भवानी और अमरावती इसकी सहायक नदियाँ हैं। II. यह श्रीरंगपटना और श्रीरंगम के नदी द्वीप बनाती है। III. यह तमिलनाडु में बंगाल की खाड़ी में पहुँचती है, और इसका पुराना मुहाना पूमपुहार (कावेरीपट्टिनम) था। IV. यह त्र्यंबकेश्वर से निकलती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। कावेरी कोडागु की ब्रह्मगिरि पहाड़ियों में तालकावेरी से निकलती है। नासिक के निकट त्र्यंबकेश्वर गोदावरी का उद्गम है।"},
  {"id":"geo-indian-rivers-107","question":"How many of these statements about the Chambal are correct? I. The Banas, Kali Sindh and Parbati are its tributaries. II. The Gandhi Sagar, Rana Pratap Sagar and Jawahar Sagar dams are on it. III. The National Chambal Sanctuary protects the gharial. IV. It joins the Yamuna in the Etawah region.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Chambal flows north through Madhya Pradesh and Rajasthan, with the Kota barrage below the three dams, and then forms the MP–Rajasthan and MP–UP boundaries before joining the Yamuna.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"चंबल के बारे में इनमें से कितने कथन सही हैं? I. बनास, काली सिंध और पार्वती इसकी सहायक नदियाँ हैं। II. गांधी सागर, राणा प्रताप सागर और जवाहर सागर बाँध इस पर हैं। III. राष्ट्रीय चंबल अभयारण्य घड़ियाल की रक्षा करता है। IV. यह इटावा क्षेत्र में यमुना से मिलती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। चंबल मध्य प्रदेश और राजस्थान से होकर उत्तर की ओर बहती है, तीनों बाँधों के नीचे कोटा बैराज है, फिर यह म.प्र.–राजस्थान और म.प्र.–उ.प्र. की सीमाएँ बनाकर यमुना से मिलती है।"},
  {"id":"geo-indian-rivers-108","question":"Arrange in chronological order: 1. Launch of the Ganga Action Plan 2. Launch of the Namami Gange programme 3. Ganga declared the National River 4. Setting up of the Damodar Valley Corporation","options":["1, 4, 3, 2","4, 1, 3, 2","4, 3, 1, 2","4, 1, 2, 3"],"answer":1,"explanation":"Damodar Valley Corporation 1948 → Ganga Action Plan 1986 → Ganga declared the National River 2008 → Namami Gange 2014.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालानुक्रमिक क्रम में व्यवस्थित कीजिए: 1. गंगा एक्शन प्लान का आरंभ 2. नमामि गंगे कार्यक्रम का आरंभ 3. गंगा को राष्ट्रीय नदी घोषित किया जाना 4. दामोदर घाटी निगम की स्थापना","optionsHi":["1, 4, 3, 2","4, 1, 3, 2","4, 3, 1, 2","4, 1, 2, 3"],"explanationHi":"दामोदर घाटी निगम 1948 → गंगा एक्शन प्लान 1986 → गंगा राष्ट्रीय नदी घोषित 2008 → नमामि गंगे 2014।"},
  {"id":"geo-indian-rivers-109","question":"How many of these statements about west-flowing rivers are correct? I. The Mandovi and the Zuari flow through Goa. II. The Netravati enters the Arabian Sea at Kannur. III. The Periyar flows into the Bay of Bengal. IV. The Kali (Kalinadi) reaches the sea at Karwar.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and IV are correct. II is wrong: the Netravati reaches the sea at Mangaluru in Karnataka. III is wrong: the Periyar flows west into the Arabian Sea near Kochi.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"पश्चिम की ओर बहने वाली नदियों के बारे में इनमें से कितने कथन सही हैं? I. मांडोवी और ज़ुआरी गोवा से होकर बहती हैं। II. नेत्रवती कन्नूर में अरब सागर में प्रवेश करती है। III. पेरियार बंगाल की खाड़ी में गिरती है। IV. काली (कालीनदी) कारवार में समुद्र में पहुँचती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और IV सही हैं। II गलत है: नेत्रवती कर्नाटक में मंगलुरु में समुद्र में पहुँचती है। III गलत है: पेरियार पश्चिम की ओर कोच्चि के निकट अरब सागर में गिरती है।"},
  {"id":"geo-indian-rivers-110","question":"Which of these is NOT a tributary of the Mahanadi?","options":["Wardha","Seonath","Hasdeo","Ib"],"answer":0,"explanation":"The Seonath, Hasdeo, Mand, Ib and Tel feed the Mahanadi. The Wardha joins the Wainganga to form the Pranhita, which flows into the Godavari.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सी महानदी की सहायक नदी नहीं है?","optionsHi":["वर्धा","शिवनाथ","हसदेव","इब"],"explanationHi":"शिवनाथ, हसदेव, मांड, इब और तेल महानदी में मिलती हैं। वर्धा वैनगंगा से मिलकर प्राणहिता बनाती है, जो गोदावरी में गिरती है।"},
  {"id":"geo-indian-rivers-111","question":"Assertion (A): The Ganga–Brahmaputra delta is the largest delta in the world. Reason (R): The two rivers together bring down an enormous load of Himalayan sediment and deposit it at the head of the Bay of Bengal.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The Ganga, Brahmaputra and Meghna together carry one of the world's largest sediment loads. The delta they have built, with the Sundarbans mangroves on its sea face, is the world's largest.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): गंगा–ब्रह्मपुत्र डेल्टा विश्व का सबसे बड़ा डेल्टा है। कारण (R): दोनों नदियाँ मिलकर हिमालय का भारी अवसाद लाती हैं और उसे बंगाल की खाड़ी के शीर्ष पर जमा करती हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"गंगा, ब्रह्मपुत्र और मेघना मिलकर विश्व के सबसे बड़े अवसाद भारों में से एक ढोती हैं। उनके द्वारा निर्मित डेल्टा, जिसके समुद्री मुख पर सुंदरबन के मैंग्रोव हैं, विश्व का सबसे बड़ा डेल्टा है।"},
  {"id":"geo-indian-rivers-112","question":"How many of these statements are correct? I. The Brahmani is formed by the union of the Koel and the Sankh near Sambalpur. II. The Baitarani rises in the Gonasika hills of Keonjhar. III. The Chilika lagoon lies in the Brahmani–Baitarani delta. IV. The Baitarani is a tributary of the Mahanadi.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct. The Koel and Sankh meet near Rourkela, not Sambalpur; the Brahmani–Baitarani delta holds Bhitarkanika, while Chilika lies south of the Mahanadi delta; and the Baitarani is an independent river.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"इनमें से कितने कथन सही हैं? I. ब्राह्मणी का निर्माण संबलपुर के निकट कोयल और शंख के मिलने से होता है। II. बैतरणी केंदुझर की गोनासिका पहाड़ियों से निकलती है। III. चिल्का लैगून ब्राह्मणी–बैतरणी डेल्टा में स्थित है। IV. बैतरणी महानदी की सहायक नदी है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है। कोयल और शंख राउरकेला के निकट मिलती हैं, संबलपुर के निकट नहीं; ब्राह्मणी–बैतरणी डेल्टा में भितरकनिका है, जबकि चिल्का महानदी डेल्टा के दक्षिण में है; और बैतरणी एक स्वतंत्र नदी है।"},
  {"id":"geo-indian-rivers-113","question":"Which of these cities is paired with the WRONG river?","options":["Vijayawada – Krishna","Nashik – Godavari","Surat – Tapi","Ludhiana – Beas"],"answer":3,"explanation":"Ludhiana stands near the Sutlej. Vijayawada has the Prakasam barrage on the Krishna, Nashik is on the upper Godavari, and Surat is near the mouth of the Tapi.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से कौन-सा नगर गलत नदी के साथ जोड़ा गया है?","optionsHi":["विजयवाड़ा – कृष्णा","नासिक – गोदावरी","सूरत – ताप्ती","लुधियाना – ब्यास"],"explanationHi":"लुधियाना सतलुज के निकट स्थित है। विजयवाड़ा में कृष्णा पर प्रकाशम बैराज है, नासिक ऊपरी गोदावरी पर है, और सूरत ताप्ती के मुहाने के निकट है।"},
  {"id":"geo-indian-rivers-114","question":"How many of these statements about the Ganga basin are correct? I. It is the largest river basin in India. II. Uttar Pradesh has the longest stretch of the Ganga among the States. III. Below the Farakka barrage the main stream enters Bangladesh as the Padma. IV. The basin covers more than a quarter of India's area.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Ganga basin covers about 26% of India's area and spans 11 States. The Bhagirathi–Hooghly branch carries water south to Kolkata while the Padma flows east.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"गंगा बेसिन के बारे में इनमें से कितने कथन सही हैं? I. यह भारत का सबसे बड़ा नदी बेसिन है। II. राज्यों में गंगा का सबसे लंबा विस्तार उत्तर प्रदेश में है। III. फरक्का बैराज के नीचे मुख्य धारा पद्मा के रूप में बांग्लादेश में प्रवेश करती है। IV. बेसिन भारत के क्षेत्रफल के एक-चौथाई से अधिक भाग को ढकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। गंगा बेसिन भारत के लगभग 26% क्षेत्रफल को ढकता है और 11 राज्यों में फैला है। भागीरथी–हुगली शाखा जल को दक्षिण की ओर कोलकाता ले जाती है, जबकि पद्मा पूर्व की ओर बहती है।"},
  {"id":"geo-indian-rivers-115","question":"Nashik, one of the four sites of the Kumbh Mela, stands on the bank of the river:","options":["Godavari","Shipra","Narmada","Mula–Mutha"],"answer":0,"explanation":"The Godavari rises at Trimbakeshwar close to Nashik and flows past the city. The Kumbh is held at Haridwar (Ganga), Prayagraj (Sangam), Ujjain (Shipra) and Nashik (Godavari); the Mula–Mutha flows through Pune.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"कुंभ मेले के चार स्थलों में से एक नासिक किस नदी के तट पर स्थित है?","optionsHi":["गोदावरी","शिप्रा","नर्मदा","मुला–मुठा"],"explanationHi":"गोदावरी नासिक के निकट त्र्यंबकेश्वर से निकलती है और नगर के पास से बहती है। कुंभ हरिद्वार (गंगा), प्रयागराज (संगम), उज्जैन (शिप्रा) और नासिक (गोदावरी) में आयोजित होता है; मुला–मुठा पुणे से होकर बहती है।"},
  {"id":"geo-indian-rivers-116","question":"Guwahati, the largest city of the north-east, lies on the bank of the:","options":["Barak","Brahmaputra","Kolong (Kalang)","Subansiri"],"answer":1,"explanation":"Guwahati sits on the south bank of the Brahmaputra. The Barak flows past Silchar in southern Assam and the Kolong is a small distributary channel through Nagaon.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"पूर्वोत्तर का सबसे बड़ा शहर गुवाहाटी किस नदी के तट पर स्थित है?","optionsHi":["बराक","ब्रह्मपुत्र","कोलोंग (कलंग)","सुबनसिरी"],"explanationHi":"गुवाहाटी ब्रह्मपुत्र के दक्षिणी तट पर स्थित है। बराक दक्षिणी असम में सिलचर के पास से बहती है और कोलोंग नगाँव से होकर बहने वाली एक छोटी वितरिका है।"},
  {"id":"geo-indian-rivers-117","question":"The Teesta, whose water sharing is a long-pending issue with Bangladesh, flows through which Indian states before entering Bangladesh?","options":["Assam and Meghalaya","Bihar and West Bengal","Sikkim and West Bengal","Arunachal Pradesh and Assam"],"answer":2,"explanation":"The Teesta rises in north Sikkim, flows past the Darjeeling hills into the plains of north Bengal and then joins the Brahmaputra (Jamuna) in Bangladesh.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"तीस्ता, जिसके जल बँटवारे का मुद्दा बांग्लादेश के साथ लंबे समय से लंबित है, बांग्लादेश में प्रवेश करने से पहले भारत के किन राज्यों से होकर बहती है?","optionsHi":["असम और मेघालय","बिहार और पश्चिम बंगाल","सिक्किम और पश्चिम बंगाल","अरुणाचल प्रदेश और असम"],"explanationHi":"तीस्ता उत्तरी सिक्किम में निकलती है, दार्जिलिंग की पहाड़ियों के निकट से उत्तरी बंगाल के मैदानों में बहती है और फिर बांग्लादेश में ब्रह्मपुत्र (जमुना) से मिलती है।"},
  {"id":"geo-indian-rivers-118","question":"The Sabarmati, on which Ahmedabad stands, rises in the:","options":["Satpura range of Madhya Pradesh","Western Ghats near Nashik","Saurashtra plateau","Aravalli hills of Rajasthan"],"answer":3,"explanation":"The Sabarmati rises in the Aravallis in Udaipur district, Rajasthan, and flows south-west across Gujarat into the Gulf of Khambhat.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"साबरमती, जिस पर अहमदाबाद स्थित है, कहाँ से निकलती है?","optionsHi":["मध्य प्रदेश की सतपुड़ा श्रेणी","नासिक के निकट पश्चिमी घाट","सौराष्ट्र पठार","राजस्थान की अरावली पहाड़ियाँ"],"explanationHi":"साबरमती राजस्थान के उदयपुर जिले में अरावली से निकलती है और गुजरात के आर-पार दक्षिण-पश्चिम की ओर बहकर खंभात की खाड़ी में गिरती है।"},
  {"id":"geo-indian-rivers-119","question":"The Mullaperiyar dam, which lies in Kerala but is operated by Tamil Nadu under a lease from the colonial period, is built on the:","options":["Periyar","Kaveri","Vaigai","Bharathapuzha"],"answer":0,"explanation":"Mullaperiyar (1895) is on the Periyar in Idukki district; its water is diverted east through a tunnel into the Vaigai basin of Tamil Nadu, which is the root of the inter-state dispute.","difficulty":"moderate","source":"State PSC · SSC CGL","questionHi":"मुल्लापेरियार बाँध, जो केरल में स्थित है किंतु औपनिवेशिक काल के पट्टे के अंतर्गत तमिलनाडु द्वारा संचालित होता है, किस नदी पर बना है?","optionsHi":["पेरियार","कावेरी","वैगई","भारतपुझा"],"explanationHi":"मुल्लापेरियार (1895) इडुक्की जिले में पेरियार पर है; इसका जल एक सुरंग से पूर्व की ओर तमिलनाडु के वैगई बेसिन में मोड़ा जाता है, जो अंतर-राज्यीय विवाद की जड़ है।"},
  {"id":"geo-indian-rivers-120","question":"Majuli, a large inhabited river island known for its Vaishnava satras, lies in the river:","options":["Ganga","Brahmaputra","Godavari","Mahanadi"],"answer":1,"explanation":"Majuli is in the Brahmaputra in upper Assam and became a district in 2016. Its area keeps shrinking because of bank erosion by the braided river.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"माजुली, एक विशाल आबाद नदी द्वीप जो अपने वैष्णव सत्रों के लिए प्रसिद्ध है, किस नदी में स्थित है?","optionsHi":["गंगा","ब्रह्मपुत्र","गोदावरी","महानदी"],"explanationHi":"माजुली ऊपरी असम में ब्रह्मपुत्र में है और 2016 में जिला बना। गुंफित (braided) नदी द्वारा तटीय अपरदन के कारण इसका क्षेत्रफल घटता जा रहा है।"},
  {"id":"geo-indian-rivers-121","question":"Which of these west-flowing rivers crosses the Tropic of Cancer twice?","options":["Narmada","Tapi","Mahi","Luni"],"answer":2,"explanation":"The Mahi rises in the Vindhyas of Madhya Pradesh, loops north into Rajasthan (Banswara) and turns back south-west through Gujarat, so it crosses the Tropic of Cancer twice before reaching the Gulf of Khambhat.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पश्चिम की ओर बहने वाली इनमें से कौन-सी नदी कर्क रेखा को दो बार पार करती है?","optionsHi":["नर्मदा","ताप्ती","माही","लूनी"],"explanationHi":"माही मध्य प्रदेश के विंध्य में निकलती है, उत्तर की ओर राजस्थान (बाँसवाड़ा) में मुड़ती है और फिर गुजरात से होकर दक्षिण-पश्चिम की ओर लौटती है, इसलिए खंभात की खाड़ी में पहुँचने से पहले वह कर्क रेखा को दो बार पार करती है।"},
  {"id":"geo-indian-rivers-122","question":"The Pranhita, a major left-bank tributary of the Godavari, is formed by the union of the:","options":["Bhima and Tungabhadra","Tawa and Hiran","Manjira and Purna","Wardha and Wainganga"],"answer":3,"explanation":"The Wardha and the Wainganga meet in eastern Maharashtra to form the Pranhita, which joins the Godavari on the Telangana–Maharashtra border. Bhima and Tungabhadra are Krishna tributaries.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"प्राणहिता, गोदावरी की एक प्रमुख बाएँ तट की सहायक नदी, किनके मिलने से बनती है?","optionsHi":["भीमा और तुंगभद्रा","तवा और हिरण","मंजीरा और पूर्णा","वर्धा और वैनगंगा"],"explanationHi":"वर्धा और वैनगंगा पूर्वी महाराष्ट्र में मिलकर प्राणहिता बनाती हैं, जो तेलंगाना–महाराष्ट्र सीमा पर गोदावरी से मिलती है। भीमा और तुंगभद्रा कृष्णा की सहायक नदियाँ हैं।"},
  {"id":"geo-indian-rivers-123","question":"The Wular lake, one of the largest freshwater lakes in India, is fed and drained by the:","options":["Jhelum","Chenab","Ravi","Indus"],"answer":0,"explanation":"The Jhelum flows into the Wular lake in Bandipora district and leaves it near Sopore, so the lake acts as a natural flood reservoir for the river.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"वुलर झील, जो भारत की सबसे बड़ी मीठे पानी की झीलों में से एक है, किस नदी से भरती और खाली होती है?","optionsHi":["झेलम","चेनाब","रावी","सिंधु"],"explanationHi":"झेलम बांदीपोरा जिले में वुलर झील में बहती है और सोपोर के निकट उससे बाहर निकलती है, इसलिए झील नदी के लिए एक प्राकृतिक बाढ़ जलाशय का काम करती है।"},
  {"id":"geo-indian-rivers-124","question":"The Kolleru lake in Andhra Pradesh lies between the deltas of the:","options":["Mahanadi and Brahmani","Godavari and Krishna","Krishna and Penna","Kaveri and Vaigai"],"answer":1,"explanation":"Kolleru is a shallow freshwater lake between the Godavari and Krishna deltas. Chilika, a brackish lagoon, lies south of the Mahanadi delta in Odisha.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"आंध्र प्रदेश की कोल्लेरु झील किन डेल्टाओं के बीच स्थित है?","optionsHi":["महानदी और ब्राह्मणी","गोदावरी और कृष्णा","कृष्णा और पेन्ना","कावेरी और वैगई"],"explanationHi":"कोल्लेरु गोदावरी और कृष्णा डेल्टाओं के बीच स्थित एक उथली मीठे पानी की झील है। चिल्का, एक खारे पानी की लैगून, ओडिशा में महानदी डेल्टा के दक्षिण में है।"},
  {"id":"geo-indian-rivers-125","question":"The river that forms much of the boundary between Uttarakhand and Nepal is the:","options":["Gandak","Ramganga","Mahakali","Bagmati"],"answer":2,"explanation":"The Kali (Mahakali), called the Sharda further downstream, marks the western boundary of Nepal with Uttarakhand. The Ramganga rises inside Uttarakhand, while the Gandak and Bagmati flow out of Nepal into Bihar.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"उत्तराखंड और नेपाल के बीच की अधिकांश सीमा बनाने वाली नदी कौन-सी है?","optionsHi":["गंडक","रामगंगा","महाकाली","बागमती"],"explanationHi":"काली (महाकाली), जिसे आगे नीचे शारदा कहा जाता है, नेपाल की उत्तराखंड के साथ पश्चिमी सीमा बनाती है। रामगंगा उत्तराखंड के भीतर से निकलती है, जबकि गंडक और बागमती नेपाल से निकलकर बिहार में बहती हैं।"},
  {"id":"geo-indian-rivers-126","question":"The Chenab is formed in Himachal Pradesh by the confluence of the:","options":["Tunga and Bhadra","Bhagirathi and Alaknanda","Dihang and Lohit","Chandra and Bhaga"],"answer":3,"explanation":"The Chandra and the Bhaga meet at Tandi in Lahaul to form the Chandrabhaga, known as the Chenab as it flows into Jammu and Kashmir.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"हिमाचल प्रदेश में चेनाब का निर्माण किनके संगम से होता है?","optionsHi":["तुंगा और भद्रा","भागीरथी और अलकनंदा","दिहांग और लोहित","चंद्र और भागा"],"explanationHi":"चंद्र और भागा लाहौल में तांदी में मिलकर चंद्रभागा बनाती हैं, जो जम्मू-कश्मीर में बहते हुए चेनाब कहलाती है।"},
  {"id":"geo-indian-rivers-127","question":"Which of these rivers does NOT flow through a rift valley?","options":["Krishna","Narmada","Tapi","Damodar"],"answer":0,"explanation":"The Narmada and Tapi occupy rift troughs, and the Damodar flows through a rift that holds the Gondwana coal of Jharia and Raniganj. The Krishna flows across the plateau in a normal valley and builds a delta.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कौन-सी नदी भ्रंश घाटी से होकर नहीं बहती?","optionsHi":["कृष्णा","नर्मदा","ताप्ती","दामोदर"],"explanationHi":"नर्मदा और ताप्ती भ्रंश द्रोणियों में हैं, और दामोदर एक ऐसे भ्रंश से बहती है जिसमें झरिया और रानीगंज का गोंडवाना कोयला है। कृष्णा पठार के आर-पार सामान्य घाटी में बहती है और डेल्टा बनाती है।"},
  {"id":"geo-indian-rivers-128","question":"Match the tributary with its main river. A. Indravati  B. Bhavani  C. Tawa  D. Hasdeo; 1. Mahanadi  2. Narmada  3. Kaveri  4. Godavari","options":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-1, B-3, C-2, D-4","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"The Indravati joins the Godavari, the Bhavani the Kaveri (in Tamil Nadu), the Tawa the Narmada (Tawa reservoir in Madhya Pradesh), and the Hasdeo the Mahanadi in Chhattisgarh.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"सहायक नदी का उसकी मुख्य नदी से मिलान कीजिए। A. इंद्रावती  B. भवानी  C. तवा  D. हसदेव; 1. महानदी  2. नर्मदा  3. कावेरी  4. गोदावरी","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-1, B-3, C-2, D-4","A-4, B-3, C-1, D-2"],"explanationHi":"इंद्रावती गोदावरी में मिलती है, भवानी कावेरी में (तमिलनाडु में), तवा नर्मदा में (मध्य प्रदेश में तवा जलाशय), और हसदेव छत्तीसगढ़ में महानदी में।"},
  {"id":"geo-indian-rivers-129","question":"Arrange these cities in the order a boat would pass them going down the Ganga: 1. Patna  2. Kanpur  3. Varanasi  4. Prayagraj","options":["2-3-4-1","4-2-3-1","2-4-3-1","2-4-1-3"],"answer":2,"explanation":"Downstream from Haridwar the Ganga passes Kanpur, then meets the Yamuna at Prayagraj, then flows past Varanasi and on to Patna in Bihar.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"इन नगरों को उस क्रम में व्यवस्थित कीजिए जिसमें गंगा में नीचे की ओर जाती कोई नाव उनसे गुजरेगी: 1. पटना  2. कानपुर  3. वाराणसी  4. प्रयागराज","optionsHi":["2-3-4-1","4-2-3-1","2-4-3-1","2-4-1-3"],"explanationHi":"हरिद्वार से नीचे की ओर गंगा कानपुर से गुजरती है, फिर प्रयागराज में यमुना से मिलती है, फिर वाराणसी के पास से बहकर बिहार में पटना पहुँचती है।"},
  {"id":"geo-indian-rivers-130","question":"How many of these statements about the Krishna are correct? I. It rises near Mahabaleshwar in the Western Ghats. II. The Bhima and the Indravati are among its tributaries. III. The Srisailam and Nagarjuna Sagar dams are built on it. IV. It enters the sea through an estuary without forming a delta.","options":["Only one","Only two","All four","Only three"],"answer":1,"explanation":"I and III are correct. II is wrong: the Bhima is a Krishna tributary but the Indravati joins the Godavari. IV is wrong: the Krishna builds a large delta on the Andhra coast.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कृष्णा के बारे में इनमें से कितने कथन सही हैं? I. यह पश्चिमी घाट में महाबलेश्वर के निकट से निकलती है। II. भीमा और इंद्रावती इसकी सहायक नदियों में हैं। III. श्रीशैलम और नागार्जुन सागर बाँध इस पर बने हैं। IV. यह डेल्टा बनाए बिना ज्वारनदमुख (एस्चुअरी) से होकर समुद्र में प्रवेश करती है।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"I और III सही हैं। II गलत है: भीमा कृष्णा की सहायक नदी है, किंतु इंद्रावती गोदावरी में मिलती है। IV गलत है: कृष्णा आंध्र तट पर एक बड़ा डेल्टा बनाती है।"},
  {"id":"geo-indian-rivers-131","question":"Assertion (A): Rivers of the Konkan and Malabar coasts are short and swift. Reason (R): The Western Ghats rise close to the west coast, leaving a narrow, steep slope down to the sea.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"With the watershed only 50–80 km from the sea, west-coast rivers drop steeply over a short course, forming falls such as Jog and having little room for deltas.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कोंकण और मालाबार तटों की नदियाँ छोटी और तेज बहने वाली हैं। कारण (R): पश्चिमी घाट पश्चिमी तट के निकट ही उठते हैं, जिससे समुद्र तक एक संकरी, तीव्र ढाल बची रहती है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"जलविभाजक समुद्र से केवल 50–80 किमी की दूरी पर होने से पश्चिमी तट की नदियाँ छोटे मार्ग में तेजी से नीचे उतरती हैं, जोग जैसे प्रपात बनाती हैं और डेल्टा के लिए उनके पास बहुत कम स्थान होता है।"},
  {"id":"geo-indian-rivers-132","question":"How many of these pairs of river and the state where it rises are correct? I. Mahanadi — Chhattisgarh  II. Krishna — Maharashtra  III. Kaveri — Karnataka  IV. Tapi — Madhya Pradesh","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: the Mahanadi rises at Sihawa (Chhattisgarh), the Krishna at Mahabaleshwar (Maharashtra), the Kaveri at Talakaveri (Karnataka) and the Tapi at Multai in Betul district (Madhya Pradesh).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"नदी और उस राज्य के इनमें से कितने युग्म सही हैं जहाँ वह निकलती है? I. महानदी — छत्तीसगढ़  II. कृष्णा — महाराष्ट्र  III. कावेरी — कर्नाटक  IV. ताप्ती — मध्य प्रदेश","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: महानदी सिहावा (छत्तीसगढ़) से, कृष्णा महाबलेश्वर (महाराष्ट्र) से, कावेरी तालकावेरी (कर्नाटक) से और ताप्ती बैतूल जिले के मुलताई (मध्य प्रदेश) से निकलती है।"},
  {"id":"geo-indian-rivers-133","question":"Match the dam with the river it is built on. A. Idukki  B. Srisailam  C. Ranjit Sagar  D. Gandhi Sagar; 1. Ravi  2. Chambal  3. Periyar  4. Krishna","options":["A-3, B-1, C-4, D-2","A-2, B-4, C-1, D-3","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Idukki's arch dam is on the Periyar in Kerala, Srisailam on the Krishna, Ranjit Sagar (Thein dam) on the Ravi at the Punjab–J&K border, and Gandhi Sagar on the Chambal in Madhya Pradesh.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"बाँध का उस नदी से मिलान कीजिए जिस पर वह बना है। A. इडुक्की  B. श्रीशैलम  C. रंजीत सागर  D. गांधी सागर; 1. रावी  2. चंबल  3. पेरियार  4. कृष्णा","optionsHi":["A-3, B-1, C-4, D-2","A-2, B-4, C-1, D-3","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"explanationHi":"इडुक्की का चाप बाँध केरल में पेरियार पर है, श्रीशैलम कृष्णा पर, रंजीत सागर (थीन बाँध) पंजाब–जम्मू-कश्मीर सीमा पर रावी पर, और गांधी सागर मध्य प्रदेश में चंबल पर।"},
  {"id":"geo-indian-rivers-134","question":"Assertion (A): The water of the Luni becomes saline in its lower course. Reason (R): It flows through an arid region where salt-bearing soils and high evaporation concentrate salts in the water.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true","Both A and R are true but R is not the correct explanation of A"],"answer":1,"explanation":"The Luni, also called Lavanavari (salt river), is fresh near Ajmer but turns brackish below Balotra as it crosses salty desert soils, and finally dies out in the Rann of Kutch.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): लूनी का जल अपने निचले मार्ग में लवणीय हो जाता है। कारण (R): यह एक शुष्क क्षेत्र से बहती है, जहाँ लवणयुक्त मिट्टी और उच्च वाष्पन जल में लवणों को सांद्रित कर देते हैं।","optionsHi":["A सही है, किंतु R गलत है","A और R दोनों सही हैं और R, A की सही व्याख्या है","A गलत है, किंतु R सही है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"लूनी, जिसे लवणवारी (नमक की नदी) भी कहते हैं, अजमेर के निकट मीठी है, किंतु बालोतरा के नीचे लवणीय मरुस्थलीय मिट्टी से गुजरते हुए खारी हो जाती है, और अंततः कच्छ के रण में समाप्त हो जाती है।"},
  {"id":"geo-indian-rivers-135","question":"Which of these is NOT a right-bank tributary of the Yamuna?","options":["Chambal","Betwa","Ken","Hindon"],"answer":3,"explanation":"The Chambal, Sindh, Betwa and Ken drain the peninsular uplands and join the Yamuna from the south (right bank). The Hindon rises in the Shiwaliks and joins from the left, near Delhi–Noida.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"इनमें से कौन-सी यमुना की दाएँ तट की सहायक नदी नहीं है?","optionsHi":["चंबल","बेतवा","केन","हिंडन"],"explanationHi":"चंबल, सिंध, बेतवा और केन प्रायद्वीपीय उच्चभूमि का अपवाह लाती हैं और यमुना में दक्षिण (दाएँ तट) से मिलती हैं। हिंडन शिवालिक में निकलती है और दिल्ली–नोएडा के निकट बाएँ तट से मिलती है।"},
  {"id":"geo-indian-rivers-136","question":"The Zanskar river, whose frozen gorge in winter forms the route of the 'Chadar' trek, joins the Indus near:","options":["Nimu, near Leh","Skardu, Baltistan","Attock, Pakistan","Kargil, Ladakh"],"answer":0,"explanation":"The Zanskar flows north from the Zanskar range and meets the Indus at Nimu, west of Leh. The Shyok and the Gilgit join the Indus further downstream, and the Kabul joins it at Attock.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"ज़ांस्कर नदी, जिसकी जमी हुई घाटी सर्दियों में ‘चादर’ ट्रेक का मार्ग बनाती है, सिंधु से कहाँ के निकट मिलती है?","optionsHi":["निमू, लेह के निकट","स्कर्दू, बल्तिस्तान","अटक, पाकिस्तान","कारगिल, लद्दाख"],"explanationHi":"ज़ांस्कर, ज़ांस्कर श्रेणी से उत्तर की ओर बहती है और लेह के पश्चिम में निमू में सिंधु से मिलती है। श्योक और गिलगित सिंधु में आगे नीचे मिलती हैं, और काबुल अटक में उससे मिलती है।"},
  {"id":"geo-indian-rivers-137","question":"The Tapi rises near Multai in the Satpura range, in which district?","options":["Nashik district of Maharashtra","Betul district of Madhya Pradesh","Mandla district of Madhya Pradesh","Raipur district of Chhattisgarh"],"answer":1,"explanation":"The Tapi rises at Multai in Betul and flows west through a rift valley to the Gulf of Khambhat near Surat. Nashik is the source area of the Godavari, a frequent confusion.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"ताप्ती सतपुड़ा श्रेणी में मुलताई के निकट से निकलती है; यह किस जिले में है?","optionsHi":["महाराष्ट्र का नासिक जिला","मध्य प्रदेश का बैतूल जिला","मध्य प्रदेश का मंडला जिला","छत्तीसगढ़ का रायपुर जिला"],"explanationHi":"ताप्ती बैतूल के मुलताई से निकलती है और भ्रंश घाटी से होकर पश्चिम की ओर बहकर सूरत के निकट खंभात की खाड़ी में गिरती है। नासिक गोदावरी का उद्गम क्षेत्र है, जो बार-बार का भ्रम है।"},
  {"id":"geo-indian-rivers-138","question":"The Kallanai (Grand Anicut), among the oldest water-diversion structures in the world still in use, was built across the Kaveri by:","options":["Rajaraja I","Sir Arthur Cotton","Karikala Chola","Krishnadevaraya"],"answer":2,"explanation":"Tradition credits the early Chola king Karikala (around the 2nd century CE) with the stone dam; Sir Arthur Cotton studied and remodelled it in the 19th century and later built the Godavari anicut.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"कल्लनई (ग्रैंड अनिकट), जो विश्व की अब भी प्रयोग में आने वाली सबसे प्राचीन जल-अपवर्तन संरचनाओं में से एक है, कावेरी पर किसके द्वारा बनवाया गया था?","optionsHi":["राजराज प्रथम","सर आर्थर कॉटन","करिकाल चोल","कृष्णदेवराय"],"explanationHi":"परंपरा के अनुसार इस पत्थर के बाँध का श्रेय आरंभिक चोल राजा करिकाल (लगभग दूसरी शताब्दी ई.) को दिया जाता है; सर आर्थर कॉटन ने 19वीं शताब्दी में इसका अध्ययन कर इसे नया रूप दिया और बाद में गोदावरी अनिकट बनवाया।"},
  {"id":"geo-indian-rivers-139","question":"The Bhitarkanika mangroves of Odisha, known for their saltwater crocodiles, lie in the delta of the:","options":["Brahmani and Baitarani","Godavari and Sabari","Krishna and Bhima","Rushikulya and Vamsadhara"],"answer":0,"explanation":"Bhitarkanika in Kendrapara district is formed by the Brahmani, Baitarani and Dhamra channels and is India's second-largest mangrove ecosystem after the Sundarbans. The Rushikulya is known for olive ridley nesting, not mangroves.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ओडिशा के भितरकनिका मैंग्रोव, जो अपने खारे पानी के मगरमच्छों के लिए जाने जाते हैं, किस नदी-डेल्टा में स्थित हैं?","optionsHi":["ब्राह्मणी और बैतरणी","गोदावरी और सबरी","कृष्णा और भीमा","ऋषिकुल्या और वंशधारा"],"explanationHi":"केंद्रपाड़ा जिले में भितरकनिका ब्राह्मणी, बैतरणी और धामरा धाराओं से बना है और सुंदरबन के बाद भारत का दूसरा सबसे बड़ा मैंग्रोव पारिस्थितिक तंत्र है। ऋषिकुल्या ऑलिव रिडले कछुओं के घोंसलों के लिए जानी जाती है, मैंग्रोव के लिए नहीं।"},
  {"id":"geo-indian-rivers-140","question":"The Manas, along which the Manas National Park lies, enters Assam from:","options":["Arunachal Pradesh","Tibet directly","Nepal","Bhutan"],"answer":3,"explanation":"The Manas flows out of the Bhutan Himalaya and joins the Brahmaputra from the north; the park adjoins Bhutan's Royal Manas National Park across the border.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"मानस, जिसके किनारे मानस राष्ट्रीय उद्यान स्थित है, असम में कहाँ से प्रवेश करती है?","optionsHi":["अरुणाचल प्रदेश","सीधे तिब्बत से","नेपाल","भूटान"],"explanationHi":"मानस भूटान हिमालय से निकलकर उत्तर से ब्रह्मपुत्र में मिलती है; यह उद्यान सीमा के पार भूटान के रॉयल मानस राष्ट्रीय उद्यान से सटा हुआ है।"},
  {"id":"geo-indian-rivers-141","question":"An ox-bow lake is formed when:","options":["a glacier scoops out a rock basin that later fills with meltwater","a river cuts across a meander neck and the old loop is sealed off","a landslide blocks a mountain valley and ponds the river behind it","a sand bar grows across a coastal inlet and cuts it off from the sea"],"answer":1,"explanation":"On flat floodplains meanders grow until a flood breaches their neck; deposits then seal the old loop, leaving a crescent lake, common along the Ganga in Bihar. A sand bar across an inlet forms a lagoon, not an ox-bow.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"चापाकार झील (ऑक्स-बो लेक) कब बनती है?","optionsHi":["जब कोई हिमनद चट्टानी गड्ढा खोदता है, जो बाद में पिघले जल से भर जाता है","जब कोई नदी विसर्प की ग्रीवा को काट देती है और पुराना मोड़ अलग हो जाता है","जब भूस्खलन पर्वतीय घाटी को रोक देता है और नदी पीछे जल से भर जाती है","जब कोई रेत की पट्टी तटीय खाड़ी के आर-पार उग आती है और उसे समुद्र से काट देती है"],"explanationHi":"समतल बाढ़ के मैदानों में विसर्प तब तक बढ़ते हैं जब तक बाढ़ उनकी ग्रीवा को तोड़ नहीं देती; फिर जमाव पुराने मोड़ को बंद कर देते हैं, जिससे अर्धचंद्राकार झील बनती है, जो बिहार में गंगा के किनारे आम है। खाड़ी के आर-पार रेत की पट्टी लैगून बनाती है, चापाकार झील नहीं।"},
  {"id":"geo-indian-rivers-142","question":"The Yarlung Tsangpo (Brahmaputra) makes a sharp U-turn through a very deep gorge around which peak before entering India as the Siang (Dihang)?","options":["Kangchenjunga","Nanga Parbat","Namcha Barwa","Gurla Mandhata"],"answer":2,"explanation":"The Tsangpo bends around Namcha Barwa at the eastern end of the Himalaya. Nanga Parbat marks the Indus bend at the western end, the usual trap.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"यारलुंग सांगपो (ब्रह्मपुत्र) सियांग (दिहांग) के रूप में भारत में प्रवेश करने से पहले किस चोटी के चारों ओर एक बहुत गहरे महाखड्ड से होकर तीखा यू-टर्न लेती है?","optionsHi":["कंचनजंगा","नंगा पर्वत","नामचा बरवा","गुरला मांधाता"],"explanationHi":"सांगपो हिमालय के पूर्वी छोर पर नामचा बरवा के चारों ओर मुड़ती है। नंगा पर्वत पश्चिमी छोर पर सिंधु के मोड़ को चिह्नित करता है, जो प्रायः भ्रम का कारण बनता है।"},
  {"id":"geo-indian-rivers-143","question":"The Jog Falls in Shivamogga district of Karnataka are formed by the:","options":["Kali","Netravati","Tunga","Sharavati"],"answer":3,"explanation":"The Sharavati, a west-flowing river, plunges over the Western Ghats escarpment at Jog; the Linganamakki dam upstream regulates it for hydro power.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"कर्नाटक के शिवमोगा जिले में जोग प्रपात किसके द्वारा बनता है?","optionsHi":["काली","नेत्रवती","तुंगा","शरावती"],"explanationHi":"पश्चिम की ओर बहने वाली शरावती जोग में पश्चिमी घाट की कगार से नीचे गिरती है; ऊपर की ओर लिंगनमक्की बाँध जलविद्युत के लिए उसे नियंत्रित करता है।"},
  {"id":"geo-indian-rivers-144","question":"The Jayakwadi project at Paithan, which irrigates the drought-prone Marathwada region of Maharashtra, is built on the:","options":["Krishna","Bhima","Godavari","Tapi"],"answer":2,"explanation":"Jayakwadi (Nath Sagar) at Paithan is on the Godavari and is Marathwada's largest irrigation project; the Krishna and Bhima drain western and southern Maharashtra, while the Tapi drains Khandesh.","difficulty":"moderate","questionHi":"महाराष्ट्र के सूखा-प्रभावित मराठवाड़ा क्षेत्र की सिंचाई करने वाली, पैठण स्थित जायकवाड़ी परियोजना किस नदी पर बनी है?","optionsHi":["कृष्णा","भीमा","गोदावरी","तापी"],"explanationHi":"पैठण का जायकवाड़ी (नाथ सागर) गोदावरी पर है और मराठवाड़ा की सबसे बड़ी सिंचाई परियोजना है; कृष्णा और भीमा पश्चिमी-दक्षिणी महाराष्ट्र में तथा तापी खानदेश में बहती हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-145","question":"The Gandikota gorge in Andhra Pradesh, often called the 'Grand Canyon of India', has been cut through the Erramala hills by the:","options":["Penna (Pennar)","Krishna","Godavari","Tungabhadra"],"answer":0,"explanation":"The Penna (Pennar) has carved the Gandikota gorge in Kadapa district; the Krishna, Tungabhadra and Godavari lie in other parts of the peninsula.","difficulty":"hard","questionHi":"आंध्र प्रदेश की गंडीकोटा घाटी, जिसे प्रायः 'भारत का ग्रैंड कैन्यन' कहा जाता है, एर्रामाला पहाड़ियों को काटकर किस नदी ने बनाई है?","optionsHi":["पेन्ना (पेन्नार)","कृष्णा","गोदावरी","तुंगभद्रा"],"explanationHi":"पेन्ना (पेन्नार) ने कडप्पा जिले में गंडीकोटा घाटी का निर्माण किया है; कृष्णा, तुंगभद्रा और गोदावरी प्रायद्वीप के अन्य भागों में बहती हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-146","question":"Jamshedpur, the steel city of Jharkhand, lies at the confluence of the Subarnarekha and the:","options":["Koel","Kharkai","Sankh","Barakar"],"answer":1,"explanation":"Jamshedpur stands where the Kharkai joins the Subarnarekha. The Sankh and Koel meet at Rourkela to form the Brahmani, and the Barakar is a tributary of the Damodar.","difficulty":"hard","questionHi":"झारखंड का इस्पात नगर जमशेदपुर, सुवर्णरेखा और किस नदी के संगम पर स्थित है?","optionsHi":["कोयल","खरकई","शंख","बराकर"],"explanationHi":"जमशेदपुर वहाँ बसा है जहाँ खरकई सुवर्णरेखा से मिलती है। शंख और कोयल राउरकेला में मिलकर ब्राह्मणी बनाती हैं और बराकर दामोदर की सहायक नदी है।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-147","question":"Pachnada (Panch Nad), the 'confluence of five rivers' on the Jalaun–Etawah border of Uttar Pradesh, is formed by the Yamuna, Chambal, Kwari, Sindh and the:","options":["Ken","Betwa","Hindon","Pahuj"],"answer":3,"explanation":"The five streams at Pachnada are the Yamuna, Chambal, Kwari, Sindh and Pahuj. The Betwa and Ken join the Yamuna much further downstream, and the Hindon joins it near Delhi–Noida.","difficulty":"very-hard","questionHi":"उत्तर प्रदेश में जालौन–इटावा सीमा पर स्थित पचनदा ('पाँच नदियों का संगम') यमुना, चंबल, क्वारी, सिंध और किस नदी से बनता है?","optionsHi":["केन","बेतवा","हिंडन","पहुज"],"explanationHi":"पचनदा की पाँच धाराएँ यमुना, चंबल, क्वारी, सिंध और पहुज हैं। बेतवा और केन यमुना में बहुत आगे नीचे की ओर मिलती हैं तथा हिंडन दिल्ली–नोएडा के पास मिलती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-148","question":"At Gaya, the Lilajan (Niranjana), on whose bank Bodh Gaya stands, unites with the Mohana to form the river:","options":["Phalgu","Kiul","Punpun","Sone"],"answer":0,"explanation":"The Phalgu is formed at Gaya by the Lilajan (Niranjana) and the Mohana. The Punpun and Sone are separate tributaries of the Ganga, and the Kiul is a different river of south Bihar.","difficulty":"hard","questionHi":"गया में बोधगया के तट पर बहने वाली लीलाजन (निरंजना) मोहना से मिलकर किस नदी का निर्माण करती है?","optionsHi":["फल्गु","किउल","पुनपुन","सोन"],"explanationHi":"गया में लीलाजन (निरंजना) और मोहना के मिलने से फल्गु बनती है। पुनपुन और सोन गंगा की अलग सहायक नदियाँ हैं तथा किउल दक्षिण बिहार की एक भिन्न नदी है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-indian-rivers-149","question":"The Tulbul Navigation Project is planned at the mouth of the Wular lake on the river:","options":["Indus","Kishanganga","Jhelum","Chenab"],"answer":2,"explanation":"Wular is a lake on the Jhelum and the Tulbul project is a navigation lock-cum-control structure at its outlet; the Chenab, Kishanganga and Indus flow elsewhere.","difficulty":"hard","questionHi":"तुलबुल नौवहन परियोजना वुलर झील के मुहाने पर किस नदी पर प्रस्तावित है?","optionsHi":["सिंधु","किशनगंगा","झेलम","चेनाब"],"explanationHi":"वुलर झेलम पर स्थित झील है और तुलबुल परियोजना उसके निकास पर बनने वाली नौवहन लॉक-सह-नियंत्रण संरचना है; चेनाब, किशनगंगा और सिंधु अन्यत्र बहती हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-150","question":"Which of the following hydroelectric projects is wrongly paired with the river on which it stands?","options":["Salal – Chenab","Uri – Jhelum","Nathpa Jhakri – Sutlej","Baglihar – Jhelum"],"answer":3,"explanation":"Baglihar is on the Chenab (Ramban district), not the Jhelum. Salal is also on the Chenab, Uri on the Jhelum and Nathpa Jhakri on the Sutlej.","difficulty":"very-hard","questionHi":"निम्नलिखित में से कौन-सी जलविद्युत परियोजना उस नदी के साथ गलत जोड़ी गई है जिस पर वह स्थित है?","optionsHi":["सलाल – चेनाब","उरी – झेलम","नाथपा झाकड़ी – सतलुज","बगलिहार – झेलम"],"explanationHi":"बगलिहार झेलम पर नहीं, बल्कि चेनाब (रामबन जिला) पर है। सलाल भी चेनाब पर, उरी झेलम पर और नाथपा झाकड़ी सतलुज पर है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-151","question":"Match the ancient (Vedic) name with the modern river. A. Vitasta  B. Asikni  C. Vipasa  D. Shutudri; 1. Sutlej  2. Beas  3. Chenab  4. Jhelum","options":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":1,"explanation":"Vitasta is the Jhelum, Asikni the Chenab, Vipasa the Beas and Shutudri the Sutlej. The wrong options swap the Jhelum–Chenab pair or the Beas–Sutlej pair.","difficulty":"hard","questionHi":"प्राचीन (वैदिक) नाम का आधुनिक नदी से मिलान कीजिए। A. वितस्ता  B. अस्किनी  C. विपाशा  D. शुतुद्री; 1. सतलुज  2. ब्यास  3. चेनाब  4. झेलम","optionsHi":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"explanationHi":"वितस्ता झेलम, अस्किनी चेनाब, विपाशा ब्यास और शुतुद्री सतलुज है। गलत विकल्पों में झेलम–चेनाब या ब्यास–सतलुज का युग्म आपस में बदल दिया गया है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-152","question":"In Bangladesh, the Padma (the Ganga) and the Jamuna (the Brahmaputra) unite near:","options":["Mymensingh","Chandpur","Goalundo","Sylhet"],"answer":2,"explanation":"The Padma and Jamuna meet near Goalundo Ghat; the combined stream later joins the Meghna near Chandpur, so Chandpur is the second confluence, not the first.","difficulty":"hard","questionHi":"बांग्लादेश में पद्मा (गंगा) और जमुना (ब्रह्मपुत्र) किस स्थान के निकट मिलती हैं?","optionsHi":["मयमनसिंह","चाँदपुर","गोआलुंदो","सिलहट"],"explanationHi":"पद्मा और जमुना गोआलुंदो घाट के निकट मिलती हैं; संयुक्त धारा आगे चाँदपुर के पास मेघना से मिलती है, इसलिए चाँदपुर दूसरा संगम है, पहला नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-153","question":"The Spiti river joins the Sutlej at:","options":["Bhuntar","Khab","Tandi","Rampur"],"answer":1,"explanation":"The Spiti meets the Sutlej at Khab in Kinnaur. Tandi is where the Chandra and Bhaga meet, Bhuntar is where the Parvati joins the Beas, and Rampur is only a town on the Sutlej.","difficulty":"very-hard","questionHi":"स्पीति नदी सतलुज से किस स्थान पर मिलती है?","optionsHi":["भुंतर","खाब","तांदी","रामपुर"],"explanationHi":"स्पीति किन्नौर में खाब पर सतलुज से मिलती है। तांदी में चंद्रा और भागा मिलती हैं, भुंतर में पार्वती ब्यास से मिलती है और रामपुर केवल सतलुज तट का एक नगर है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-154","question":"Which of the following barrages is wrongly paired with its river?","options":["Hathnikund – Ganga","Bhimnagar – Kosi","Valmikinagar – Gandak","Tanakpur – Sharda (Mahakali)"],"answer":0,"explanation":"Hathnikund barrage is on the Yamuna in Haryana, where the Western and Eastern Yamuna canals take off. The other three pairings are correct.","difficulty":"very-hard","questionHi":"निम्नलिखित में से कौन-सा बैराज अपनी नदी के साथ गलत जोड़ा गया है?","optionsHi":["हथिनीकुंड – गंगा","भीमनगर – कोसी","वाल्मीकिनगर – गंडक","टनकपुर – शारदा (महाकाली)"],"explanationHi":"हथिनीकुंड बैराज हरियाणा में यमुना पर है, जहाँ से पश्चिमी और पूर्वी यमुना नहरें निकलती हैं। शेष तीनों युग्म सही हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-155","question":"The Upper Ganga Canal, opened in 1854 and associated with the engineer Proby Cautley, takes off from the Ganga near:","options":["Narora","Bijnor","Rishikesh","Haridwar"],"answer":3,"explanation":"The Upper Ganga Canal begins at Haridwar (Bhimgoda). The Lower Ganga Canal, opened later, takes off at Narora, which is the usual trap.","difficulty":"hard","questionHi":"1854 में खुली और इंजीनियर प्रोबी कॉटले से जुड़ी ऊपरी गंगा नहर, गंगा से किस स्थान के निकट निकलती है?","optionsHi":["नरौरा","बिजनौर","ऋषिकेश","हरिद्वार"],"explanationHi":"ऊपरी गंगा नहर हरिद्वार (भीमगोड़ा) से शुरू होती है। बाद में खुली निचली गंगा नहर नरौरा से निकलती है, जो प्रचलित भ्रम है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-156","question":"Kabartal (Kanwar) lake of Begusarai in Bihar, a well-known freshwater oxbow lake, is an abandoned meander of the:","options":["Bagmati","Mahananda","Kosi","Burhi Gandak"],"answer":3,"explanation":"Kanwar lake is a cut-off loop of the Burhi Gandak. The Kosi, Bagmati and Mahananda also shift course in north Bihar, but they did not form this lake.","difficulty":"very-hard","questionHi":"बिहार के बेगूसराय की काबरताल (कांवर) झील, जो एक प्रसिद्ध मीठे पानी की धनुषाकार (ऑक्सबो) झील है, किस नदी का छोड़ा हुआ विसर्प है?","optionsHi":["बागमती","महानंदा","कोसी","बूढ़ी गंडक"],"explanationHi":"कांवर झील बूढ़ी गंडक का कटा हुआ मोड़ है। कोसी, बागमती और महानंदा भी उत्तर बिहार में मार्ग बदलती हैं, पर इस झील का निर्माण उन्होंने नहीं किया।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-157","question":"Which of these Tamil Nadu rivers rises in the Western Ghats, receives rain from both the south-west and north-east monsoons, and is regarded as the state's perennial river?","options":["Ponnaiyar","Palar","Tamiraparani","Vaigai"],"answer":2,"explanation":"The Tamiraparani (Thamirabarani) rises in the Agastyamalai hills and gets rain in both seasons, so it flows through the year into the Gulf of Mannar. The Vaigai, Palar and Ponnaiyar are largely seasonal.","difficulty":"hard","questionHi":"तमिलनाडु की कौन-सी नदी पश्चिमी घाट से निकलती है, दक्षिण-पश्चिम और उत्तर-पूर्व दोनों मानसूनों से वर्षा पाती है और राज्य की बारहमासी नदी मानी जाती है?","optionsHi":["पोन्नैयार","पालार","तामिरपरणी","वैगई"],"explanationHi":"तामिरपरणी अगस्त्यमलै पहाड़ियों से निकलती है और दोनों ऋतुओं में वर्षा पाती है, इसलिए वर्ष भर मन्नार की खाड़ी में बहती है। वैगई, पालार और पोन्नैयार प्रायः मौसमी हैं।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-indian-rivers-158","question":"Although a large part of its basin lies in Madhya Pradesh, the main stream of the Ganga does NOT flow through the state of:","options":["West Bengal","Madhya Pradesh","Jharkhand","Bihar"],"answer":1,"explanation":"The Ganga's main channel flows through Uttarakhand, Uttar Pradesh, Bihar, Jharkhand (briefly, at Sahibganj) and West Bengal; Madhya Pradesh is only part of the basin through the Chambal, Betwa, Ken and Son.","difficulty":"hard","questionHi":"यद्यपि गंगा बेसिन का बड़ा भाग मध्य प्रदेश में है, फिर भी गंगा की मुख्य धारा किस राज्य से होकर नहीं बहती?","optionsHi":["पश्चिम बंगाल","मध्य प्रदेश","झारखंड","बिहार"],"explanationHi":"गंगा की मुख्य धारा उत्तराखंड, उत्तर प्रदेश, बिहार, झारखंड (साहिबगंज में थोड़ी दूर) और पश्चिम बंगाल से बहती है; मध्य प्रदेश चंबल, बेतवा, केन और सोन के कारण केवल बेसिन का भाग है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-159","question":"Which pair of rivers has its source at the Amarkantak plateau?","options":["Narmada and Son","Son and Mahanadi","Narmada and Tapi","Narmada and Mahanadi"],"answer":0,"explanation":"Both the Narmada and the Son (along with the Johila) rise at Amarkantak. The Tapi rises at Multai and the Mahanadi at Sihawa in Chhattisgarh.","difficulty":"moderate","questionHi":"नदियों के किस युग्म का उद्गम अमरकंटक पठार है?","optionsHi":["नर्मदा और सोन","सोन और महानदी","नर्मदा और तापी","नर्मदा और महानदी"],"explanationHi":"नर्मदा और सोन (जोहिला के साथ) दोनों अमरकंटक से निकलती हैं। तापी मुलताई से और महानदी छत्तीसगढ़ के सिहावा से निकलती है।","source":"SSC CGL · State PCS"},
  {"id":"geo-indian-rivers-160","question":"Siliguri, the gateway town of the Darjeeling Himalaya, stands on the bank of the:","options":["Teesta","Torsa","Jaldhaka","Mahananda"],"answer":3,"explanation":"Siliguri lies on the Mahananda, which rises near Darjeeling. The Teesta flows to its east near Jalpaiguri, while the Jaldhaka and Torsa flow farther east.","difficulty":"hard","questionHi":"दार्जिलिंग हिमालय का प्रवेश-द्वार माना जाने वाला नगर सिलीगुड़ी किस नदी के तट पर स्थित है?","optionsHi":["तीस्ता","तोर्सा","जलढाका","महानंदा"],"explanationHi":"सिलीगुड़ी महानंदा के तट पर है, जो दार्जिलिंग के निकट से निकलती है। तीस्ता जलपाईगुड़ी के पास उसके पूर्व में बहती है, जबकि जलढाका और तोर्सा और पूर्व में बहती हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-161","question":"Korba, a major coal and thermal-power centre of Chhattisgarh, lies on the Hasdeo, a tributary of the:","options":["Son","Mahanadi","Narmada","Godavari"],"answer":1,"explanation":"The Hasdeo (Hasdo) joins the Mahanadi after passing Korba, where the Hasdeo Bango dam is built. The Narmada, Godavari and Son are not part of its drainage.","difficulty":"hard","questionHi":"छत्तीसगढ़ का प्रमुख कोयला एवं ताप-विद्युत केंद्र कोरबा हसदेव नदी पर स्थित है, जो किस नदी की सहायक नदी है?","optionsHi":["सोन","महानदी","नर्मदा","गोदावरी"],"explanationHi":"कोरबा से गुज़रने के बाद हसदेव महानदी में मिल जाती है, और यहीं हसदेव बांगो बांध बना है। नर्मदा, गोदावरी और सोन उसके अपवाह तंत्र का भाग नहीं हैं।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-indian-rivers-162","question":"Banswara, the 'City of Hundred Islands' in southern Rajasthan, lies on the:","options":["Mahi","Chambal","Luni","Banas"],"answer":0,"explanation":"The Mahi forms many islets at Banswara, hence the name, before it enters Gujarat. The Chambal flows through eastern Rajasthan and the Luni through the west.","difficulty":"hard","questionHi":"दक्षिणी राजस्थान का 'सौ द्वीपों का नगर' कहलाने वाला बाँसवाड़ा किस नदी पर स्थित है?","optionsHi":["माही","चंबल","लूनी","बनास"],"explanationHi":"गुजरात में प्रवेश करने से पहले माही बाँसवाड़ा में अनेक द्वीप बनाती है, इसी से यह नाम पड़ा। चंबल पूर्वी राजस्थान में और लूनी पश्चिम में बहती है।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-163","question":"Which of these city–river pairs is NOT correct?","options":["Kota – Chambal","Bareilly – Ramganga","Nanded – Krishna","Jammu – Tawi"],"answer":2,"explanation":"Nanded lies on the Godavari, not the Krishna. Kota is on the Chambal, Jammu on the Tawi and Bareilly on the Ramganga.","difficulty":"hard","questionHi":"निम्नलिखित में से कौन-सा नगर–नदी युग्म सही नहीं है?","optionsHi":["कोटा – चंबल","बरेली – रामगंगा","नांदेड़ – कृष्णा","जम्मू – तवी"],"explanationHi":"नांदेड़ गोदावरी पर है, कृष्णा पर नहीं। कोटा चंबल पर, जम्मू तवी पर और बरेली रामगंगा पर स्थित है।","source":"SSC CGL · State PCS"},
  {"id":"geo-indian-rivers-164","question":"According to NCERT, the town that lies on the watershed between the Indus and the Ganga river systems is:","options":["Ludhiana","Karnal","Ambala","Hisar"],"answer":2,"explanation":"Ambala sits on the divide between the Indus system (Ghaggar and the Sutlej side) and the Ganga system (Yamuna side). Hisar, Ludhiana and Karnal lie clearly on one side.","difficulty":"moderate","questionHi":"एनसीईआरटी के अनुसार सिंधु और गंगा नदी तंत्रों के जल विभाजक पर स्थित नगर कौन-सा है?","optionsHi":["लुधियाना","करनाल","अंबाला","हिसार"],"explanationHi":"अंबाला सिंधु तंत्र (घग्गर और सतलुज की ओर) तथा गंगा तंत्र (यमुना की ओर) के विभाजक पर स्थित है। हिसार, लुधियाना और करनाल स्पष्ट रूप से एक ओर पड़ते हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-165","question":"Which of these peninsular rivers flows through exactly three states, Karnataka, Andhra Pradesh and Tamil Nadu, before reaching the Bay of Bengal?","options":["Pennar","Palar","Vellar","Ponnaiyar"],"answer":1,"explanation":"The Palar rises in Karnataka near Nandi hills, crosses a small stretch of Andhra Pradesh and then flows through Tamil Nadu. The Pennar stays in Karnataka and Andhra, the Ponnaiyar in Karnataka and Tamil Nadu, and the Vellar only in Tamil Nadu.","difficulty":"very-hard","questionHi":"प्रायद्वीपीय भारत की कौन-सी नदी बंगाल की खाड़ी में गिरने से पहले ठीक तीन राज्यों, कर्नाटक, आंध्र प्रदेश और तमिलनाडु, से होकर बहती है?","optionsHi":["पेन्नार","पालार","वेल्लार","पोन्नैयार"],"explanationHi":"पालार कर्नाटक में नंदी पहाड़ियों के पास से निकलती है, आंध्र प्रदेश के एक छोटे भाग से गुज़रती है और फिर तमिलनाडु में बहती है। पेन्नार कर्नाटक व आंध्र में, पोन्नैयार कर्नाटक व तमिलनाडु में और वेल्लार केवल तमिलनाडु में बहती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-166","question":"On a meandering river in its lower course, a point bar (a sandy deposit) builds up mainly on the:","options":["middle of the straight reach joining two bends","outer bank of the bend, where flow is fastest","outer bank of the bend, where the channel is deepest","inner bank of the bend, where flow is slowest"],"answer":3,"explanation":"On a bend the fast, deep current hugs the outer bank and erodes it (cut bank), while the slow inner side drops sediment as a point bar.","difficulty":"moderate","questionHi":"निचले मार्ग में विसर्पण करने वाली नदी में बिंदु-रोधिका (बालू का निक्षेप) मुख्यतः कहाँ बनती है?","optionsHi":["दो मोड़ों को जोड़ने वाले सीधे भाग के बीच में","मोड़ के बाहरी किनारे पर, जहाँ प्रवाह सबसे तेज़ होता है","मोड़ के बाहरी किनारे पर, जहाँ धारा सबसे गहरी होती है","मोड़ के भीतरी किनारे पर, जहाँ प्रवाह सबसे धीमा होता है"],"explanationHi":"मोड़ पर तेज़ और गहरी धारा बाहरी किनारे से टकराकर उसे काटती है (कटाव तट), जबकि धीमे भीतरी भाग में अवसाद जमकर बिंदु-रोधिका बनाता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-167","question":"Assertion (A): Natural levees are found along the banks of rivers that regularly flood their plains. Reason (R): When a river overflows, it drops its coarsest sediment first, close to the channel, where its velocity falls suddenly.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"On overflowing, the water slows at the channel edge and deposits the heaviest particles there, building raised banks (levees); finer silt spreads farther as the floodplain.","difficulty":"moderate","questionHi":"अभिकथन (A): जो नदियाँ अपने मैदानों में नियमित रूप से बाढ़ लाती हैं, उनके किनारों पर प्राकृतिक तटबंध (लेवी) पाए जाते हैं। कारण (R): जब नदी उफनती है, तो वह सबसे मोटा अवसाद सबसे पहले धारा के पास गिराती है, जहाँ उसका वेग अचानक घट जाता है।","optionsHi":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"उफान पर पानी धारा के किनारे धीमा पड़ जाता है और भारी कण वहीं जमा करता है, जिससे ऊँचे तट (लेवी) बनते हैं; महीन गाद और दूर बाढ़ मैदान के रूप में फैलती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-168","question":"Arrange these peninsular rivers in increasing order of length: 1. Kaveri  2. Narmada  3. Godavari  4. Tapi","options":["1-4-2-3","4-1-3-2","4-1-2-3","4-2-1-3"],"answer":2,"explanation":"Lengths are roughly Tapi 724 km, Kaveri 800 km, Narmada 1,312 km and Godavari 1,465 km. The Tapi is the shortest, and the Godavari is the longest river wholly within the peninsula's drainage.","difficulty":"hard","questionHi":"इन प्रायद्वीपीय नदियों को लंबाई के बढ़ते क्रम में व्यवस्थित कीजिए: 1. कावेरी  2. नर्मदा  3. गोदावरी  4. तापी","optionsHi":["1-4-2-3","4-1-3-2","4-1-2-3","4-2-1-3"],"explanationHi":"लंबाइयाँ लगभग तापी 724 km, कावेरी 800 km, नर्मदा 1,312 km और गोदावरी 1,465 km हैं। तापी सबसे छोटी और गोदावरी प्रायद्वीप की सबसे लंबी नदी है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-169","question":"Chamba, the old capital of a Himalayan hill kingdom in Himachal Pradesh, stands on the bank of the:","options":["Beas","Ravi","Chenab","Sutlej"],"answer":1,"explanation":"Chamba lies on the Ravi, which drains the Chamba district. The Beas flows through Kullu and Mandi, the Chenab through Lahaul and Kishtwar, and the Sutlej through Kinnaur.","difficulty":"moderate","questionHi":"हिमाचल प्रदेश में एक पर्वतीय रियासत की पुरानी राजधानी चंबा किस नदी के तट पर स्थित है?","optionsHi":["ब्यास","रावी","चेनाब","सतलुज"],"explanationHi":"चंबा रावी के तट पर है, जो चंबा जिले का अपवाह करती है। ब्यास कुल्लू और मंडी से, चेनाब लाहौल और किश्तवाड़ से तथा सतलुज किन्नौर से होकर बहती है।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-170","question":"Pahalgam, the base town for the Amarnath yatra, stands on the Lidder, a tributary of the:","options":["Kishanganga","Chenab","Indus","Jhelum"],"answer":3,"explanation":"The Lidder (Lidar) rises near Kolahoi glacier and joins the Jhelum near Anantnag. The Chenab and Kishanganga are separate river systems, and the Indus lies in Ladakh.","difficulty":"hard","questionHi":"अमरनाथ यात्रा का आधार नगर पहलगाम लिद्दर नदी पर स्थित है, जो किस नदी की सहायक नदी है?","optionsHi":["किशनगंगा","चेनाब","सिंधु","झेलम"],"explanationHi":"लिद्दर कोलाहोई हिमनद के पास से निकलकर अनंतनाग के निकट झेलम में मिलती है। चेनाब और किशनगंगा भिन्न नदी तंत्र की हैं तथा सिंधु लद्दाख में है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-171","question":"Vidisha, the historic city near the Buddhist site of Sanchi, lies on the bank of the:","options":["Betwa","Ken","Chambal","Sindh"],"answer":0,"explanation":"Vidisha stands at the confluence of the Betwa and the Bes. The Ken, Sindh and Chambal flow through other parts of central and northern Madhya Pradesh.","difficulty":"moderate","questionHi":"साँची बौद्ध स्थल के निकट स्थित ऐतिहासिक नगर विदिशा किस नदी के तट पर है?","optionsHi":["बेतवा","केन","चंबल","सिंध"],"explanationHi":"विदिशा बेतवा और बेस नदियों के संगम पर बसा है। केन, सिंध और चंबल मध्य प्रदेश के अन्य भागों से होकर बहती हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-172","question":"At Karad in Maharashtra (the 'Preeti Sangam'), the Krishna is joined by the:","options":["Panchganga","Koyna","Venna","Bhima"],"answer":1,"explanation":"The Koyna meets the Krishna at Karad. The Venna joins earlier near Mahuli (Satara), the Panchganga later near Narsobawadi (Kolhapur), and the Bhima only in the Karnataka–Telangana stretch.","difficulty":"very-hard","questionHi":"महाराष्ट्र के कराड ('प्रीति संगम') में कृष्णा से कौन-सी नदी मिलती है?","optionsHi":["पंचगंगा","कोयना","वेण्णा","भीमा"],"explanationHi":"कराड में कोयना कृष्णा से मिलती है। वेण्णा पहले माहुली (सतारा) के पास, पंचगंगा बाद में नरसोबावाड़ी (कोल्हापुर) के पास और भीमा केवल कर्नाटक–तेलंगाना वाले भाग में मिलती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-173","question":"Match the nuclear power station with the river beside which it stands. A. Kaiga  B. Kakrapar  C. Rawatbhata  D. Narora; 1. Chambal  2. Kali  3. Tapi  4. Ganga","options":["A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1"],"answer":2,"explanation":"Kaiga is on the Kali (Karnataka), Kakrapar on the Tapi (Gujarat), Rawatbhata on the Rana Pratap Sagar reservoir of the Chambal (Rajasthan) and Narora on the Ganga (Uttar Pradesh).","difficulty":"very-hard","questionHi":"परमाणु ऊर्जा केंद्र का उस नदी से मिलान कीजिए जिसके निकट वह स्थित है। A. कैगा  B. काकरापार  C. रावतभाटा  D. नरौरा; 1. चंबल  2. काली  3. तापी  4. गंगा","optionsHi":["A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1"],"explanationHi":"कैगा कर्नाटक में काली पर, काकरापार गुजरात में तापी पर, रावतभाटा राजस्थान में चंबल के राणा प्रताप सागर जलाशय पर और नरौरा उत्तर प्रदेश में गंगा पर स्थित है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-174","question":"The Jim Corbett National Park in Uttarakhand is drained and partly bisected by the:","options":["Ramganga","Sharda","Gandak","Yamuna"],"answer":0,"explanation":"The Ramganga flows through the park and is dammed at Kalagarh, forming the Ramganga reservoir inside it. The Sharda, Yamuna and Gandak flow well away from this park.","difficulty":"moderate","questionHi":"उत्तराखंड का जिम कॉर्बेट राष्ट्रीय उद्यान किस नदी द्वारा अपवाहित है और उसके द्वारा आंशिक रूप से बँटा हुआ है?","optionsHi":["रामगंगा","शारदा","गंडक","यमुना"],"explanationHi":"रामगंगा उद्यान से होकर बहती है और कालागढ़ में बाँधी गई है, जिससे उद्यान के भीतर रामगंगा जलाशय बना है। शारदा, यमुना और गंडक इस उद्यान से बहुत दूर बहती हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-175","question":"Arrange these tributaries by the point at which they join the Krishna, from upstream to downstream: 1. Musi  2. Koyna  3. Tungabhadra  4. Bhima","options":["2-3-4-1","4-2-3-1","2-4-1-3","2-4-3-1"],"answer":3,"explanation":"Going downstream, the Krishna meets the Koyna at Karad, the Bhima near Raichur, the Tungabhadra near Kurnool (Sangameshwaram) and the Musi near Wadapally, below the Nagarjuna Sagar dam.","difficulty":"very-hard","questionHi":"कृष्णा नदी में मिलने के स्थान के आधार पर इन सहायक नदियों को ऊपरी धारा से निचली धारा की ओर व्यवस्थित कीजिए: 1. मूसी  2. कोयना  3. तुंगभद्रा  4. भीमा","optionsHi":["2-3-4-1","4-2-3-1","2-4-1-3","2-4-3-1"],"explanationHi":"नीचे की ओर चलने पर कृष्णा से कोयना कराड में, भीमा रायचूर के पास, तुंगभद्रा कुरनूल (संगमेश्वरम) के पास और मूसी नागार्जुन सागर बाँध के नीचे वाडापल्ली के पास मिलती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-176","question":"Arrange these tributaries by the point at which they join the Godavari, from upstream to downstream: 1. Sabari  2. Manjira  3. Indravati  4. Pranhita","options":["2-3-4-1","2-4-3-1","2-4-1-3","4-2-3-1"],"answer":1,"explanation":"Downstream along the Godavari, the Manjira joins first (Nizamabad region), then the Pranhita near Kaleshwaram, then the Indravati near Bhadrakali, and the Sabari last, near Kunavaram on the Andhra border.","difficulty":"very-hard","questionHi":"गोदावरी में मिलने के स्थान के आधार पर इन सहायक नदियों को ऊपरी धारा से निचली धारा की ओर व्यवस्थित कीजिए: 1. सबरी  2. मंजीरा  3. इंद्रावती  4. प्राणहिता","optionsHi":["2-3-4-1","2-4-3-1","2-4-1-3","4-2-3-1"],"explanationHi":"गोदावरी के निचले प्रवाह में सबसे पहले मंजीरा (निजामाबाद क्षेत्र) मिलती है, फिर कालेश्वरम के पास प्राणहिता, फिर भद्रकाली के पास इंद्रावती और अंत में आंध्र सीमा पर कुनावरम के पास सबरी।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-177","question":"The Beas rises from the Beas Kund glacial area near:","options":["Shipki La","Jalori Pass","Bara Lacha La","Rohtang Pass"],"answer":3,"explanation":"The Beas emerges at Beas Kund near the Rohtang Pass in the Pir Panjal. Bara Lacha La gives rise to the Chandra and Bhaga, and Shipki La is where the Sutlej enters India.","difficulty":"moderate","questionHi":"ब्यास नदी किसके निकट ब्यास कुंड के हिमनद क्षेत्र से निकलती है?","optionsHi":["शिपकी ला","जलोड़ी दर्रा","बारालाचा ला","रोहतांग दर्रा"],"explanationHi":"ब्यास पीर पंजाल में रोहतांग दर्रे के निकट ब्यास कुंड से निकलती है। बारालाचा ला से चंद्रा और भागा निकलती हैं तथा शिपकी ला वह स्थान है जहाँ सतलुज भारत में प्रवेश करती है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-178","question":"The Chandra and the Bhaga, which unite at Tandi to form the Chenab, rise on opposite sides of:","options":["Kunzum La","Rohtang Pass","Bara Lacha La","Zoji La"],"answer":2,"explanation":"Both headstreams originate near Bara Lacha La in Lahaul-Spiti, one on each side, and meet at Tandi. Rohtang is the Beas source area, and Zoji La lies far to the north-west.","difficulty":"hard","questionHi":"चंद्रा और भागा, जो तांदी में मिलकर चेनाब बनाती हैं, किसके विपरीत पक्षों से निकलती हैं?","optionsHi":["कुंजुम ला","रोहतांग दर्रा","बारालाचा ला","ज़ोजी ला"],"explanationHi":"दोनों धाराएँ लाहौल-स्पीति में बारालाचा ला के निकट, एक-एक ओर से निकलकर तांदी में मिलती हैं। रोहतांग ब्यास का उद्गम क्षेत्र है और ज़ोजी ला बहुत उत्तर-पश्चिम में है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-179","question":"Match the doab with the rivers that bound it. A. Bari Doab  B. Rechna Doab  C. Chaj Doab  D. Sind Sagar Doab; 1. Jhelum and Indus  2. Chenab and Jhelum  3. Ravi and Chenab  4. Beas and Ravi","options":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1"],"answer":0,"explanation":"Counting westwards: Bari (Beas–Ravi), Rechna (Ravi–Chenab), Chaj (Chenab–Jhelum) and Sind Sagar (Jhelum–Indus). The Chaj name itself is a contraction of Chenab and Jhelum.","difficulty":"very-hard","questionHi":"दोआब का उसे घेरने वाली नदियों से मिलान कीजिए। A. बारी दोआब  B. रेचना दोआब  C. चाज दोआब  D. सिंध सागर दोआब; 1. झेलम और सिंधु  2. चेनाब और झेलम  3. रावी और चेनाब  4. ब्यास और रावी","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1"],"explanationHi":"पश्चिम की ओर गिनने पर: बारी (ब्यास–रावी), रेचना (रावी–चेनाब), चाज (चेनाब–झेलम) और सिंध सागर (झेलम–सिंधु)। 'चाज' नाम स्वयं चेनाब और झेलम का संक्षिप्त रूप है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-180","question":"The Majha region of Punjab, including Amritsar and Gurdaspur, lies between the rivers:","options":["Sutlej and Ghaggar","Ravi and Chenab","Ravi and Beas","Beas and Sutlej"],"answer":2,"explanation":"Majha is the central Punjab tract between the Ravi and the Beas (the Bari Doab). The Beas–Sutlej tract is Doaba, and the region south of the Sutlej is Malwa.","difficulty":"moderate","questionHi":"अमृतसर और गुरदासपुर सहित पंजाब का माझा क्षेत्र किन नदियों के बीच स्थित है?","optionsHi":["सतलुज और घग्गर","रावी और चेनाब","रावी और ब्यास","ब्यास और सतलुज"],"explanationHi":"माझा पंजाब का मध्य भाग है जो रावी और ब्यास (बारी दोआब) के बीच है। ब्यास–सतलुज का क्षेत्र दोआबा है और सतलुज के दक्षिण का क्षेत्र मालवा है।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-181","question":"All of the following tributaries of the Ganga rise in the Himalaya EXCEPT the:","options":["Kosi","Son","Ghaghara","Gandak"],"answer":1,"explanation":"The Son rises at Amarkantak on the peninsular plateau and joins the Ganga from the south. The Ghaghara, Gandak and Kosi descend from the Himalaya through Nepal.","difficulty":"moderate","questionHi":"गंगा की निम्नलिखित सभी सहायक नदियाँ हिमालय से निकलती हैं, सिवाय:","optionsHi":["कोसी","सोन","घाघरा","गंडक"],"explanationHi":"सोन प्रायद्वीपीय पठार पर अमरकंटक से निकलती है और दक्षिण से गंगा में मिलती है। घाघरा, गंडक और कोसी नेपाल होकर हिमालय से उतरती हैं।","source":"SSC CGL · State PCS"},
  {"id":"geo-indian-rivers-182","question":"Five streams rise at Mahabaleshwar, but only one of the following flows west to the Arabian Sea instead of east. Which one?","options":["Venna","Krishna","Koyna","Savitri"],"answer":3,"explanation":"The Savitri rises at Mahabaleshwar, drops down the Ghats and enters the Arabian Sea near Bankot. The Krishna, Koyna and Venna flow east, towards the Bay of Bengal.","difficulty":"very-hard","questionHi":"महाबलेश्वर से पाँच धाराएँ निकलती हैं, पर निम्नलिखित में से केवल एक पूर्व की बजाय पश्चिम में अरब सागर की ओर बहती है। वह कौन-सी है?","optionsHi":["वेण्णा","कृष्णा","कोयना","सावित्री"],"explanationHi":"सावित्री महाबलेश्वर से निकलकर घाट से नीचे उतरती है और बानकोट के पास अरब सागर में मिलती है। कृष्णा, कोयना और वेण्णा पूर्व की ओर, बंगाल की खाड़ी की दिशा में बहती हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-183","question":"Pandharpur, famous for the Vitthal temple, stands on the Bhima, which is locally called the:","options":["Nira","Chandrabhaga","Mula–Mutha","Indrayani"],"answer":1,"explanation":"At Pandharpur the Bhima takes a crescent-shaped bend and is called the Chandrabhaga. The Indrayani flows past Alandi and Dehu, the Mula–Mutha through Pune, and the Nira is a separate tributary of the Bhima.","difficulty":"hard","questionHi":"विट्ठल मंदिर के लिए प्रसिद्ध पंढरपुर भीमा नदी के तट पर है, जिसे स्थानीय रूप से क्या कहा जाता है?","optionsHi":["नीरा","चंद्रभागा","मुला–मुठा","इंद्रायणी"],"explanationHi":"पंढरपुर में भीमा अर्द्धचंद्राकार मोड़ लेती है और चंद्रभागा कहलाती है। इंद्रायणी आळंदी और देहू से, मुला–मुठा पुणे से बहती है तथा नीरा भीमा की अलग सहायक नदी है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-indian-rivers-184","question":"The Zemu glacier on the Kanchenjunga massif is the principal source of the headwaters of the:","options":["Teesta","Gandak","Kosi","Mahananda"],"answer":0,"explanation":"Meltwater from the Zemu glacier feeds the Teesta through the Lachen Chu. The Pindari glacier feeds the Pindar and the Milam glacier the Gori Ganga, both in Uttarakhand.","difficulty":"hard","questionHi":"कंचनजंगा पर्वत-समूह का ज़ेमू हिमनद किस नदी की प्रमुख उद्गम धाराओं का स्रोत है?","optionsHi":["तीस्ता","गंडक","कोसी","महानंदा"],"explanationHi":"ज़ेमू हिमनद का पिघला जल लाचेन चू के माध्यम से तीस्ता को पोषित करता है। पिंडारी हिमनद पिंडर को और मिलम हिमनद गोरी गंगा को पोषित करता है, दोनों उत्तराखंड में हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-185","question":"The Nubra, a tributary of the Shyok in Ladakh, rises from the:","options":["Gangotri glacier","Zemu glacier","Siachen glacier","Bara Shigri glacier"],"answer":2,"explanation":"The Nubra river flows out of the Siachen glacier in the Karakoram and joins the Shyok. The Gangotri, Zemu and Bara Shigri glaciers feed the Bhagirathi, Teesta and Chandra respectively.","difficulty":"moderate","questionHi":"लद्दाख में शयोक की सहायक नदी नुब्रा किस हिमनद से निकलती है?","optionsHi":["गंगोत्री हिमनद","ज़ेमू हिमनद","सियाचिन हिमनद","बड़ा शिगरी हिमनद"],"explanationHi":"नुब्रा नदी काराकोरम में सियाचिन हिमनद से निकलकर शयोक में मिलती है। गंगोत्री, ज़ेमू और बड़ा शिगरी हिमनद क्रमशः भागीरथी, तीस्ता और चंद्रा को पोषित करते हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-186","question":"Match the ancient name with the modern river. A. Charmanvati  B. Vetravati  C. Kausiki  D. Sarayu; 1. Chambal  2. Betwa  3. Kosi  4. Ghaghara","options":["A-2, B-1, C-3, D-4","A-1, B-2, C-4, D-3","A-1, B-3, C-2, D-4","A-1, B-2, C-3, D-4"],"answer":3,"explanation":"Charmanvati is the Chambal, Vetravati the Betwa, Kausiki the Kosi and Sarayu the Ghaghara. The distractors swap neighbouring rivers of the Yamuna or Ganga systems.","difficulty":"hard","questionHi":"प्राचीन नाम का आधुनिक नदी से मिलान कीजिए। A. चर्मण्वती  B. वेत्रवती  C. कौशिकी  D. सरयू; 1. चंबल  2. बेतवा  3. कोसी  4. घाघरा","optionsHi":["A-2, B-1, C-3, D-4","A-1, B-2, C-4, D-3","A-1, B-3, C-2, D-4","A-1, B-2, C-3, D-4"],"explanationHi":"चर्मण्वती चंबल, वेत्रवती बेतवा, कौशिकी कोसी और सरयू घाघरा है। गलत विकल्पों में यमुना या गंगा तंत्र की पास-पास की नदियाँ आपस में बदल दी गई हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-187","question":"Match the Greek name used by Alexander's historians with the modern river. A. Hydaspes  B. Acesines  C. Hydraotes  D. Hyphasis; 1. Beas  2. Ravi  3. Chenab  4. Jhelum","options":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1"],"answer":0,"explanation":"Hydaspes is the Jhelum, Acesines the Chenab, Hydraotes the Ravi and Hyphasis the Beas, the last river Alexander reached before his army refused to go farther east.","difficulty":"hard","questionHi":"सिकंदर के इतिहासकारों द्वारा प्रयुक्त यूनानी नाम का आधुनिक नदी से मिलान कीजिए। A. हाइडैस्पीज़  B. एसेसीनीज़  C. हाइड्राओटीज़  D. हाइफ़ैसिस; 1. ब्यास  2. रावी  3. चेनाब  4. झेलम","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1"],"explanationHi":"हाइडैस्पीज़ झेलम, एसेसीनीज़ चेनाब, हाइड्राओटीज़ रावी और हाइफ़ैसिस ब्यास है; ब्यास अंतिम नदी थी जहाँ सिकंदर पहुँचा, उसके बाद सेना ने पूर्व की ओर बढ़ने से इनकार कर दिया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-188","question":"Which of these dams is regarded as the largest masonry dam in the world?","options":["Tehri","Bhakra","Hirakud","Nagarjuna Sagar"],"answer":3,"explanation":"Nagarjuna Sagar on the Krishna is built of stone masonry and is famed as the world's largest masonry dam. Bhakra is a concrete gravity dam, Hirakud an earth-and-concrete dam and Tehri an earth-and-rockfill dam.","difficulty":"moderate","questionHi":"इनमें से किस बाँध को विश्व का सबसे बड़ा चिनाई (मेसनरी) बाँध माना जाता है?","optionsHi":["टिहरी","भाखड़ा","हीराकुड","नागार्जुन सागर"],"explanationHi":"कृष्णा पर बना नागार्जुन सागर पत्थर की चिनाई से बना है और विश्व का सबसे बड़ा चिनाई बाँध माना जाता है। भाखड़ा कंक्रीट गुरुत्व बाँध, हीराकुड मिट्टी-कंक्रीट बाँध और टिहरी मिट्टी-शैल भराव बाँध है।","source":"SSC CGL · State PCS"},
  {"id":"geo-indian-rivers-189","question":"The Pandoh dam in Himachal Pradesh diverts water of the Beas through a tunnel to the reservoir of the:","options":["Ranjit Sagar dam","Pong dam","Bhakra dam (Gobind Sagar)","Chamera dam"],"answer":2,"explanation":"Pandoh sends Beas water through the Beas–Sutlej Link tunnel via the Dehar power house into the Gobind Sagar on the Sutlej. Pong is on the Beas itself, and Ranjit Sagar and Chamera are on the Ravi.","difficulty":"very-hard","questionHi":"हिमाचल प्रदेश का पंडोह बाँध ब्यास के जल को सुरंग द्वारा किस बाँध के जलाशय में पहुँचाता है?","optionsHi":["रंजीत सागर बाँध","पोंग बाँध","भाखड़ा बाँध (गोबिंद सागर)","चमेरा बाँध"],"explanationHi":"पंडोह ब्यास–सतलुज लिंक सुरंग से देहर विद्युत गृह होते हुए ब्यास का जल सतलुज के गोबिंद सागर में भेजता है। पोंग स्वयं ब्यास पर है तथा रंजीत सागर और चमेरा रावी पर हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-190","question":"Alexander's army refused to march farther east after reaching the Hyphasis, which today is the:","options":["Sutlej","Beas","Jhelum","Ravi"],"answer":1,"explanation":"The Hyphasis is the Beas, the easternmost of the five Punjab rivers Alexander reached. The Jhelum (Hydaspes) was where he fought Porus, and the Ravi lies to its west.","difficulty":"moderate","questionHi":"सिकंदर की सेना ने हाइफ़ैसिस पहुँचने के बाद और पूर्व की ओर बढ़ने से इनकार कर दिया; आज यह नदी कौन-सी है?","optionsHi":["सतलुज","ब्यास","झेलम","रावी"],"explanationHi":"हाइफ़ैसिस ब्यास है, जो सिकंदर के पहुँचने वाली पंजाब की पाँच नदियों में सबसे पूर्वी है। झेलम (हाइडैस्पीज़) पर उसने पोरस से युद्ध किया था और रावी उसके पश्चिम में है।","source":"SSC CGL · State PCS"},
  {"id":"geo-indian-rivers-191","question":"The Panchganga, on which Kolhapur stands, is formed by the union of five streams. Which of these is NOT one of them?","options":["Kumbhi","Tulshi","Kasari","Koyna"],"answer":3,"explanation":"The Panchganga is made up of the Kasari, Kumbhi, Tulshi, Bhogavati and the (hidden) Saraswati. The Koyna is a separate tributary of the Krishna that joins it at Karad.","difficulty":"hard","questionHi":"कोल्हापुर जिस पंचगंगा के तट पर बसा है, वह पाँच धाराओं के मिलने से बनी है। इनमें से कौन-सी उनमें शामिल नहीं है?","optionsHi":["कुंभी","तुलशी","कासारी","कोयना"],"explanationHi":"पंचगंगा कासारी, कुंभी, तुलशी, भोगावती और (लुप्त) सरस्वती से मिलकर बनी है। कोयना कृष्णा की अलग सहायक नदी है जो कराड में उससे मिलती है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-indian-rivers-192","question":"The Drishadvati of the Rigvedic hymns is usually identified with the present-day:","options":["Markanda","Chautang (Chitang)","Tangri","Ghaggar"],"answer":1,"explanation":"Scholars most often equate the Drishadvati with the Chautang, a seasonal stream of Haryana and Rajasthan that was once a tributary of the Saraswati–Ghaggar. The Markanda and Tangri are separate Ghaggar tributaries, and the Ghaggar is itself linked to the Saraswati.","difficulty":"very-hard","questionHi":"ऋग्वैदिक सूक्तों की दृषद्वती की पहचान प्रायः वर्तमान किस नदी से की जाती है?","optionsHi":["मारकंडा","चौतांग (चितांग)","टांगरी","घग्गर"],"explanationHi":"विद्वान प्रायः दृषद्वती को चौतांग से जोड़ते हैं, जो हरियाणा और राजस्थान की एक मौसमी धारा है और कभी सरस्वती–घग्गर की सहायक थी। मारकंडा और टांगरी घग्गर की अलग सहायक नदियाँ हैं और घग्गर स्वयं सरस्वती से जोड़ी जाती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-193","question":"The Bogibeel Bridge, India's longest rail-cum-road bridge, spans the Brahmaputra near:","options":["Dibrugarh","Guwahati","Jorhat","Tezpur"],"answer":0,"explanation":"Bogibeel connects the Dibrugarh side on the south bank with the Dhemaji–Dhola side on the north bank. Tezpur, Guwahati and Jorhat have other Brahmaputra crossings.","difficulty":"moderate","questionHi":"भारत का सबसे लंबा रेल-सह-सड़क पुल, बोगीबील पुल, ब्रह्मपुत्र पर किस नगर के निकट है?","optionsHi":["डिब्रूगढ़","गुवाहाटी","जोरहाट","तेजपुर"],"explanationHi":"बोगीबील दक्षिणी तट के डिब्रूगढ़ क्षेत्र को उत्तरी तट के धेमाजी–ढोला क्षेत्र से जोड़ता है। तेजपुर, गुवाहाटी और जोरहाट में ब्रह्मपुत्र पर अन्य पुल हैं।","source":"SSC CGL · State PCS"},
  {"id":"geo-indian-rivers-194","question":"Paradip port, on the coast of Odisha, lies near the mouth of the:","options":["Baitarani","Brahmani","Mahanadi","Subarnarekha"],"answer":2,"explanation":"Paradip is on the Mahanadi's estuarine coast, near the Jatadhari creek. The Brahmani and Baitarani meet the sea farther north near Dhamra, and the Subarnarekha reaches it near the Odisha–Bengal border.","difficulty":"hard","questionHi":"ओडिशा तट पर स्थित पारादीप बंदरगाह किस नदी के मुहाने के निकट है?","optionsHi":["बैतरणी","ब्राह्मणी","महानदी","सुवर्णरेखा"],"explanationHi":"पारादीप महानदी के ज्वारनदमुख वाले तट पर, जटाधारी खाड़ी के निकट है। ब्राह्मणी और बैतरणी और उत्तर में धामरा के पास तथा सुवर्णरेखा ओडिशा–बंगाल सीमा के पास समुद्र में मिलती है।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-195","question":"Mormugao, the main port of Goa, lies at the mouth of the:","options":["Zuari","Kali","Sharavathi","Mandovi"],"answer":0,"explanation":"Mormugao stands on a peninsula at the entrance of the Zuari estuary. The Mandovi's mouth is at Panaji, farther north, while the Sharavathi and Kali enter the sea in Karnataka.","difficulty":"hard","questionHi":"गोवा का प्रमुख बंदरगाह मोरमुगाओ किस नदी के मुहाने पर स्थित है?","optionsHi":["ज़ुआरी","काली","शरावती","मांडवी"],"explanationHi":"मोरमुगाओ ज़ुआरी के ज्वारनदमुख के प्रवेश पर एक प्रायद्वीप पर बसा है। मांडवी का मुहाना और उत्तर में पणजी पर है, जबकि शरावती और काली कर्नाटक में समुद्र से मिलती हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-196","question":"The island of Srirangam, with its famous temple, is formed where the Kaveri splits into two channels: the Kaveri and the:","options":["Noyyal","Bhavani","Amaravati","Kollidam (Coleroon)"],"answer":3,"explanation":"Near Tiruchirappalli the Kaveri divides into the Kaveri and the Kollidam, enclosing Srirangam island. The Bhavani, Amaravati and Noyyal are tributaries that join from the west or south.","difficulty":"hard","questionHi":"प्रसिद्ध मंदिर वाला श्रीरंगम द्वीप वहाँ बना है जहाँ कावेरी दो धाराओं में बँटती है: कावेरी और:","optionsHi":["नोय्यल","भवानी","अमरावती","कोल्लिदम (कोलेरून)"],"explanationHi":"तिरुचिरापल्ली के निकट कावेरी कावेरी और कोल्लिदम में बँट जाती है, जिनके बीच श्रीरंगम द्वीप है। भवानी, अमरावती और नोय्यल पश्चिम या दक्षिण से मिलने वाली सहायक नदियाँ हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-197","question":"The Somasila dam, near Nellore in Andhra Pradesh, is built across the:","options":["Krishna","Swarnamukhi","Pennar","Godavari"],"answer":2,"explanation":"Somasila is on the Pennar (Penna), supplying the Nellore region. The Krishna and Godavari have their own major dams, and the Swarnamukhi is a small coastal river near Tirupati.","difficulty":"hard","questionHi":"आंध्र प्रदेश में नेल्लोर के निकट स्थित सोमशिला बाँध किस नदी पर बना है?","optionsHi":["कृष्णा","स्वर्णमुखी","पेन्नार","गोदावरी"],"explanationHi":"सोमशिला पेन्नार (पेन्ना) पर है और नेल्लोर क्षेत्र को जल देता है। कृष्णा और गोदावरी पर अपने बड़े बाँध हैं तथा स्वर्णमुखी तिरुपति के निकट की एक छोटी तटीय नदी है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-indian-rivers-198","question":"The Mayurakshi project, with a dam at Massanjore and a barrage at Tilpara, harnesses which river?","options":["Damodar","Mayurakshi","Ajay","Kangsabati"],"answer":1,"explanation":"Massanjore (Canada dam) in Jharkhand and the Tilpara barrage in Birbhum, West Bengal, are on the Mayurakshi. The Ajay, Kangsabati and Damodar have their own projects.","difficulty":"very-hard","questionHi":"मसानजोर में बाँध और तिलपाड़ा में बैराज वाली मयूराक्षी परियोजना किस नदी का उपयोग करती है?","optionsHi":["दामोदर","मयूराक्षी","अजय","कंसावती"],"explanationHi":"झारखंड का मसानजोर (कनाडा बाँध) और पश्चिम बंगाल के बीरभूम का तिलपाड़ा बैराज मयूराक्षी पर हैं। अजय, कंसावती और दामोदर की अपनी परियोजनाएँ हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-199","question":"The Karmanasa, traditionally regarded as an inauspicious river, forms part of the boundary between:","options":["Bihar and Jharkhand","Madhya Pradesh and Uttar Pradesh","Uttar Pradesh and Bihar","Uttar Pradesh and Uttarakhand"],"answer":2,"explanation":"The Karmanasa rises in the Kaimur hills and, for much of its lower course, separates Uttar Pradesh (Chandauli, Ghazipur) from Bihar before joining the Ganga near Buxar.","difficulty":"very-hard","questionHi":"परंपरागत रूप से अशुभ मानी जाने वाली कर्मनाशा नदी किन दो राज्यों की सीमा का भाग बनाती है?","optionsHi":["बिहार और झारखंड","मध्य प्रदेश और उत्तर प्रदेश","उत्तर प्रदेश और बिहार","उत्तर प्रदेश और उत्तराखंड"],"explanationHi":"कर्मनाशा कैमूर पहाड़ियों से निकलती है और अपने निचले मार्ग में अधिकांशतः उत्तर प्रदेश (चंदौली, गाज़ीपुर) को बिहार से अलग करती हुई बक्सर के पास गंगा में मिलती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-200","question":"In southern Tibet, the Tsangpo (the upper Brahmaputra) flows mainly:","options":["from east to west, parallel to the Himalaya","from north to south, across the Himalaya","from south to north, towards the Kunlun","from west to east, parallel to the Himalaya"],"answer":3,"explanation":"The Tsangpo runs roughly 1,700 km west to east along the southern edge of the Tibetan plateau before turning around the Namcha Barwa massif and cutting south through the Himalaya as the Siang.","difficulty":"moderate","questionHi":"दक्षिणी तिब्बत में त्सांगपो (ऊपरी ब्रह्मपुत्र) मुख्यतः किस दिशा में बहती है?","optionsHi":["पूर्व से पश्चिम की ओर, हिमालय के समानांतर","उत्तर से दक्षिण की ओर, हिमालय को काटते हुए","दक्षिण से उत्तर की ओर, कुनलुन की ओर","पश्चिम से पूर्व की ओर, हिमालय के समानांतर"],"explanationHi":"त्सांगपो तिब्बती पठार के दक्षिणी किनारे पर लगभग 1,700 km पश्चिम से पूर्व बहती है, फिर नामचा बरवा पर्वत-समूह का चक्कर लगाकर सियांग के रूप में हिमालय को काटते हुए दक्षिण की ओर मुड़ जाती है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-201","question":"The Brahmaputra Board, set up under an Act of Parliament in 1980 for planning the control of floods and use of the river's water, is headquartered at:","options":["Guwahati","Kolkata","Dibrugarh","Shillong"],"answer":0,"explanation":"The Brahmaputra Board Act, 1980 created the Board with its headquarters at Guwahati, the main city on the river. Shillong, Dibrugarh and Kolkata host other regional bodies but not this one.","difficulty":"moderate","questionHi":"बाढ़ नियंत्रण की योजना बनाने और नदी के जल के उपयोग हेतु 1980 में संसद के अधिनियम द्वारा गठित ब्रह्मपुत्र बोर्ड का मुख्यालय कहाँ है?","optionsHi":["गुवाहाटी","कोलकाता","डिब्रूगढ़","शिलांग"],"explanationHi":"ब्रह्मपुत्र बोर्ड अधिनियम, 1980 से बने बोर्ड का मुख्यालय नदी के मुख्य नगर गुवाहाटी में है। शिलांग, डिब्रूगढ़ और कोलकाता में अन्य क्षेत्रीय निकाय हैं, यह बोर्ड नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-202","question":"Consider the following statements about the Indus Waters Treaty (1960). I. The Ravi, Beas and Sutlej were allotted to India for its use. II. India may build run-of-river hydropower projects on the western rivers within the treaty's design limits. III. The treaty was signed at Karachi, with the World Bank signing in a limited capacity. IV. The treaty bars India from any irrigation use of the Indus, Jhelum and Chenab. How many statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is false: India may use the western rivers for domestic use, limited irrigation, and run-of-river power, though it cannot divert or significantly store their water.","difficulty":"very-hard","questionHi":"सिंधु जल संधि (1960) के संबंध में निम्नलिखित कथनों पर विचार कीजिए। I. रावी, ब्यास और सतलुज भारत को उसके उपयोग के लिए आवंटित की गईं। II. भारत संधि की डिज़ाइन सीमाओं के भीतर पश्चिमी नदियों पर रन-ऑफ-द-रिवर जलविद्युत परियोजनाएँ बना सकता है। III. संधि पर कराची में हस्ताक्षर हुए, और विश्व बैंक ने सीमित हैसियत से हस्ताक्षर किए। IV. संधि भारत को सिंधु, झेलम और चेनाब के किसी भी सिंचाई उपयोग से रोकती है। कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: भारत पश्चिमी नदियों का घरेलू उपयोग, सीमित सिंचाई और रन-ऑफ-द-रिवर विद्युत के लिए उपयोग कर सकता है, पर उनका जल मोड़ या बड़े पैमाने पर संग्रहित नहीं कर सकता।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-203","question":"Gorakhpur in eastern Uttar Pradesh stands on the bank of the:","options":["Gandak","Rapti","Ghaghara","Gomti"],"answer":1,"explanation":"Gorakhpur lies on the Rapti (Rohin joins it nearby), a tributary of the Ghaghara. The Gandak flows farther east along the Bihar border, and the Ghaghara and Gomti pass other districts.","difficulty":"hard","questionHi":"पूर्वी उत्तर प्रदेश का गोरखपुर किस नदी के तट पर स्थित है?","optionsHi":["गंडक","राप्ती","घाघरा","गोमती"],"explanationHi":"गोरखपुर राप्ती के तट पर है (रोहिन निकट ही उसमें मिलती है), जो घाघरा की सहायक नदी है। गंडक बिहार सीमा के साथ और पूर्व में बहती है तथा घाघरा और गोमती अन्य जिलों से गुज़रती हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-204","question":"Muzaffarpur, the litchi-growing town of north Bihar, lies on the bank of the:","options":["Punpun","Kosi","Burhi Gandak","Son"],"answer":2,"explanation":"Muzaffarpur stands on the Burhi Gandak (Little Gandak). The Kosi flows far to the east, while the Son and Punpun are south-Bihar rivers south of the Ganga.","difficulty":"hard","questionHi":"उत्तर बिहार का लीची उत्पादक नगर मुज़फ़्फ़रपुर किस नदी के तट पर स्थित है?","optionsHi":["पुनपुन","कोसी","बूढ़ी गंडक","सोन"],"explanationHi":"मुज़फ़्फ़रपुर बूढ़ी गंडक (छोटी गंडक) के तट पर है। कोसी बहुत पूर्व में बहती है, जबकि सोन और पुनपुन गंगा के दक्षिण की बिहार की नदियाँ हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-205","question":"Raipur, the capital of Chhattisgarh, stands on the bank of the Kharun, a tributary of the:","options":["Hasdeo","Indravati","Arpa","Shivnath"],"answer":3,"explanation":"The Kharun rises in Durg district, passes Raipur and joins the Shivnath, itself a tributary of the Mahanadi. The Hasdeo, Arpa and Indravati are separate rivers.","difficulty":"hard","questionHi":"छत्तीसगढ़ की राजधानी रायपुर खारून नदी के तट पर है, जो किस नदी की सहायक नदी है?","optionsHi":["हसदेव","इंद्रावती","अरपा","शिवनाथ"],"explanationHi":"खारून दुर्ग जिले से निकलकर रायपुर से गुज़रती है और शिवनाथ में मिलती है, जो स्वयं महानदी की सहायक है। हसदेव, अरपा और इंद्रावती अलग नदियाँ हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-206","question":"Mandi, the 'Chhoti Kashi' of Himachal Pradesh, stands on the bank of the:","options":["Chenab","Beas","Ravi","Sutlej"],"answer":1,"explanation":"Mandi, with its many old temples, stands on the Beas just below the Pandoh dam. The Sutlej flows through Rampur and Bilaspur, the Ravi through Chamba and the Chenab through Lahaul.","difficulty":"moderate","questionHi":"हिमाचल प्रदेश की 'छोटी काशी' कहलाने वाला मंडी किस नदी के तट पर स्थित है?","optionsHi":["चेनाब","ब्यास","रावी","सतलुज"],"explanationHi":"अनेक प्राचीन मंदिरों वाला मंडी पंडोह बाँध के ठीक नीचे ब्यास के तट पर है। सतलुज रामपुर और बिलासपुर से, रावी चंबा से तथा चेनाब लाहौल से बहती है।","source":"SSC CGL · State PCS"},
  {"id":"geo-indian-rivers-207","question":"Dehradun lies in the Doon valley, which is enclosed between the:","options":["Ganga and Yamuna","Ganga and Ramganga","Yamuna and Tons","Ganga and Sharda"],"answer":0,"explanation":"The Doon valley lies between the Yamuna on the west and the Ganga on the east, in the Shiwalik–Lesser Himalaya foothills. Ramganga and Sharda lie much farther east.","difficulty":"moderate","questionHi":"देहरादून दून घाटी में स्थित है, जो किन नदियों के बीच घिरी हुई है?","optionsHi":["गंगा और यमुना","गंगा और रामगंगा","यमुना और टोंस","गंगा और शारदा"],"explanationHi":"दून घाटी शिवालिक–लघु हिमालय की तलहटी में पश्चिम में यमुना और पूर्व में गंगा के बीच है। रामगंगा और शारदा बहुत पूर्व में हैं।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-208","question":"The Rangit, which rises from the Rathong glacier in Sikkim, is a tributary of the:","options":["Jaldhaka","Mahananda","Torsa","Teesta"],"answer":3,"explanation":"The Rangit (Rangeet) joins the Teesta at Triveni near the Sikkim–West Bengal border. The Torsa, Mahananda and Jaldhaka are independent rivers of the north Bengal Himalayan foothills.","difficulty":"hard","questionHi":"सिक्किम के रथोंग हिमनद से निकलने वाली रंगित किस नदी की सहायक नदी है?","optionsHi":["जलढाका","महानंदा","तोर्सा","तीस्ता"],"explanationHi":"रंगित (रंगीत) सिक्किम–पश्चिम बंगाल सीमा के निकट त्रिवेणी में तीस्ता से मिलती है। तोर्सा, महानंदा और जलढाका उत्तर बंगाल की तलहटी की स्वतंत्र नदियाँ हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-209","question":"The Doyang reservoir in Nagaland, known for the annual roosting of Amur falcons, lies on the Doyang, a tributary of the:","options":["Kopili","Dhansiri","Dikhow","Barak"],"answer":1,"explanation":"The Doyang flows north from Nagaland and joins the Dhansiri (South) in Assam. The Kopili, Barak and Dikhow are separate river systems.","difficulty":"very-hard","questionHi":"नागालैंड का डोयांग जलाशय, जो अमूर बाज़ों के वार्षिक विश्राम के लिए प्रसिद्ध है, डोयांग नदी पर है, जो किस नदी की सहायक है?","optionsHi":["कोपिली","धनसिरी","दिखो","बराक"],"explanationHi":"डोयांग नागालैंड से उत्तर की ओर बहकर असम में धनसिरी (दक्षिण) में मिलती है। कोपिली, बराक और दिखो अलग नदी तंत्रों की हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-210","question":"The Dawki river in Meghalaya, famed for its crystal-clear water, is the:","options":["Kynshi","Simsang","Umngot","Myntdu"],"answer":2,"explanation":"The Umngot flows past Dawki on the border with Bangladesh and is known for its transparency. The Myntdu, Kynshi and Simsang are other Meghalaya rivers.","difficulty":"hard","questionHi":"मेघालय की डॉकी नदी, जो अपने स्फटिक जैसे निर्मल जल के लिए प्रसिद्ध है, कौन-सी है?","optionsHi":["किंशी","सिमसंग","उमंगोट","म्यंतडू"],"explanationHi":"उमंगोट बांग्लादेश सीमा पर डॉकी से होकर बहती है और अपनी पारदर्शिता के लिए जानी जाती है। म्यंतडू, किंशी और सिमसंग मेघालय की अन्य नदियाँ हैं।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-indian-rivers-211","question":"The Kali Gandaki flows through a famous gorge cut between the mountains:","options":["Dhaulagiri and Annapurna","Kanchenjunga and Makalu","Everest and Lhotse","Nanda Devi and Kamet"],"answer":0,"explanation":"The Kali Gandaki, a headstream of the Gandak, has cut a deep gorge between Dhaulagiri and Annapurna in Nepal. The other pairs belong to the Kosi or Kumaon Himalayan systems.","difficulty":"hard","questionHi":"काली गंडकी किन पर्वतों के बीच कटी एक प्रसिद्ध घाटी (गॉर्ज) से होकर बहती है?","optionsHi":["धौलागिरि और अन्नपूर्णा","कंचनजंगा और मकालू","एवरेस्ट और ल्होत्से","नंदा देवी और कामेट"],"explanationHi":"गंडक की एक उद्गम धारा काली गंडकी ने नेपाल में धौलागिरि और अन्नपूर्णा के बीच गहरी घाटी काटी है। अन्य जोड़े कोसी या कुमाऊँ हिमालय के तंत्रों से जुड़े हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-212","question":"The Bharathapuzha, the second-longest river of Kerala, is also known as the:","options":["Pamba","Kabini","Chaliyar","Nila"],"answer":3,"explanation":"The Bharathapuzha is called the Nila and reaches the Arabian Sea near Ponnani. The Pamba (Sabarimala) and Chaliyar are other west-flowing rivers, and the Kabini flows east to the Kaveri.","difficulty":"moderate","questionHi":"केरल की दूसरी सबसे लंबी नदी भरतपुझा को और किस नाम से जाना जाता है?","optionsHi":["पंबा","कबिनी","चालियार","निला"],"explanationHi":"भरतपुझा को निला कहा जाता है और यह पोन्नानी के निकट अरब सागर में गिरती है। पंबा (सबरीमला) और चालियार पश्चिम की ओर बहने वाली अन्य नदियाँ हैं तथा कबिनी पूर्व में कावेरी की ओर बहती है।","source":"State PCS · SSC CGL"},
  {"id":"geo-indian-rivers-213","question":"Mangaluru (Mangalore) lies on the coast between the estuaries of two rivers. Which pair?","options":["Kali and Gangavali","Netravati and Gurupura","Sharavathi and Aghanashini","Chakra and Sita"],"answer":1,"explanation":"Mangaluru sits between the Netravati on the south and the Gurupura (Phalguni) on the north, which form backwaters near the city. The other pairs belong to coastal Karnataka but not to Mangaluru.","difficulty":"very-hard","questionHi":"मंगलुरु (मंगलौर) तट पर दो नदियों के मुहानों के बीच स्थित है। वह युग्म कौन-सा है?","optionsHi":["काली और गंगावली","नेत्रावती और गुरुपुरा","शरावती और अघनाशिनी","चक्रा और सीता"],"explanationHi":"मंगलुरु दक्षिण में नेत्रावती और उत्तर में गुरुपुरा (फाल्गुनी) के बीच बसा है, जो नगर के पास अप्रवाही जल (बैकवाटर) बनाती हैं। अन्य युग्म तटीय कर्नाटक के हैं, पर मंगलुरु के नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-indian-rivers-214","question":"The Tehri dam is built just below the confluence of the Bhagirathi and the:","options":["Bhilangana","Dhauliganga","Pindar","Mandakini"],"answer":0,"explanation":"Tehri stands where the Bhilangana joins the Bhagirathi; the dam is on the Bhagirathi in Uttarakhand. The Mandakini, Dhauliganga and Pindar are Alaknanda-system streams.","difficulty":"hard","questionHi":"टिहरी बाँध भागीरथी और किस नदी के संगम के ठीक नीचे बना है?","optionsHi":["भिलंगना","धौलीगंगा","पिंडर","मंदाकिनी"],"explanationHi":"टिहरी वहाँ है जहाँ भिलंगना भागीरथी में मिलती है; बाँध उत्तराखंड में भागीरथी पर है। मंदाकिनी, धौलीगंगा और पिंडर अलकनंदा तंत्र की धाराएँ हैं।","source":"UPSC Prelims · SSC CGL"},
];

export default questions;
